def env_flag(*names: str, default: bool = False) -> bool:
    for name in names:
        value = os.getenv(name)
        if value is None:
            continue
        parsed = parse_env_bool(value)
        if parsed is not None:
            return parsed
    return default


def env_flag_value(*names: str) -> bool | None:
    for name in names:
        value = os.getenv(name)
        if value is None:
            continue
        parsed = parse_env_bool(value)
        if parsed is not None:
            return parsed
    return None


def parse_env_bool(value: str) -> bool | None:
    normalized = value.strip().lower()
    if normalized in TRUE_ENV_VALUES:
        return True
    if normalized in FALSE_ENV_VALUES:
        return False
    return None


def env_custom_theme_name(default: str = DEFAULT_CUSTOM_THEME_NAME) -> str:
    name = os.getenv("AGENT_PBX_TUI_CUSTOM_THEME_NAME", default).strip()
    return name or default


def env_color(name: str, default: str) -> str:
    value = os.getenv(name, "").strip()
    if not value:
        return default
    try:
        Color.parse(value)
    except ColorParseError:
        return default
    return value


def env_custom_palette() -> dict[str, str]:
    return {
        key: env_color(
            f"AGENT_PBX_TUI_CUSTOM_{key.upper()}",
            DEFAULT_CUSTOM_PALETTE[key],
        )
        for key in THEME_KEYS
    }


def is_custom_theme_selector(theme: str, custom_name: str) -> bool:
    normalized = theme.strip().lower()
    return normalized in {
        custom_name.strip().lower(),
        DEFAULT_CUSTOM_THEME_NAME,
        "leet",
    }


def is_minimal_theme_selector(theme: str) -> bool:
    normalized = theme.strip().lower().replace("_", "-")
    return normalized in {
        MINIMAL_TUI_THEME,
        "basic",
        "black-white",
        "blackwhite",
        "bw",
        "compat",
        "compatible",
        "mono",
        "monochrome",
    }


def is_accessible_theme_selector(theme: str) -> bool:
    normalized = theme.strip().lower().replace("_", "-")
    return normalized in {
        ACCESSIBLE_TUI_THEME,
        "accessible",
        "deuteranopia",
    }


def is_default_theme_selector(theme: str) -> bool:
    normalized = theme.strip().lower().replace("_", "-")
    return normalized in {
        "",
        "default",
        DEFAULT_TUI_THEME,
        "github",
        "github dark",
        "github-dark",
    }


def env_theme(
    default: str = DEFAULT_TUI_THEME, custom_name: str | None = None
) -> str:
    override = env_theme_value(custom_name=custom_name)
    return override or default


def env_theme_value(custom_name: str | None = None) -> str | None:
    resolved_custom_name = custom_name or env_custom_theme_name()
    if env_flag_value("AGENT_PBX_TUI_1337"):
        return resolved_custom_name
    if "AGENT_PBX_TUI_THEME" not in os.environ:
        return None
    theme = os.getenv("AGENT_PBX_TUI_THEME", "").strip().lower()
    if is_custom_theme_selector(theme, resolved_custom_name):
        return resolved_custom_name
    if is_minimal_theme_selector(theme):
        return MINIMAL_TUI_THEME
    if is_accessible_theme_selector(theme):
        return ACCESSIBLE_TUI_THEME
    if is_default_theme_selector(theme):
        return DEFAULT_TUI_THEME
    return None


def resolve_layout(layout_name: str) -> str:
    normalized = layout_name.strip().lower().replace("_", "-")
    if normalized in {"", "default", "auto", "adaptive", "responsive"}:
        return ADAPTIVE_TUI_LAYOUT
    if normalized in {"split", "wide", "desktop"}:
        return SPLIT_TUI_LAYOUT
    if normalized in {"compact", "mobile", "small", "single", "single-pane"}:
        return COMPACT_TUI_LAYOUT
    if normalized in {"tiny", "pocket", "pocketchip", "mini"}:
        return TINY_TUI_LAYOUT
    return DEFAULT_TUI_LAYOUT


def env_layout_value() -> str | None:
    if "AGENT_PBX_TUI_LAYOUT" not in os.environ:
        return None
    return resolve_layout(os.getenv("AGENT_PBX_TUI_LAYOUT", ""))


def clamp_split_percent(value: int) -> int:
    return max(MIN_SPLIT_PERCENT, min(MAX_SPLIT_PERCENT, value))


def operator_panel_height(left_height: int) -> int:
    if left_height <= 0:
        return OPERATOR_PANEL_MIN_HEIGHT
    minimum = max(OPERATOR_PANEL_MIN_HEIGHT, round(left_height * OPERATOR_PANEL_MIN_RATIO))
    maximum = max(minimum, round(left_height * OPERATOR_PANEL_MAX_RATIO))
    desired = round(left_height * OPERATOR_PANEL_DEFAULT_RATIO)
    return max(minimum, min(maximum, desired))


def agent_pbx_mcp_url(server: str) -> str:
    return f"{server.rstrip('/')}/mcp"


def codex_command_argv(codex_command: str) -> list[str]:
    argv = shlex.split(codex_command.strip())
    return argv or ["codex"]


def codex_mcp_add_command(codex_command: str, mcp_url: str) -> list[str]:
    return [
        *codex_command_argv(codex_command),
        "mcp",
        "add",
        "agent-pbx",
        "--url",
        mcp_url,
        "--bearer-token-env-var",
        AGENT_PBX_TOKEN_ENV,
    ]


def codex_mcp_remove_command(codex_command: str) -> list[str]:
    return [*codex_command_argv(codex_command), "mcp", "remove", "agent-pbx"]


def codex_config_mcp_key(server_name: str, setting: str) -> str:
    return f"mcp_servers.{toml_key(server_name)}.{setting}"


def codex_model_launch_config_overrides() -> list[str]:
    return codex_model_config_overrides(
        model=os.getenv(CODEX_MODEL_ENV),
        reasoning_effort=os.getenv(CODEX_REASONING_EFFORT_ENV),
        reasoning_summary=os.getenv(CODEX_REASONING_SUMMARY_ENV),
        verbosity=os.getenv(CODEX_VERBOSITY_ENV),
        service_tier=os.getenv(CODEX_SERVICE_TIER_ENV),
    )


def codex_project_trust_config_override(cwd: str | None) -> str | None:
    path = str(cwd or "").strip()
    if not path:
        return None
    try:
        resolved = str(Path(path).expanduser().resolve())
    except OSError:
        resolved = str(Path(path).expanduser())
    return codex_config_override(
        "projects",
        {resolved: {"trust_level": "trusted"}},
    )


def parse_codex_config_string_value(raw_value: str) -> str | None:
    value = raw_value.strip()
    if len(value) < 2:
        return None
    if value[0] == value[-1] == '"':
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            return value[1:-1]
        return parsed if isinstance(parsed, str) else None
    if value[0] == value[-1] == "'":
        return value[1:-1]
    return None


def parse_codex_config_string_array(raw_value: str) -> list[str] | None:
    value = raw_value.strip()
    if not value.startswith("[") or not value.endswith("]"):
        return None
    try:
        parsed = json.loads(value)
    except json.JSONDecodeError:
        return None
    if not isinstance(parsed, list):
        return None
    items = [item for item in parsed if isinstance(item, str)]
    return items if len(items) == len(parsed) else None


def parse_codex_config_simple_value(raw_value: str) -> object | None:
    value = raw_value.strip()
    parsed_string = parse_codex_config_string_value(value)
    if parsed_string is not None:
        return parsed_string
    parsed_array = parse_codex_config_string_array(value)
    if parsed_array is not None:
        return parsed_array
    return None


def codex_mcp_server_header_name(line: str) -> str | None:
    match = re.match(r"^\s*\[mcp_servers\.(?P<name>.+)]\s*(?:#.*)?$", line)
    if not match:
        return None
    raw_name = match.group("name").strip()
    if raw_name.startswith('"') and raw_name.endswith('"'):
        try:
            parsed = json.loads(raw_name)
        except json.JSONDecodeError:
            return raw_name[1:-1]
        return parsed if isinstance(parsed, str) else None
    return raw_name


def load_codex_mcp_server_configs(
    codex_home: Path | None,
    server_names: Iterable[str],
) -> dict[str, dict[str, object]]:
    if codex_home is None:
        return {}
    config_path = codex_home / "config.toml"
    try:
        lines = config_path.read_text(encoding="utf-8").splitlines()
    except OSError:
        return {}

    targets = set(server_names)
    configs: dict[str, dict[str, object]] = {}
    current: str | None = None
    for line in lines:
        header_name = codex_mcp_server_header_name(line)
        if header_name is not None:
            current = header_name if header_name in targets else None
            if current is not None:
                configs.setdefault(current, {})
            continue
        if line.strip().startswith("["):
            current = None
            continue
        if current is None or "=" not in line:
            continue
        key, raw_value = line.split("=", 1)
        key = key.strip()
        if key not in CODEX_MCP_SERVER_TRANSPORT_KEYS:
            continue
        value = parse_codex_config_simple_value(raw_value)
        if value is not None:
            configs[current][key] = value
    return configs


def review_operator_mcp_approval_server_names() -> tuple[str, ...]:
    return mcp_approval_server_names(
        REVIEW_OPERATOR_MCP_APPROVAL_SERVERS_ENV,
        fallback_env_names=(),
    )


def operator_mcp_approval_server_names() -> tuple[str, ...]:
    return mcp_approval_server_names(
        OPERATOR_MCP_APPROVAL_SERVERS_ENV,
        fallback_env_names=(REVIEW_OPERATOR_MCP_APPROVAL_SERVERS_ENV,),
    )


def mcp_approval_server_names(
    env_name: str,
    *,
    fallback_env_names: Iterable[str] = (),
) -> tuple[str, ...]:
    configured = os.getenv(env_name, "").strip()
    if not configured:
        for fallback_name in fallback_env_names:
            configured = os.getenv(fallback_name, "").strip()
            if configured:
                break
    if configured:
        names = tuple(
            name.strip()
            for name in configured.split(",")
            if name.strip()
        )
    else:
        names = DEFAULT_REVIEW_OPERATOR_MCP_APPROVAL_SERVERS
    if "agent-pbx" in names:
        return names
    return ("agent-pbx", *names)


def review_operator_mcp_config_overrides(
    server_names: Iterable[str] | None = None,
    *,
    mcp_url: str | None = None,
    codex_home: Path | None = None,
    server_configs: Mapping[str, Mapping[str, object]] | None = None,
    agent_pbx_approved_tools: Iterable[str] | None = None,
    workerbee_approved_tools: Iterable[str] | None = None,
    workerbee_gateway_binding: Mapping[str, object] | None = None,
) -> list[str]:
    overrides: list[str] = []
    names = tuple(server_names or review_operator_mcp_approval_server_names())
    if workerbee_gateway_binding and "workerbee" not in names:
        names = (*names, "workerbee")
    configured_servers: dict[str, dict[str, object]] = {
        server_name: dict(config)
        for server_name, config in DEFAULT_REVIEW_OPERATOR_MCP_SERVER_CONFIGS.items()
    }
    configured_servers.update(load_codex_mcp_server_configs(codex_home, names))
    if server_configs:
        configured_servers.update(
            {
                server_name: dict(config)
                for server_name, config in server_configs.items()
            }
        )
    resolved_agent_pbx_tools = tuple(agent_pbx_approved_tools or ())
    for server_name in names:
        approved_tools = (
            resolved_agent_pbx_tools
            if server_name == "agent-pbx" and resolved_agent_pbx_tools
            else (
                tuple(workerbee_approved_tools or ())
                if server_name == "workerbee" and workerbee_approved_tools
                else REVIEW_OPERATOR_MCP_APPROVED_TOOLS.get(server_name)
            )
        )
        if not approved_tools:
            continue
        transport_config = dict(configured_servers.get(server_name, {}))
        if server_name == "agent-pbx":
            transport_config["url"] = (
                mcp_url
                or str(transport_config.get("url") or "").strip()
                or agent_pbx_mcp_url(
                    os.getenv(AGENT_PBX_SERVER_URL_ENV, "http://127.0.0.1:8765")
                )
            )
            transport_config["bearer_token_env_var"] = AGENT_PBX_TOKEN_ENV
        elif server_name == "workerbee" and workerbee_gateway_binding:
            transport_config = {
                "url": str(
                    workerbee_gateway_binding.get("gateway_url") or ""
                ).strip(),
                "bearer_token_env_var": str(
                    workerbee_gateway_binding.get("bearer_token_env_var")
                    or WORKERBEE_GATEWAY_TOKEN_ENV
                ).strip(),
            }
        if not transport_config.get("url") and not transport_config.get("command"):
            continue
        config = {
            key: value
            for key, value in transport_config.items()
            if key in CODEX_MCP_SERVER_TRANSPORT_KEYS
        }
        config["enabled_tools"] = list(approved_tools)
        config["default_tools_approval_mode"] = "approve"
        overrides.append(
            codex_config_override(
                f"mcp_servers.{toml_key(server_name)}",
                config,
            )
        )
    return overrides


def workerbee_gateway_launch_tools(
    binding: Mapping[str, object] | None,
) -> tuple[str, ...]:
    """Return the reviewed Codex allowlist for one gateway lease.

    The gateway remains the authorization boundary, but Codex also needs an
    explicit launch-time allowlist.  Derive that allowlist from the exact lease
    rather than falling back to the review-only operator surface.  Unknown or
    incomplete leases fail closed to the review surface.
    """

    lease = binding.get("lease") if isinstance(binding, Mapping) else None
    if not isinstance(lease, Mapping):
        return REVIEW_OPERATOR_WORKERBEE_APPROVED_TOOLS
    profile = str(lease.get("profile") or "").strip().lower()
    if profile not in {
        WORKERBEE_PROFILE_REVIEW,
        WORKERBEE_PROFILE_OBSERVE,
        WORKERBEE_PROFILE_LOCAL_DEPLOY,
        WORKERBEE_PROFILE_TRUSTED_WORKBENCH,
    }:
        return REVIEW_OPERATOR_WORKERBEE_APPROVED_TOOLS
    backend = str(lease.get("backend") or "").strip()
    reviewed = reviewed_tools_for_access_profile(profile, backend)
    raw_allowed = lease.get("allowed_tools")
    if not isinstance(raw_allowed, (list, tuple)):
        return reviewed
    reviewed_set = set(reviewed)
    allowed = tuple(
        dict.fromkeys(
            str(tool).strip()
            for tool in raw_allowed
            if str(tool).strip() in reviewed_set
        )
    )
    return allowed or REVIEW_OPERATOR_WORKERBEE_APPROVED_TOOLS


def agent_pbx_mcp_config_override(
    approved_tools: Iterable[str],
    *,
    mcp_url: str | None = None,
) -> str:
    transport_config = {
        "url": mcp_url
        or agent_pbx_mcp_url(
            os.getenv(AGENT_PBX_SERVER_URL_ENV, "http://127.0.0.1:8765")
        ),
        "bearer_token_env_var": AGENT_PBX_TOKEN_ENV,
        "enabled_tools": list(approved_tools),
        "default_tools_approval_mode": "approve",
    }
    return codex_config_override(
        "mcp_servers.agent-pbx",
        transport_config,
    )


def caller_workerbee_mcp_config_overrides(
    profile: str | None,
    *,
    codex_home: Path | None = None,
    server_configs: Mapping[str, Mapping[str, object]] | None = None,
    gateway_binding: Mapping[str, object] | None = None,
) -> list[str]:
    """Return an explicit, task-scoped WorkerBee policy for a caller.

    Direct callers otherwise inherit the user's global WorkerBee configuration.
    A recognized metadata profile opts one caller into a bounded mutation set;
    unknown values fail closed without broadening global policy.
    """

    normalized_profile = str(profile or "").strip().lower()
    if normalized_profile not in {
        WORKERBEE_PROFILE_REVIEW,
        WORKERBEE_PROFILE_OBSERVE,
        WORKERBEE_PROFILE_LOCAL_DEPLOY,
        WORKERBEE_PROFILE_TRUSTED_WORKBENCH,
    }:
        return []

    configured_servers = {
        "workerbee": dict(DEFAULT_REVIEW_OPERATOR_MCP_SERVER_CONFIGS["workerbee"])
    }
    configured_servers.update(load_codex_mcp_server_configs(codex_home, ("workerbee",)))
    if server_configs and "workerbee" in server_configs:
        configured_servers["workerbee"] = {
            **configured_servers["workerbee"],
            **dict(server_configs["workerbee"]),
        }
    if gateway_binding:
        transport_config = {
            "url": str(gateway_binding.get("gateway_url") or "").strip(),
            "bearer_token_env_var": str(
                gateway_binding.get("bearer_token_env_var")
                or WORKERBEE_GATEWAY_TOKEN_ENV
            ).strip(),
        }
    else:
        transport_config = {
            key: value
            for key, value in configured_servers["workerbee"].items()
            if key in CODEX_MCP_SERVER_TRANSPORT_KEYS
        }
    if not transport_config.get("url") and not transport_config.get("command"):
        return []
    transport_config["enabled_tools"] = list(
        workerbee_gateway_launch_tools(gateway_binding)
        if gateway_binding
        else tools_for_access_profile(normalized_profile)
    )
    transport_config["default_tools_approval_mode"] = "approve"
    return [
        codex_config_override(
            "mcp_servers.workerbee",
            transport_config,
        )
    ]


def caller_agent_config_overrides(
    *,
    mcp_url: str | None = None,
    work_root: str | None = None,
    terminal_mode: str = CODEX_TERMINAL_MODE_DEFAULT,
    workerbee_profile: str | None = None,
    codex_home: Path | None = None,
    server_configs: Mapping[str, Mapping[str, object]] | None = None,
    workerbee_gateway_binding: Mapping[str, object] | None = None,
) -> list[str]:
    mcp_overrides = [
        agent_pbx_mcp_config_override(
            CALLER_AGENT_PBX_APPROVED_TOOLS,
            mcp_url=mcp_url,
        )
    ]
    mcp_overrides.extend(
        caller_workerbee_mcp_config_overrides(
            workerbee_profile,
            codex_home=codex_home,
            server_configs=server_configs,
            gateway_binding=workerbee_gateway_binding,
        )
    )
    return CodexLaunchOverridePolicy(
        process=managed_codex_process_overrides(),
        mcp=tuple(mcp_overrides),
        trust=codex_project_trust_config_override(work_root),
        profile=tuple(
            codex_model_preset_config_overrides(
                CODEX_MODEL_PRESET_BY_KEY[DEFAULT_CALLER_MODEL_PRESET_KEY]
            )
        ),
        model=tuple(codex_model_launch_config_overrides()),
        terminal=tuple(codex_terminal_config_overrides(terminal_mode)),
    ).overrides()


def review_operator_config_overrides(
    server_names: Iterable[str] | None = None,
    *,
    mcp_url: str | None = None,
    codex_home: Path | None = None,
    work_root: str | None = None,
    server_configs: Mapping[str, Mapping[str, object]] | None = None,
    terminal_mode: str = CODEX_TERMINAL_MODE_DEFAULT,
    workerbee_gateway_binding: Mapping[str, object] | None = None,
) -> list[str]:
    return CodexLaunchOverridePolicy(
        process=managed_codex_process_overrides(),
        mcp=tuple(
            review_operator_mcp_config_overrides(
                server_names,
                mcp_url=mcp_url,
                codex_home=codex_home,
                server_configs=server_configs,
                workerbee_gateway_binding=workerbee_gateway_binding,
            )
        ),
        trust=codex_project_trust_config_override(work_root),
        profile=tuple(
            codex_model_preset_config_overrides(
                CODEX_MODEL_PRESET_BY_KEY[DEFAULT_OPERATOR_MODEL_PRESET_KEY]
            )
        ),
        model=tuple(codex_model_launch_config_overrides()),
        terminal=tuple(codex_terminal_config_overrides(terminal_mode)),
    ).overrides()


def operator_agent_config_overrides(
    server_names: Iterable[str] | None = None,
    *,
    mcp_url: str | None = None,
    codex_home: Path | None = None,
    work_root: str | None = None,
    server_configs: Mapping[str, Mapping[str, object]] | None = None,
    include_campaign_lifecycle: bool = False,
    terminal_mode: str = CODEX_TERMINAL_MODE_DEFAULT,
    workerbee_gateway_binding: Mapping[str, object] | None = None,
    authority_metadata: Mapping[str, object] | None = None,
    linked_git_admin_plan: LinkedWorktreeGitAdminPlan | None = None,
) -> list[str]:
    """Build a least-privilege operator MCP allowlist for a launch.

    Root operator panes receive the campaign lifecycle tools. Edit and review
    forks remain unable to create, follow up, or finish campaigns directly.
    """
    return CodexLaunchOverridePolicy(
        process=managed_codex_process_overrides(),
        mcp=tuple(
            review_operator_mcp_config_overrides(
                server_names or operator_mcp_approval_server_names(),
                mcp_url=mcp_url,
                codex_home=codex_home,
                server_configs=server_configs,
                agent_pbx_approved_tools=(
                    OPERATOR_AGENT_PBX_APPROVED_TOOLS
                    if include_campaign_lifecycle
                    else None
                ),
                workerbee_approved_tools=workerbee_gateway_launch_tools(
                    workerbee_gateway_binding
                ),
                workerbee_gateway_binding=workerbee_gateway_binding,
            )
        ),
        trust=codex_project_trust_config_override(work_root),
        profile=tuple(
            codex_model_preset_config_overrides(
                CODEX_MODEL_PRESET_BY_KEY[DEFAULT_OPERATOR_MODEL_PRESET_KEY]
            )
        ),
        model=tuple(codex_model_launch_config_overrides()),
        terminal=tuple(codex_terminal_config_overrides(terminal_mode)),
        authority=tuple(
            codex_config_override(key, value)
            for key, value in operator_authority_launch_overrides(
                authority_metadata or {},
                linked_git_admin_plan=linked_git_admin_plan,
            )
        ),
    ).overrides()


def process_error_summary(result: subprocess.CompletedProcess[str]) -> str:
    detail = (result.stderr or result.stdout or "").strip()
    if detail:
        return detail
    return f"exit code {result.returncode}"


def configure_codex_mcp(
    codex_command: str,
    mcp_url: str,
    *,
    timeout: float = 15.0,
) -> None:
    add_command = codex_mcp_add_command(codex_command, mcp_url)
    add = subprocess.run(
        add_command,
        capture_output=True,
        text=True,
        timeout=timeout,
    )
    if add.returncode == 0:
        return
    add_failure = process_error_summary(add).lower()
    if "exist" not in add_failure and "already" not in add_failure:
        raise RuntimeError(f"add failed: {process_error_summary(add)}")

    remove = subprocess.run(
        codex_mcp_remove_command(codex_command),
        capture_output=True,
        text=True,
        timeout=timeout,
    )
    retry = subprocess.run(
        add_command,
        capture_output=True,
        text=True,
        timeout=timeout,
    )
    if retry.returncode == 0:
        return

    details = [f"add failed: {process_error_summary(add)}"]
    if remove.returncode != 0:
        details.append(f"remove failed: {process_error_summary(remove)}")
    details.append(f"retry failed: {process_error_summary(retry)}")
    raise RuntimeError("; ".join(details))


def env_split_percent_value() -> int | None:
    value = os.getenv("AGENT_PBX_TUI_SPLIT_PERCENT", "").strip()
    if not value:
        return None
    parsed = int_value(value)
    return clamp_split_percent(parsed) if parsed is not None else None


def env_export_dir(default: Path = DEFAULT_EXPORT_DIR) -> Path:
    return env_export_dir_value() or default


def env_export_dir_value() -> Path | None:
    value = os.getenv("AGENT_PBX_TUI_EXPORT_DIR", "").strip()
    return Path(value).expanduser() if value else None


def env_tmux_capture_lines_value() -> int | None:
    value = os.getenv("AGENT_PBX_TUI_TMUX_CAPTURE_LINES", "").strip()
    if not value:
        return None
    parsed = int_value(value)
    return parsed if parsed is not None and parsed >= 0 else None


def env_tmux_refresh_seconds_value() -> float | None:
    value = os.getenv("AGENT_PBX_TUI_TMUX_REFRESH_SECONDS", "").strip()
    if not value:
        return None
    parsed = float_value(value)
    if parsed is None or parsed <= 0:
        return None
    return max(MIN_TMUX_REFRESH_SECONDS, parsed)


def env_agent_refresh_seconds_value() -> float | None:
    value = os.getenv("AGENT_PBX_TUI_AGENT_REFRESH_SECONDS", "").strip()
    if not value:
        return None
    parsed = float_value(value)
    if parsed is None or parsed <= 0:
        return None
    return max(MIN_AGENT_REFRESH_SECONDS, parsed)


def env_attention_blink_seconds_value() -> float | None:
    value = os.getenv("AGENT_PBX_TUI_ATTENTION_BLINK_SECONDS", "").strip()
    if not value:
        return None
    parsed = float_value(value)
    if parsed is None or parsed <= 0:
        return None
    return max(MIN_ATTENTION_BLINK_SECONDS, parsed)


def is_local_server_url(server: str) -> bool:
    parsed = urlparse(server)
    host = (parsed.hostname or "").strip().lower()
    return host in {"localhost", "127.0.0.1", "::1"}


def tmux_features_available(
    *,
    tmux_direct_enabled: bool = False,
    tmux_bin: str = "tmux",
) -> bool:
    if resolve_tmux_binary(tmux_bin) is None:
        return False
    return bool(os.getenv("TMUX")) or tmux_direct_enabled or env_flag(
        "AGENT_PBX_TUI_TMUX_SHOW"
    )


def env_settings_file() -> Path:
    value = os.getenv("AGENT_PBX_TUI_SETTINGS_FILE", "").strip()
    if value:
        return Path(value).expanduser()
    config_home = os.getenv("XDG_CONFIG_HOME", "").strip()
    base = Path(config_home).expanduser() if config_home else Path.home() / ".config"
    return base / DEFAULT_SETTINGS_FILE


def load_tui_settings(path: Path) -> dict[str, Any]:
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    return data if isinstance(data, dict) else {}


def normalize_codex_terminal_mode(value: object) -> str:
    mode = str(value or "").strip().casefold().replace("-", "_")
    if mode in {"scrollback", "normal", "pbx", "compatible"}:
        return CODEX_TERMINAL_MODE_SCROLLBACK
    if mode in {"raw", "raw_output", "raw_scrollback"}:
        return CODEX_TERMINAL_MODE_RAW
    if mode in {"default", "codex", "auto"}:
        return CODEX_TERMINAL_MODE_DEFAULT
    return DEFAULT_CODEX_TERMINAL_MODE


def codex_terminal_config_overrides(mode: object) -> list[str]:
    normalized = normalize_codex_terminal_mode(mode)
    overrides = list(portable_codex_keymap_overrides())
    if normalized == CODEX_TERMINAL_MODE_DEFAULT:
        return overrides
    overrides.append(codex_config_override("tui.alternate_screen", "never"))
    if normalized == CODEX_TERMINAL_MODE_RAW:
        overrides.append(codex_config_override("tui.raw_output_mode", True))
    return overrides


def codex_model_preset_for(value: object) -> CodexModelPreset | None:
    return managed_profile_for(value)


def codex_model_preset_from_metadata(
    metadata: Mapping[str, Any] | None,
) -> CodexModelPreset | None:
    """Recover the last selected harness preset without trusting free-form text."""
    return managed_profile_from_metadata(metadata)


def codex_model_preset_config_overrides(
    preset: CodexModelPreset | None,
) -> list[str]:
    if preset is None:
        return []
    return codex_model_config_overrides(
        model=preset.model,
        reasoning_effort=preset.reasoning_effort,
        reasoning_summary=preset.reasoning_summary,
        verbosity=preset.verbosity,
        service_tier=preset.service_tier,
    )


def env_slash_commands_file() -> Path:
    value = os.getenv("AGENT_PBX_TUI_COMMANDS_FILE", "").strip()
    if value:
        return Path(value).expanduser()
    config_home = os.getenv("XDG_CONFIG_HOME", "").strip()
    base = Path(config_home).expanduser() if config_home else Path.home() / ".config"
    return base / DEFAULT_SLASH_COMMANDS_FILE


def parse_custom_slash_commands(
    data: object,
    *,
    built_in_names: set[str] | None = None,
) -> tuple[list[CustomSlashCommand], list[str]]:
    if not isinstance(data, dict):
        return [], ["custom slash command file must contain a JSON object"]
    raw_commands = data.get("commands")
    if raw_commands is None:
        return [], []
    if not isinstance(raw_commands, list):
        return [], ["custom slash command field 'commands' must be a list"]

    reserved_names = {name.strip() for name in built_in_names or set()}
    seen_names = set(reserved_names)
    commands: list[CustomSlashCommand] = []
    errors: list[str] = []
    for index, item in enumerate(raw_commands, start=1):
        prefix = f"commands[{index}]"
        if not isinstance(item, dict):
            errors.append(f"{prefix} must be an object")
            continue
        name = item.get("name")
        prompt = item.get("prompt")
        if not isinstance(name, str) or not name.strip():
            errors.append(f"{prefix}.name is required")
            continue
        normalized_name = name.strip()
        if not normalized_name.startswith("/"):
            errors.append(f"{prefix}.name must start with '/'")
            continue
        if normalized_name in seen_names:
            errors.append(f"{prefix}.name duplicates a built-in or earlier command")
            continue
        if not isinstance(prompt, str) or not prompt.strip():
            errors.append(f"{prefix}.prompt is required")
            continue
        clean_prompt = prompt.strip()
        placeholders = set(re.findall(r"{([^{}]+)}", clean_prompt))
        unsupported = sorted(placeholders - {"arg"})
        if unsupported:
            errors.append(
                f"{prefix}.prompt uses unsupported placeholder(s): "
                + ", ".join(f"{{{value}}}" for value in unsupported)
            )
            continue
        description = item.get("description")
        arg_label = item.get("arg_label")
        arg_placeholder = item.get("arg_placeholder")
        arg_required = item.get("arg_required")
        commands.append(
            CustomSlashCommand(
                name=normalized_name,
                description=(
                    description.strip()
                    if isinstance(description, str) and description.strip()
                    else "Custom slash command"
                ),
                prompt=clean_prompt,
                arg_label=(
                    arg_label.strip()
                    if isinstance(arg_label, str) and arg_label.strip()
                    else "Argument"
                ),
                arg_placeholder=(
                    arg_placeholder.strip()
                    if isinstance(arg_placeholder, str)
                    and arg_placeholder.strip()
                    else ""
                ),
                arg_required=arg_required if isinstance(arg_required, bool) else False,
            )
        )
        seen_names.add(normalized_name)
    return commands, errors


def load_custom_slash_commands(
    path: Path,
    *,
    built_in_names: set[str] | None = None,
) -> tuple[list[CustomSlashCommand], list[str]]:
    try:
        text = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        return [], []
    except OSError as exc:
        return [], [f"unable to read {path}: {exc}"]
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        return [], [f"{path}: invalid JSON at line {exc.lineno}, column {exc.colno}"]
    return parse_custom_slash_commands(data, built_in_names=built_in_names)


def render_custom_slash_prompt(command: CustomSlashCommand, arg: str = "") -> str:
    return command.prompt.replace("{arg}", arg.strip())


def render_plan_prompt(message: str) -> str:
    return f"{PLAN_PBX_CONTEXT_PROMPT}\n\n{message.strip()}"


def codex_native_plan_selector_indices(text: str) -> tuple[int, ...]:
    normalized_lines = [
        " ".join(line.casefold().split()) for line in text.splitlines()
    ]
    if not normalized_lines:
        return ()
    start_terms = (
        "implement this plan",
        "implement the plan",
        "start coding",
        "start implementation",
        "begin coding",
        "start work",
        "switch to default",
    )
    stay_terms = (
        "stay in plan",
        "stay in planning",
        "keep planning",
        "continue planning",
        "remain in plan",
        "no, keep",
    )
    indexed_labels: dict[int, str] = {}
    marked_indices: set[int] = set()
    for line in normalized_lines[-40:]:
        match = CODEX_NATIVE_SELECTOR_LINE_PATTERN.match(line)
        if match is None:
            continue
        label = match.group("label").strip()
        if len(label) > 160:
            continue
        index = int(match.group("index"))
        indexed_labels[index] = label
        if match.group("marker"):
            marked_indices.add(index)

    def choice_line(index: int, terms: tuple[str, ...]) -> bool:
        label = indexed_labels.get(index, "")
        return any(term in label for term in terms)

    if all(
        (
            choice_line(1, start_terms),
            choice_line(2, ("clear", "discard")),
            choice_line(3, stay_terms),
        )
    ):
        return tuple(sorted(indexed_labels))
    selector_context = any(
        term in " ".join(normalized_lines[-40:])
        for term in (
            "plan",
            "planning",
            "implement",
            "coding",
            "context",
            "approach",
            "api shape",
            "compatibility",
            "migration",
            "phase",
        )
    )
    if marked_indices and len(indexed_labels) >= 2 and selector_context:
        return tuple(sorted(indexed_labels))
    return ()


def contains_codex_native_plan_selector(text: str) -> bool:
    return bool(codex_native_plan_selector_indices(text))


def contains_codex_copy_picker(text: str) -> bool:
    clean = str(text or "")
    lower = clean.casefold()
    numbered_options = re.findall(
        r"(?m)^\s*(?:[>›❯▸➜*]\s*)?\d+[.)]\s+\S",
        clean,
    )
    if len(numbered_options) < 2:
        return False
    # Native Codex picker text has changed between CLI releases. Require menu
    # evidence specific to /copy before acting on it so arbitrary numbered
    # agent questions are never treated as a local selection dialog.
    native_controls = bool(
        re.search(
            r"(?i)(?:enter\s+(?:to\s+)?select|esc\s+(?:to\s+)?(?:back|cancel)|"
            r"arrow\s+keys|[↑↓]\s*(?:move|navigate|select))",
            clean,
        )
    )
    copy_heading = bool(
        re.search(
            r"(?i)(?:copy\s+(?:to\s+)?clipboard|"
            r"(?:choose|select|what)\b[^\n]{0,48}\bcopy\b|"
            r"copy\s+(?:response|content|selection))",
            clean,
        )
    )
    return copy_heading and (native_controls or "/copy" in lower)


def codex_copy_options(text: str) -> tuple[CodexCopyOption, ...]:
    if not contains_codex_copy_picker(text):
        return ()
    options: list[CodexCopyOption] = []
    for line in str(text or "").splitlines():
        match = re.match(
            r"^\s*(?P<marker>[>›❯▸➜*])?\s*(?P<index>\d+)[.)]\s+(?P<label>\S.*)$",
            line,
        )
        if match is None:
            continue
        label = re.split(r"\s{2,}", match.group("label").strip(), maxsplit=1)[0]
        options.append(
            CodexCopyOption(
                index=int(match.group("index")),
                label=label,
                selected=bool(match.group("marker")),
            )
        )
    return tuple(options)


def codex_copy_response_option(text: str) -> CodexCopyOption | None:
    preferred: list[tuple[int, CodexCopyOption]] = []
    for option in codex_copy_options(text):
        label = " ".join(option.label.casefold().split())
        if any(term in label for term in ("prompt", "reasoning", "code block", "command")):
            continue
        score = 0
        if any(term in label for term in ("whole response", "entire response", "full response")):
            score = 40
        elif any(term in label for term in ("latest response", "current response")):
            score = 35
        elif any(term in label for term in ("entire answer", "whole answer", "full answer")):
            score = 30
        elif re.search(r"\b(response|answer|message|status)\b", label):
            score = 20
        if score:
            preferred.append((score, option))
    if not preferred:
        return None
    preferred.sort(key=lambda item: (-item[0], item[1].index))
    return preferred[0][1]


def contains_codex_copy_selector(text: str) -> bool:
    """Return whether a native picker offers a response-safe choice."""
    return codex_copy_response_option(text) is not None


def built_in_palette_command_names(custom_theme_name: str = DEFAULT_CUSTOM_THEME_NAME) -> set[str]:
    names = set(BUILT_IN_PALETTE_COMMAND_NAMES)
    if (
        str(os.getenv("AGENT_PBX_WORKERBEE_WORKSPACE_CONTROL_MODE") or "")
        .strip()
        .lower()
        == "hidden"
    ):
        names.difference_update({"/workerbee workspace", "/workerbee policy"})
    if (
        str(os.getenv("AGENT_PBX_WORKERBEE_SNAPSHOT_CONTROL_MODE") or "")
        .strip()
        .lower()
        == "hidden"
    ):
        names.discard("/workerbee content")
    if all(
        str(os.getenv(name) or "").strip().lower() == "hidden"
        for name in (
            "AGENT_PBX_WORKERBEE_ACCESS_CONTROL_MODE",
            "AGENT_PBX_WORKERBEE_SOURCE_MODE_CONTROL_MODE",
            "AGENT_PBX_WORKERBEE_EXECUTION_LANE_CONTROL_MODE",
        )
    ):
        names.discard("/workerbee access")
    if (
        str(os.getenv("AGENT_PBX_WORKERBEE_CONTROLLED_RUN_CONTROL_MODE") or "")
        .strip()
        .lower()
        == "hidden"
    ):
        names.difference_update(
            {
                "/workerbee run",
                "/workerbee run status",
                "/workerbee run cancel",
                "/workerbee run leases",
            }
        )
    names.add(f"/theme {custom_theme_name}")
    return names


def normalize_response_text(text: str) -> str:
    return str(text or "").replace("\r\n", "\n").replace("\r", "\n").strip()


def response_text_digest(text: str) -> str:
    return hashlib.sha256(
        normalize_response_text(text).encode("utf-8", errors="replace")
    ).hexdigest()


def clipboard_reader_environment(
    pane_environment: Mapping[str, str] | None,
) -> dict[str, str] | None:
    """Build a reader environment from a fixed pane desktop-session allowlist."""
    if not pane_environment:
        return None
    # Clipboard readers do not need the TUI's full environment.  In particular,
    # do not pass PBX, provider, or Codex credentials to a desktop helper just
    # because the helper must run in a pane's graphical session.
    environment = {
        key: value
        for key in CLIPBOARD_READER_BASE_ENV_KEYS
        if (value := os.environ.get(key))
    }
    for key in tmux_support.PANE_CLIPBOARD_ENV_KEYS:
        value = pane_environment.get(key)
        if value:
            environment[key] = value
    return environment


def read_clipboard_candidates(
    *,
    environment: Mapping[str, str] | None = None,
    source_prefix: str = "",
    include_tmux_buffer: bool = True,
    timeout_seconds: float = CLIPBOARD_READ_TIMEOUT_SECONDS,
) -> tuple[ClipboardCandidate, ...]:
    """Read every non-empty clipboard source instead of accepting the first one."""
    commands = (
        CLIPBOARD_READ_COMMANDS
        if include_tmux_buffer
        else CLIPBOARD_DESKTOP_READ_COMMANDS
    )
    candidates: list[ClipboardCandidate] = []
    prefix = source_prefix.strip()
    for label, command in commands:
        executable = command[0]
        if shutil.which(executable) is None:
            continue
        try:
            result = subprocess.run(
                list(command),
                capture_output=True,
                text=True,
                timeout=timeout_seconds,
                check=False,
                env=dict(environment) if environment is not None else None,
            )
        except (OSError, subprocess.SubprocessError):
            continue
        if result.returncode != 0:
            continue
        text = result.stdout.rstrip("\n")
        if not text.strip():
            continue
        source = f"{prefix}: {label}" if prefix else label
        candidates.append(ClipboardCandidate(source, text))
    return tuple(candidates)


def read_clipboard_text() -> tuple[str, str]:
    candidates = read_clipboard_candidates()
    if candidates:
        first = candidates[0]
        return first.text, first.source
    raise RuntimeError(
        "no clipboard reader found; install wl-paste, xclip, xsel, pbpaste, "
        "termux-clipboard-get, or run inside tmux with a readable tmux buffer"
    )


def write_clipboard_text(text: str) -> str:
    errors: list[str] = []
    for label, command in CLIPBOARD_WRITE_COMMANDS:
        executable = command[0]
        if shutil.which(executable) is None:
            continue
        try:
            result = subprocess.run(
                list(command),
                input=text,
                capture_output=True,
                text=True,
                timeout=2,
                check=False,
            )
        except (OSError, subprocess.SubprocessError) as exc:
            errors.append(f"{label}: {exc}")
            continue
        if result.returncode == 0:
            return label
        message = (result.stderr or result.stdout).strip()
        if message:
            errors.append(f"{label}: {message}")
    if errors:
        raise RuntimeError("; ".join(errors))
    raise RuntimeError(
        "no clipboard writer found; install wl-copy, xclip, xsel, pbcopy, "
        "termux-clipboard-set, or run inside tmux with a writable tmux buffer"
    )


def latest_nonlocal_sent_prompt(
    history: list[str],
    *,
    is_local_command: Callable[[str], bool],
) -> str:
    for message in reversed(history):
        clean = message.strip()
        if not clean:
            continue
        if is_local_command(clean):
            continue
        return clean
    return ""


def joplin_tmux_copy_title(prompt: str) -> str:
    first_line = next((line.strip() for line in prompt.splitlines() if line.strip()), "")
    if not first_line:
        return "Codex Response"
    if len(first_line) > 96:
        first_line = f"{first_line[:93].rstrip()}..."
    return f"Codex Response - {first_line}"


def format_joplin_tmux_response_copy_body(
    prompt: str,
    response: str,
    *,
    capture_source: str = "",
    capture: CodexCopyCapture | None = None,
) -> str:
    clean_prompt = prompt.strip()
    clean_response = response.strip()
    prompt_body = clean_prompt or "_No prompt was recorded by the Agent PBX TUI._"
    response_body = clean_response or "_No copied response text was available._"
    lines = [
        "## Prompt",
        "",
        "```text",
        prompt_body,
        "```",
        "",
    ]
    if capture_source.strip():
        lines.extend(["## Capture", "", capture_source.strip(), ""])
    if capture is not None:
        modified = (
            datetime.fromtimestamp(capture.mtime, timezone.utc).isoformat()
            if capture.mtime is not None
            else ""
        )
        lines.extend(
            [
                "## Capture provenance",
                "",
                f"- Session ID: `{capture.session_id or 'unavailable'}`",
                f"- Transcript path: `{capture.path or 'unavailable'}`",
                f"- Phase: `{capture.phase or 'unavailable'}`",
                "- Line index: "
                f"`{capture.line_index if capture.line_index is not None else 'unavailable'}`",
                f"- Transcript mtime: `{modified or 'unavailable'}`",
                f"- Response SHA-256: `{capture.digest}`",
                "",
            ]
        )
    lines.extend(["## Response", "", response_body])
    return "\n".join(lines)


def bool_setting(settings: dict[str, Any], key: str, default: bool) -> bool:
    value = settings.get(key)
    return value if isinstance(value, bool) else default


def str_setting(settings: dict[str, Any], key: str, default: str) -> str:
    value = settings.get(key)
    return value if isinstance(value, str) and value.strip() else default


def short_stable_hash(value: str, length: int = 8) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()[:length]


def normalize_project_path(path: str) -> str | None:
    clean = path.strip()
    if clean.startswith("/"):
        return None
    parts: list[str] = []
    for part in clean.split("/"):
        if not part or part == ".":
            continue
        if part == "..":
            return None
        parts.append(part)
    return "/".join(parts) or "."


def split_file_completion_prefix(prefix: str) -> tuple[str, str] | None:
    if "/" not in prefix:
        return ".", prefix
    directory, _, name_prefix = prefix.rpartition("/")
    normalized = normalize_project_path(directory or ".")
    if normalized is None:
        return None
    return normalized, name_prefix


































def float_value(value: object) -> float | None:
    try:
        return float(value)  # type: ignore[arg-type]
    except (TypeError, ValueError):
        return None


def int_value(value: object) -> int | None:
    try:
        return int(value)  # type: ignore[arg-type]
    except (TypeError, ValueError):
        return None


def int_setting(settings: dict[str, Any], key: str, default: int) -> int:
    value = int_value(settings.get(key))
    return value if value is not None else default


def current_process_rss_bytes() -> int | None:
    """Return current RSS on procfs hosts without adding a monitoring dependency."""

    try:
        for line in Path("/proc/self/status").read_text(encoding="utf-8").splitlines():
            if line.startswith("VmRSS:"):
                return int(line.split()[1]) * 1024
    except (FileNotFoundError, OSError, IndexError, ValueError):
        return None
    return None


def float_map_setting(settings: dict[str, Any], key: str) -> dict[str, float]:
    value = settings.get(key)
    if not isinstance(value, dict):
        return {}
    result: dict[str, float] = {}
    for item_key, item_value in value.items():
        parsed = float_value(item_value)
        if isinstance(item_key, str) and parsed is not None:
            result[item_key] = parsed
    return result


def str_map_setting(settings: dict[str, Any], key: str) -> dict[str, str]:
    value = settings.get(key)
    if not isinstance(value, dict):
        return {}
    return {
        item_key: item_value
        for item_key, item_value in value.items()
        if isinstance(item_key, str) and isinstance(item_value, str)
    }


def bool_map_setting(settings: dict[str, Any], key: str) -> dict[str, bool]:
    value = settings.get(key)
    if not isinstance(value, dict):
        return {}
    result: dict[str, bool] = {}
    for item_key, item_value in value.items():
        if not isinstance(item_key, str):
            continue
        if isinstance(item_value, bool):
            result[item_key] = item_value
            continue
        if isinstance(item_value, str):
            parsed = parse_env_bool(item_value)
            if parsed is not None:
                result[item_key] = parsed
    return result


def string_record_map_setting(
    settings: dict[str, Any],
    key: str,
) -> dict[str, dict[str, str]]:
    value = settings.get(key)
    if not isinstance(value, dict):
        return {}
    records: dict[str, dict[str, str]] = {}
    for record_key, record_value in value.items():
        if not isinstance(record_key, str) or not isinstance(record_value, dict):
            continue
        record = {
            field: field_value
            for field, field_value in record_value.items()
            if isinstance(field, str) and isinstance(field_value, str)
        }
        if record:
            records[record_key] = record
    return records


def str_set_setting(settings: dict[str, Any], key: str) -> set[str]:
    value = settings.get(key)
    if not isinstance(value, list):
        return set()
    return {item for item in value if isinstance(item, str) and item.strip()}


def list_value(value: object) -> list[Any]:
    return value if isinstance(value, list) else []


def plan_choice_from_value(value: Any) -> PlanChoice | None:
    if isinstance(value, str):
        label = value.strip()
        return PlanChoice(label=label, raw=value) if label else None
    if isinstance(value, dict):
        raw_id = value.get("id")
        option_id = str(raw_id).strip() if raw_id is not None else None
        raw_label = value.get("label")
        label = str(raw_label).strip() if raw_label is not None else ""
        if not label and option_id:
            label = option_id
        raw_description = value.get("description")
        description = (
            str(raw_description).strip() if raw_description is not None else None
        )
        if description == "":
            description = None
        return (
            PlanChoice(
                label=label,
                id=option_id or None,
                description=description,
                raw=value,
            )
            if label
            else None
        )
    label = str(value).strip()
    return PlanChoice(label=label, raw=value) if label else None


def plan_choices_from_value(value: object) -> list[PlanChoice]:
    choices: list[PlanChoice] = []
    for option in list_value(value):
        choice = plan_choice_from_value(option)
        if choice is not None:
            choices.append(choice)
    return choices


def parse_plan_selection_command(message: str) -> PlanSelection | None:
    match = PLAN_SELECTION_PATTERN.match(message.strip())
    if match is None:
        return None
    index = int(match.group("index"))
    notes = (match.group("notes") or "").strip()
    return PlanSelection(index=index, notes=notes)


def is_plan_toggle_message(message: str) -> bool:
    return message.strip().lower() == PLAN_SLASH_COMMAND


def format_duration(seconds: float) -> str:
    seconds = max(0, int(seconds))
    if seconds < 60:
        return f"{seconds}s"
    minutes = seconds // 60
    if minutes < 60:
        return f"{minutes}m"
    hours = minutes // 60
    return f"{hours}h"


def format_count(value: int) -> str:
    if value < 1000:
        return str(value)
    return f"{value // 1000}k"


def git_diff_passthrough_command(target: str = "") -> str:
    clean_target = target.strip()
    if not clean_target:
        return "!git diff"
    quoted = shlex.quote(clean_target)
    if ":" in clean_target and not clean_target.startswith((".", "/")):
        return f"!git diff {quoted}"
    return f"!git diff -- {quoted}"


def git_push_passthrough_command(branch: str = "") -> str:
    clean_branch = branch.strip()
    if not clean_branch:
        return "!git push origin HEAD"
    return f"!git push origin {shlex.quote(clean_branch)}"


def parse_git_push_slash_command(message: str) -> str | None:
    stripped = message.strip()
    if "\n" in stripped:
        return None
    if stripped.lower() == "/gitpush":
        return ""
    command, separator, branch = stripped.partition(" ")
    if not separator or command.lower() != "/gitpush":
        return None
    return branch.strip()


