    def __init__(
        self,
        *,
        server: str,
        token: str | None = None,
        visual_flash: bool | None = None,
        terminal_bell: bool | None = None,
        theme_name: str | None = None,
        agent_blink: bool | None = None,
        tmux_direct: bool | None = None,
        tmux_capture_lines: int | None = None,
        export_dir: Path | str | None = None,
        settings_file: Path | str | None = None,
        v2_defaults: bool = False,
        host_terminal_identity: ui_runtime.TuiHostTerminalIdentity | None = None,
    ) -> None:
        super().__init__()
        self._campaign_controller = CampaignController(self)
        self._operator_handoff_controller = OperatorHandoffController(self)
        self._workerbee_controller = WorkerBeeController(self)
        self._workerbee_lifecycle_controller = WorkerBeeLifecycleController(self)
        self._joplin_controller = JoplinController(self)
        self._prompt_reference_controller = PromptReferenceController(self)
        self._github_controller = GitHubController(self)
        self._workerbee_projection_controller = WorkerBeeProjectionController(self)
        self.codex_model_policy: CodexModelPolicy = load_codex_model_policy()
        self.custom_theme_name = env_custom_theme_name()
        self.custom_palette = env_custom_palette()
        self.custom_theme = build_theme(self.custom_theme_name, self.custom_palette)
        self.register_theme(THEME_CYBERPUNK)
        self.register_theme(THEME_CYBERPUNK_ACCESSIBLE)
        self.register_theme(THEME_MINIMAL)
        self.register_theme(self.custom_theme)
        self.server = server.rstrip("/")
        self.token = token
        self.settings_file = (
            Path(settings_file).expanduser()
            if settings_file is not None
            else env_settings_file()
        )
        # Local-only private transaction state. This path is never accepted
        # from a palette field, API request, MCP call, or agent metadata.
        self.git_broker_state_root = default_state_root() / "git-broker"
        self.settings = load_tui_settings(self.settings_file)
        self.palette_history_persist = bool_setting(
            self.settings,
            "palette_history_persist",
            False,
        )
        stored_palette_history = self.settings.get("palette_history", [])
        if not self.palette_history_persist or not isinstance(
            stored_palette_history,
            list,
        ):
            stored_palette_history = []
        self.palette_history = PaletteCommandHistory(stored_palette_history)
        self.slash_commands_file = env_slash_commands_file()
        (
            self.custom_slash_commands,
            self.custom_slash_command_errors,
        ) = load_custom_slash_commands(
            self.slash_commands_file,
            built_in_names=built_in_palette_command_names(self.custom_theme_name),
        )
        visual_flash_setting = env_flag_value(
            "AGENT_PBX_TUI_VISUAL_FLASH", "AGENT_PBX_TUI_FLASH"
        )
        self.visual_flash_enabled = (
            bool_setting(self.settings, "visual_flash", False)
            if visual_flash is None
            else visual_flash
        )
        if visual_flash is None and visual_flash_setting is not None:
            self.visual_flash_enabled = visual_flash_setting
        terminal_bell_setting = env_flag_value(
            "AGENT_PBX_TUI_TERMINAL_BELL", "AGENT_PBX_TUI_BELL"
        )
        self.terminal_bell_enabled = (
            bool_setting(self.settings, "terminal_bell", False)
            if terminal_bell is None
            else terminal_bell
        )
        if terminal_bell is None and terminal_bell_setting is not None:
            self.terminal_bell_enabled = terminal_bell_setting
        agent_blink_setting = env_flag_value("AGENT_PBX_TUI_AGENT_BLINK")
        self.agent_blink_enabled = (
            bool_setting(self.settings, "agent_blink", True)
            if agent_blink is None
            else agent_blink
        )
        if agent_blink is None and agent_blink_setting is not None:
            self.agent_blink_enabled = agent_blink_setting
        low_power_setting = env_flag_value(
            "AGENT_PBX_TUI_LOW_POWER", "AGENT_PBX_TUI_WATCH_MODE"
        )
        self.low_power_enabled = bool_setting(self.settings, "low_power", False)
        if low_power_setting is not None:
            self.low_power_enabled = low_power_setting
        local_native_default = v2_defaults and is_local_server_url(self.server)
        tmux_direct_setting = env_flag_value("AGENT_PBX_TUI_TMUX")
        self.tmux_direct_enabled = (
            bool_setting(self.settings, "tmux_direct", local_native_default)
            if tmux_direct is None
            else tmux_direct
        )
        if tmux_direct is None and tmux_direct_setting is not None:
            self.tmux_direct_enabled = tmux_direct_setting
        self.tmux_direct_agent_modes = bool_map_setting(
            self.settings,
            "tmux_direct_agent_modes",
        )
        embedded_terminal_setting = env_flag_value(
            "AGENT_PBX_TUI_EMBEDDED_TERMINAL_V2"
        )
        embedded_terminal_requested = bool_setting(
            self.settings,
            "embedded_terminal_v2",
            local_native_default and self.tmux_direct_enabled,
        )
        if embedded_terminal_setting is not None:
            embedded_terminal_requested = embedded_terminal_setting
        self.tmux_features_available = tmux_features_available(
            tmux_direct_enabled=self.tmux_direct_enabled or embedded_terminal_requested
        )
        self.tmux_local_direct_context = (
            self.tmux_features_available and is_local_server_url(self.server)
        )
        if self.tmux_direct_enabled and not self.tmux_features_available:
            self.tmux_direct_enabled = False
        if not self.tmux_features_available:
            self.tmux_direct_agent_modes = {}
        runtime_mode_value = (
            os.getenv("AGENT_PBX_TUI_TMUX_RUNTIME_SERVER_MODE")
            or self.settings.get(
                "tmux_runtime_server_mode",
                DEFAULT_TMUX_RUNTIME_SERVER_MODE,
            )
        )
        self.tmux_runtime_server_mode = normalize_runtime_server_mode(
            runtime_mode_value
        ).value
        self.tmux_runtime_server = resolve_runtime_tmux_server(
            self.tmux_runtime_server_mode
        )
        self.embedded_terminal_v2_enabled = embedded_terminal_requested
        if not self.tmux_local_direct_context:
            self.embedded_terminal_v2_enabled = False
        self.embedded_terminal_scroll_mode = normalize_embedded_scroll_mode(
            self.settings.get(
                "embedded_terminal_scroll_mode",
                EMBEDDED_SCROLL_MODE_TMUX,
            )
        )
        self.tmux_popout_mode = str_setting(
            self.settings,
            "tmux_popout_mode",
            DEFAULT_TMUX_POPOUT_MODE,
        )
        capture_lines_setting = int_setting(
            self.settings,
            "tmux_capture_lines",
            DEFAULT_TMUX_CAPTURE_LINES,
        )
        if capture_lines_setting < 0:
            capture_lines_setting = DEFAULT_TMUX_CAPTURE_LINES
        env_capture_lines = env_tmux_capture_lines_value()
        if tmux_capture_lines is not None and tmux_capture_lines >= 0:
            self.tmux_capture_lines = tmux_capture_lines
        elif env_capture_lines is not None:
            self.tmux_capture_lines = env_capture_lines
        else:
            self.tmux_capture_lines = capture_lines_setting
        self.tmux_refresh_seconds = (
            env_tmux_refresh_seconds_value() or DEFAULT_TMUX_REFRESH_SECONDS
        )
        self.agent_refresh_seconds = self.resolve_agent_refresh_seconds()
        self.attention_blink_seconds = self.resolve_attention_blink_seconds()
        export_dir_setting = str_setting(
            self.settings,
            "export_dir",
            str(DEFAULT_EXPORT_DIR),
        )
        self.export_dir = (
            Path(export_dir).expanduser()
            if export_dir is not None
            else env_export_dir_value() or Path(export_dir_setting).expanduser()
        )
        theme_setting = str_setting(self.settings, "theme", DEFAULT_TUI_THEME)
        self.ui_theme = self.resolve_theme(
            theme_name or env_theme_value(custom_name=self.custom_theme_name) or theme_setting
        )
        self.theme = self.ui_theme
        layout_setting = str_setting(self.settings, "layout", DEFAULT_TUI_LAYOUT)
        self.layout_mode = resolve_layout(env_layout_value() or layout_setting)
        self.effective_layout_mode = self.compute_effective_layout()
        self.compact_view = "home"
        self.tiny_home_panel = TINY_HOME_AGENTS
        self.tiny_show_events = False
        self.show_hidden_agents = bool_setting(
            self.settings,
            "show_hidden_agents",
            False,
        )
        split_percent_setting = int_setting(
            self.settings,
            "split_percent",
            DEFAULT_SPLIT_PERCENT,
        )
        split_percent_env = env_split_percent_value()
        self.split_percent = (
            split_percent_env
            if split_percent_env is not None
            else clamp_split_percent(split_percent_setting)
        )
        self.joplin_copy_mode = normalize_joplin_copy_mode(
            self.settings.get("joplin_copy_mode", DEFAULT_JOPLIN_COPY_MODE)
        )
        self.joplin_paste_confirm_chars = max(
            0,
            int_setting(
                self.settings,
                "joplin_paste_confirm_chars",
                DEFAULT_JOPLIN_PASTE_CONFIRM_CHARS,
            ),
        )
        self.joplin_paste_confirm_lines = max(
            0,
            int_setting(
                self.settings,
                "joplin_paste_confirm_lines",
                DEFAULT_JOPLIN_PASTE_CONFIRM_LINES,
            ),
        )
        self.codex_terminal_mode = normalize_codex_terminal_mode(
            self.settings.get("codex_terminal_mode", DEFAULT_CODEX_TERMINAL_MODE)
        )
        self.detached_tmux_width = max(
            80,
            min(240, int_setting(self.settings, "detached_tmux_width", DEFAULT_DETACHED_TMUX_WIDTH)),
        )
        self.detached_tmux_height = max(
            24,
            min(80, int_setting(self.settings, "detached_tmux_height", DEFAULT_DETACHED_TMUX_HEIGHT)),
        )
        self.rendered_agent_columns: tuple[str, ...] = ()
        self.rendered_operator_columns: tuple[str, ...] = ()
        self.rendered_agents_signature: tuple[Any, ...] | None = None
        self.agent_table_order_lock: tuple[str, ...] | None = None
        self.operator_table_order_lock: tuple[str, ...] | None = None
        self.agents: dict[str, dict[str, Any]] = {}
        self.selected_agent_id: str | None = None
        self.agent_selection_generation = 0
        self.events: list[dict[str, Any]] = []
        self.latest_report_by_agent: dict[str, dict[str, Any]] = {}
        self.thread_items: dict[str, dict[str, Any]] = {}
        self.thread_order: list[str] = []
        self.selected_thread_item_id: str | None = None
        self.selected_thread_item_id_by_agent: dict[str, str] = {}
        self.selected_plan_option_index: int | None = None
        self.selected_latest_plan_option_index: int | None = None
        self.joplin_shortcut_pending = False
        self.marked_thread_item_ids: set[str] = set()
        self.active_agent_tab = "latest-tab"
        self.unseen_latest_agent_ids: set[str] = set()
        self.pending_handoff_approval_operator_ids: set[str] = set()
        self.reviewed_workerbee_run_signatures: dict[
            str, tuple[int, float | None]
        ] = {}
        self.workerbee_run_opening_operator_id: str | None = None
        self.reviewed_handoff_approval_signatures: dict[
            str, tuple[int, float | None]
        ] = {}
        self.handoff_approval_opening_operator_id: str | None = None
        self.reviewed_handoff_action_signatures: dict[
            str, tuple[int, float | None]
        ] = {}
        self.handoff_action_opening_operator_id: str | None = None
        self.reviewed_completion_receipt_signatures: dict[
            str, tuple[int, float | None]
        ] = {}
        self.completion_receipt_opening_operator_id: str | None = None
        self.local_starred_agent_ids = str_set_setting(
            self.settings,
            "starred_agent_ids",
        )
        self.starred_agent_ids = set(self.local_starred_agent_ids)
        self.remote_star_state_seen = False
        self.agent_last_seen_at: dict[str, float] = {}
        self.latest_viewed_at_by_agent = float_map_setting(
            self.settings,
            "latest_viewed_at_by_agent",
        )
        self.workerbee_status_by_agent: dict[str, dict[str, Any]] = {}
        self.workerbee_workspace_policy_by_agent: dict[str, dict[str, Any]] = {}
        self.workerbee_workspace_transitions_by_agent: dict[str, list[dict[str, Any]]] = {}
        self.workerbee_snapshot_policy_by_agent: dict[str, dict[str, Any]] = {}
        self.workerbee_workspace_controls_hidden = (
            str(os.getenv("AGENT_PBX_WORKERBEE_WORKSPACE_CONTROL_MODE") or "")
            .strip()
            .lower()
            == "hidden"
        )
        self.workerbee_snapshot_controls_hidden = (
            str(os.getenv("AGENT_PBX_WORKERBEE_SNAPSHOT_CONTROL_MODE") or "")
            .strip()
            .lower()
            == "hidden"
        )
        self.workerbee_controlled_run_controls_hidden = (
            str(os.getenv("AGENT_PBX_WORKERBEE_CONTROLLED_RUN_CONTROL_MODE") or "")
            .strip()
            .lower()
            == "hidden"
        )
        self.workerbee_access_controls_hidden = all(
            str(os.getenv(name) or "").strip().lower() == "hidden"
            for name in (
                "AGENT_PBX_WORKERBEE_ACCESS_CONTROL_MODE",
                "AGENT_PBX_WORKERBEE_SOURCE_MODE_CONTROL_MODE",
                "AGENT_PBX_WORKERBEE_EXECUTION_LANE_CONTROL_MODE",
            )
        )
        self.pull_request_status_by_agent: dict[str, dict[str, Any]] = {}
        self.pull_requests_by_agent: dict[str, dict[int, dict[str, Any]]] = {}
        self.selected_pull_request_number: int | None = None
        self.selected_pull_request_number_by_agent: dict[str, int] = {}
        self.issue_status_by_agent: dict[str, dict[str, Any]] = {}
        self.issues_by_agent: dict[str, dict[int, dict[str, Any]]] = {}
        self.selected_issue_number: int | None = None
        self.selected_issue_number_by_agent: dict[str, int] = {}
        self.action_registry = ActionRegistry()
        self.focus_generation = FocusGenerationGuard()
        self.async_generations = AsyncGenerationGate()
        self.event_stream_v2_enabled = bool_setting(
            self.settings,
            "event_stream_v2",
            v2_defaults,
        )
        event_stream_v2_setting = env_flag_value("AGENT_PBX_TUI_EVENT_STREAM_V2")
        if event_stream_v2_setting is not None:
            self.event_stream_v2_enabled = event_stream_v2_setting
        thread_compat_setting = env_flag_value(THREAD_ENV)
        self.legacy_thread_enabled = bool_setting(
            self.settings, "legacy_thread_enabled", True
        )
        if thread_compat_setting is not None:
            self.legacy_thread_enabled = thread_compat_setting
        terminal_capture_compat_setting = env_flag_value(TERMINAL_CAPTURE_ENV)
        self.legacy_terminal_capture_enabled = bool_setting(
            self.settings, "legacy_terminal_capture_enabled", True
        )
        if terminal_capture_compat_setting is not None:
            self.legacy_terminal_capture_enabled = terminal_capture_compat_setting
        self.remote_client_id = (
            os.getenv("AGENT_PBX_TUI_REMOTE_CLIENT_ID", "").strip()
            or str_setting(self.settings, "remote_client_id", "").strip()
            or f"tui-{uuid.uuid4().hex}"
        )
        self.remote_client_role = "local"
        self.remote_client_state_ready = False
        self.pending_remote_view_state: dict[str, Any] = {}
        self.function_key_passthrough = FunctionKeyPassthroughMap(
            modifier=str_setting(
                self.settings,
                "fkey_passthrough_modifier",
                "shift",
            )
        )
        self.register_core_actions()
        self.operator_panel_state = OperatorPanelState()
        self.campaigns_by_operator = self.operator_panel_state.campaigns_by_operator
        self.selected_campaign_id: str | None = None
        self.selected_campaign_id_by_operator = (
            self.operator_panel_state.selected_campaign_by_operator
        )
        self.selected_campaign_report_id_by_operator = (
            self.operator_panel_state.selected_report_by_operator
        )
        self.operator_kb_entries_by_operator = (
            self.operator_panel_state.kb_entries_by_operator
        )
        self.operator_kb_queries_by_operator = (
            self.operator_panel_state.kb_queries_by_operator
        )
        self.selected_operator_kb_id_by_operator: dict[str, str] = {}
        self.selected_operator_kb_query_id_by_operator: dict[str, str] = {}
        self.operator_kb_status_filter_by_operator: dict[str, str] = {}
        self.operator_kb_mode_by_operator: dict[str, str] = {}
        self.operator_kb_search_query_by_operator: dict[str, str] = {}
        self.joplin_configured = False
        self.joplin_available = False
        self.joplin_status: dict[str, Any] = {}
        self.joplin_panel_state = JoplinPanelState()
        self.joplin_notes_by_agent = self.joplin_panel_state.notes_by_scope
        self.joplin_list_fingerprint_by_scope: dict[
            str, tuple[tuple[object, ...], ...]
        ] = {}
        self.joplin_rendered_list_scope: str | None = None
        self.selected_joplin_note_id = self.joplin_panel_state.selected_note_id
        self.selected_joplin_note_id_by_agent = self.joplin_panel_state.selected_by_scope
        self.joplin_draft_timer: Timer | None = None
        self.joplin_sync_refresh_timer: Timer | None = None
        self.joplin_quit_armed_until = 0.0
        self.joplin_body_loading = False
        self.joplin_overwrite_armed_until: dict[str, float] = {}
        self.joplin_native_conflict_promote_armed_until: dict[str, float] = {}
        self.codex_session_path_cache = CodexSessionPathCache()
        self.codex_transcript_tail_cache = CodexTranscriptTailCache()
