    async def on_mount(self) -> None:
        self.api_client()
        self.apply_theme_class()
        self.update_effective_layout()
        self.apply_layout_class()
        # The web driver can mount with the browser's final dimensions before
        # child regions have completed their first layout. Re-apply the
        # height-dependent left-pane split on the first painted frame so the
        # demo does not need a synthetic browser resize to settle its panes.
        self.call_after_refresh(self.settle_initial_layout_geometry)
        self.apply_tmux_class()
        workspace_button = self.query_one_or_none("#workerbee-workspace", Button)
        if workspace_button is not None:
            workspace_button.display = not self.workerbee_workspace_controls_hidden
        snapshot_button = self.query_one_or_none("#workerbee-snapshot", Button)
        if snapshot_button is not None:
            snapshot_button.display = not self.workerbee_snapshot_controls_hidden
        access_button = self.query_one_or_none("#workerbee-access", Button)
        if access_button is not None:
            access_button.display = not self.workerbee_access_controls_hidden
        agents = self.query_one("#agents", DataTable)
        self.render_agent_columns(agents)
        operators = self.query_one("#operators", DataTable)
        self.render_operator_columns(operators)
        events = self.query_one("#events", DataTable)
        events.add_columns("ID", "Type", "Subject")
        codex_config_fields = self.query_one("#codex-config-fields", DataTable)
        codex_config_fields.add_columns("Key", "Value", "Status")
        thread = self.query_one("#thread", DataTable)
        thread.add_columns("M", "Time", "Kind", "Plan", "Status", "Summary")
        files = self.query_one("#files", DataTable)
        files.add_columns("Type", "Name", "Size", "Modified")
        file_search_results = self.query_one("#file-search-results", DataTable)
        file_search_results.add_columns("File", "Line", "Column", "Snippet")
        pull_requests = self.query_one("#pull-requests", DataTable)
        pull_requests.add_columns("#", "State", "Checks", "Title")
        issues = self.query_one("#issues", DataTable)
        issues.add_columns("#", "State", "Labels", "Title", "Updated")
        campaigns = self.query_one("#campaigns", DataTable)
        campaigns.add_columns("Status", "Assignments", "Title", "Updated")
        operator_kb = self.query_one("#operator-kb", DataTable)
        operator_kb.add_columns(
            "Status",
            "Redact",
            "Scope",
            "Project",
            "Title",
            "Tags",
            "Updated",
        )
        joplin_notes = self.query_one("#joplin-notes", DataTable)
        joplin_notes.add_columns("Updated", "Title")
        latest_plan_options = self.query_one("#latest-plan-options", DataTable)
        latest_plan_options.add_columns("#", "Option")
        plan_options = self.query_one("#plan-options", DataTable)
        plan_options.add_columns("#", "Option")
        self.update_hidden_agent_button()
        self.render_latest_plan_choice_panel(None)
        self.render_plan_choice_panel(None)
        if self.event_stream_v2_enabled:
            await self.initialize_remote_client_state()
        if self.remote_client_role != "observer":
            await self.refresh_joplin_status()
            await self.load_codex_config()
        await self.refresh_agents()
        await self.refresh_events()
        self.apply_pending_remote_view_state()
        if is_local_server_url(self.server):
            self.run_worker(
                self.refresh_codex_posture(),
                name="codex-posture",
                group="codex-posture",
                exclusive=True,
                exit_on_error=False,
            )
        self.notify_custom_slash_command_errors()
        self.restart_refresh_timers()
        self.tmux_writer_lease_timer = self.set_interval(
            TMUX_WRITER_RENEW_SECONDS,
            self.schedule_tmux_writer_lease_renewal,
        )
        if self.operator_broker_policy_error:
            self.notify(
                f"Operator broker policy is disabled: {self.operator_broker_policy_error}",
                severity="error",
            )
        elif (
            self.operator_broker_posture.root_operator_enabled
            and self.remote_client_role != "observer"
            and is_local_server_url(self.server)
        ):
            self.operator_broker_timer = self.set_interval(
                OPERATOR_BROKER_REFRESH_SECONDS,
                self.schedule_operator_broker_requests,
            )
            self.schedule_operator_broker_requests()
        self.run_worker(
            self.stream_events_v2() if self.event_stream_v2_enabled else self.stream_events(),
            name="events",
            group="event-stream",
            exclusive=True,
            exit_on_error=False,
        )

    def settle_initial_layout_geometry(self) -> None:
        if self.update_effective_layout(self.size.width, self.size.height):
            self.apply_layout_class()
        else:
            self.apply_layout_dimensions()

    async def on_unmount(self) -> None:
        self.shutting_down = True
        self.stop_refresh_timers()
        if self.tmux_writer_lease_timer is not None:
            self.tmux_writer_lease_timer.stop()
            self.tmux_writer_lease_timer = None
        if self.operator_broker_timer is not None:
            self.operator_broker_timer.stop()
            self.operator_broker_timer = None
        if self.remote_client_state_ready:
            await self.persist_remote_view_state(force=True)
        await self.detach_embedded_tmux_terminal(release_lease=True)
        if self.http_client is not None:
            await self.http_client.aclose()
            self.http_client = None

    def stop_refresh_timers(self) -> None:
        for timer in (
            self.agent_refresh_timer,
            self.tmux_refresh_timer,
            self.attention_blink_timer,
            self.runtime_health_timer,
        ):
            if timer is not None:
                timer.stop()
        self.agent_refresh_timer = None
        self.tmux_refresh_timer = None
        self.attention_blink_timer = None
        self.runtime_health_timer = None

    def restart_refresh_timers(self) -> None:
        self.stop_refresh_timers()
        self.agent_refresh_seconds = self.resolve_agent_refresh_seconds()
        self.attention_blink_seconds = self.resolve_attention_blink_seconds()
        self.agent_refresh_timer = self.set_interval(
            self.agent_refresh_seconds,
            self.schedule_refresh_agents,
        )
        self.tmux_refresh_timer = self.set_interval(
            self.tmux_refresh_seconds,
            self.schedule_refresh_tmux_capture,
        )
        self.attention_blink_timer = self.set_interval(
            self.attention_blink_seconds,
            self.toggle_unseen_attention,
        )
        self.runtime_health_expected_at = time.monotonic() + TUI_RUNTIME_HEALTH_SECONDS
        self.runtime_health_timer = self.set_interval(
            TUI_RUNTIME_HEALTH_SECONDS,
            self.sample_tui_runtime_health,
        )

    def schedule_refresh_agents(self, force: bool = False) -> None:
        now = time.monotonic()
        if (
            not force
            and self.event_stream_connected
            and self.last_agent_refresh_monotonic > 0
            and now - self.last_agent_refresh_monotonic
            < EVENT_STREAM_RECONCILE_SECONDS
        ):
            return
        self.agent_refresh_requested = True
        if self.agent_refresh_worker_active:
            return
        self.agent_refresh_worker_active = True
        self.run_worker(
            self.refresh_agents_coalesced,
            name="agents-periodic-refresh",
            group="agents-refresh",
            exclusive=False,
            exit_on_error=False,
        )

    async def refresh_agents_coalesced(self) -> None:
        """Serialize refreshes without canceling an in-flight HTTP response."""

        try:
            while self.agent_refresh_requested and not self.shutting_down:
                self.agent_refresh_requested = False
                await self.refresh_agents()
        finally:
            self.agent_refresh_worker_active = False

    def schedule_refresh_tmux_capture(self) -> None:
        self.run_worker(
            self.refresh_tmux_capture_if_active,
            name="tmux-periodic-refresh",
            group="tmux-refresh",
            exclusive=True,
        )

    def sample_tui_runtime_health(self) -> None:
        """Publish bounded event-loop and terminal throughput diagnostics."""

        now = time.monotonic()
        if self.runtime_health_expected_at > 0:
            self.runtime_health_lag_samples.append(
                max(0.0, now - self.runtime_health_expected_at)
            )
        self.runtime_health_expected_at = now + TUI_RUNTIME_HEALTH_SECONDS

        terminal_rate = 0.0
        paint_rate = 0.0
        coalesced_percent = 0.0
        surface = self.query_one_or_none(
            "#pbx-terminal-surface", PbxTerminalSurface
        )
        if surface is not None and surface.attached:
            snapshot = surface.performance_snapshot()
            if (
                surface.target == self.runtime_health_terminal_target
                and self.runtime_health_terminal_snapshot is not None
                and self.runtime_health_terminal_at > 0
            ):
                elapsed = max(0.001, now - self.runtime_health_terminal_at)
                previous = self.runtime_health_terminal_snapshot
                terminal_rate = max(0, snapshot.pty_bytes - previous.pty_bytes) / elapsed
                paint_rate = max(0, snapshot.render_calls - previous.render_calls) / elapsed
                paint_requests = max(
                    0,
                    snapshot.paint_requests - previous.paint_requests,
                )
                paint_suppressed = max(
                    0,
                    snapshot.paint_suppressed - previous.paint_suppressed,
                )
                if paint_requests:
                    coalesced_percent = 100.0 * paint_suppressed / paint_requests
            self.runtime_health_terminal_target = surface.target
            self.runtime_health_terminal_snapshot = snapshot
            self.runtime_health_terminal_at = now
        else:
            self.runtime_health_terminal_target = ""
            self.runtime_health_terminal_snapshot = None
            self.runtime_health_terminal_at = 0.0

        lag_ms = 0.0
        if self.runtime_health_lag_samples:
            ordered = sorted(self.runtime_health_lag_samples)
            lag_ms = ordered[min(len(ordered) - 1, int(len(ordered) * 0.95))] * 1000
        rss_bytes = current_process_rss_bytes()
        rss_text = (
            f"{rss_bytes / (1024 * 1024):.0f} MiB"
            if rss_bytes is not None
            else "n/a"
        )
        stream_text = "event" if self.event_stream_connected else "poll"
        widget = self.query_one_or_none("#tui-runtime-health", Static)
        if widget is not None:
            widget.update(
                "UI: "
                f"{stream_text} · lag p95 {lag_ms:.0f} ms · RSS {rss_text} · "
                f"PTY {terminal_rate / 1024:.0f} KiB/s · "
                f"paint {paint_rate:.1f}/s · coalesce {coalesced_percent:.0f}%"
            )

    def action_command_palette(self) -> None:
        """Open the PBX palette while preserving Textual's native providers."""

        if self.use_command_palette and not PbxCommandPalette.is_open(self):
            self.push_screen(
                PbxCommandPalette(
                    self.palette_history,
                    on_record=self.palette_history_recorded,
                    id="--command-palette",
                )
            )

