    async def joplin_action_for_agent(self, agent_id: str, action: str) -> None:
        previous_agent_id = self.selected_agent_id
        if previous_agent_id != agent_id:
            self.save_current_agent_pane_state(previous_agent_id)
        self.selected_agent_id = agent_id
        agent_input = self.query_one_or_none("#agent-id", Input)
        if agent_input is not None:
            agent_input.value = agent_id
        if previous_agent_id != agent_id:
            self.restore_agent_drafts(agent_id)
        self.activate_joplin_tab()
        self.update_agent_title()
        if action == "open":
            await self.load_joplin_notes(agent_id)
        elif action == "refresh":
            await self.load_joplin_notes(agent_id)
        elif action == "new":
            self.open_joplin_title_modal(agent_id, action="new")
        elif action == "rename":
            self.open_joplin_title_modal(agent_id, action="rename")
        elif action == "delete":
            self.confirm_delete_joplin_note(agent_id)
        elif action == "copy":
            await self.copy_latest_to_joplin(agent_id)
        elif action == "copy-force":
            if self.is_tmux_direct_enabled(agent_id):
                await self.copy_tmux_response_to_joplin(agent_id, force=True)
            else:
                await self.copy_latest_report_to_joplin(agent_id)
        elif action == "copy-report":
            await self.copy_latest_report_to_joplin(agent_id)
        elif action == "log-start":
            await self.start_joplin_log(agent_id)
        elif action == "log-stop":
            await self.stop_joplin_log(agent_id)
        elif action == "save":
            await self.save_joplin_note(agent_id)
        elif action == "edit":
            await self.begin_joplin_edit(agent_id)
        elif action == "preview":
            await self.preview_joplin_draft(agent_id)
        elif action == "note-copy":
            await self.copy_joplin_note_to_clipboard(agent_id)
        elif action == "note-copy-source":
            await self.copy_joplin_note_to_clipboard(agent_id, force_source=True)
        elif action == "note-paste":
            await self.paste_joplin_note_from_clipboard(agent_id)
        elif action == "promote-conflict":
            await self.promote_joplin_native_conflict(agent_id)
        elif action == "retry-write":
            await self.retry_failed_joplin_write(agent_id)
        elif action == "sync":
            await self.sync_joplin_now(agent_id)
        else:
            self.notify(f"Unknown Joplin action: {action}", severity="warning")

    async def action_refresh(self) -> None:
        await self.refresh_agents()
        await self.refresh_events()
        await self.refresh_joplin_status()
        if self.selected_agent_id:
            await self.refresh_selected_agent(self.selected_agent_id)
            if self.active_agent_tab == "workerbee-tab":
                await self.load_workerbee_status(self.selected_agent_id)
            elif self.active_agent_tab == "pull-requests-tab":
                await self.load_pull_requests(self.selected_agent_id)
            elif self.active_agent_tab == "issues-tab":
                await self.load_issues(self.selected_agent_id)
            elif self.active_agent_tab == "operator-kb-tab":
                await self.load_operator_kb(self.selected_agent_id)
            elif self.active_agent_tab == "joplin-tab":
                await self.load_joplin_notes(self.selected_agent_id)

    async def action_quit(self) -> None:
        if self.joplin_panel_state.has_dirty_draft():
            now = time.monotonic()
            if now > self.joplin_quit_armed_until:
                self.joplin_quit_armed_until = now + 5.0
                self.notify(
                    "Unsaved Joplin drafts are protected. Press q again within 5 seconds to exit; drafts remain in daemon recovery state.",
                    severity="warning",
                )
                return
            for draft in tuple(self.joplin_panel_state.drafts_by_scope.values()):
                if not draft.dirty:
                    continue
                try:
                    response = await self.api_client().put(
                        f"/v1/joplin/edits/{quote(draft.edit_id, safe='')}/draft",
                        json={"title": draft.title, "body": draft.body},
                        headers=auth_headers(self.token),
                        timeout=10,
                    )
                    response.raise_for_status()
                except Exception as exc:
                    self.notify(
                        f"Unable to persist Joplin draft before exit: {exc}",
                        severity="error",
                    )
                    self.joplin_quit_armed_until = 0.0
                    return
        await super().action_quit()

