    async def action_focus_next_alert(self) -> None:
        try:
            active_screen = self.screen
        except ScreenStackError:
            active_screen = None
        if isinstance(active_screen, DynamicResourceApprovalScreen):
            active_screen.action_approve_selected()
            return
        if (
            self.handoff_approval_opening_operator_id is not None
            or self.handoff_action_opening_operator_id is not None
            or self.completion_receipt_opening_operator_id is not None
            or self.workerbee_run_opening_operator_id is not None
        ):
            self.notify(
                "Operator handoff approvals are already opening.",
                severity="information",
            )
            return
        active_workerbee = self.active_workerbee_controlled_run_screen()
        closed_workerbee = False
        if active_workerbee is not None:
            if self.screen is not active_workerbee:
                self.notify(
                    "Finish or cancel the current WorkerBee run action before cycling alerts.",
                    severity="warning",
                )
                return
            await active_workerbee.dismiss()
            closed_workerbee = True
        active_action = self.active_ready_action_screen()
        if active_action is not None:
            if self.screen is not active_action:
                self.notify(
                    "Finish or close the current ready action before cycling alerts.",
                    severity="warning",
                )
                return
            await active_action.dismiss()
        active_approval = self.active_handoff_approval_screen()
        closed_approval = False
        if active_approval is not None:
            if self.screen is not active_approval:
                self.notify(
                    "Finish or cancel the current handoff action before cycling alerts.",
                    severity="warning",
                )
                return
            await active_approval.dismiss()
            closed_approval = True
        active_completion = self.active_completion_receipt_screen()
        closed_completion = False
        if active_completion is not None:
            if self.screen is not active_completion:
                self.notify(
                    "Finish or close the current completion action before cycling alerts.",
                    severity="warning",
                )
                return
            await active_completion.dismiss()
            closed_completion = True
        workerbee_ids = self.unreviewed_workerbee_controlled_run_operators()
        if workerbee_ids:
            await self.open_workerbee_controlled_run_center(workerbee_ids[0])
            return
        approval_ids = self.unreviewed_handoff_operators()
        if approval_ids:
            await self.open_operator_handoff_approval_center(approval_ids[0])
            return
        completion_ids = self.unreviewed_completion_operators()
        if completion_ids:
            await self.open_operator_completion_center(completion_ids[0])
            return
        action_ids = self.unreviewed_handoff_action_operators()
        if action_ids:
            await self.open_operator_ready_action(action_ids[0])
            return
        agent_id = self.next_alert_agent_id()
        if agent_id is not None:
            if not await self.open_agent_latest(agent_id):
                self.notify(
                    f"Alert target {agent_id} is no longer available.",
                    severity="warning",
                )
                return
            # End any temporary event flash immediately. open_agent_latest() has
            # already acknowledged this entity's latest report and rerendering now
            # advances the banner to the next pending alert, if one exists.
            self.clear_flash(self.flash_generation)
            return
        remaining_workerbee = self.pending_workerbee_controlled_run_operators()
        if remaining_workerbee:
            if closed_workerbee:
                self.notify(
                    "No other alerts are pending; WorkerBee run review remains openable with F8."
                )
                return
            for operator_agent_id in remaining_workerbee:
                self.reviewed_workerbee_run_signatures.pop(operator_agent_id, None)
            await self.open_workerbee_controlled_run_center(remaining_workerbee[0])
            return
        remaining_approvals = self.pending_handoff_operators()
        if remaining_approvals:
            if closed_approval:
                self.notify(
                    "No other Agent or Operator alerts are pending; approval review remains openable with F8.",
                )
                return
            for operator_agent_id in remaining_approvals:
                self.reviewed_handoff_approval_signatures.pop(operator_agent_id, None)
            await self.open_operator_handoff_approval_center(remaining_approvals[0])
            return
        remaining_completions = self.pending_completion_operators()
        if remaining_completions:
            if closed_completion:
                self.notify(
                    "No other alerts are pending; completion receipts remain openable with F8.",
                )
                return
            for operator_agent_id in remaining_completions:
                self.reviewed_completion_receipt_signatures.pop(
                    operator_agent_id,
                    None,
                )
            await self.open_operator_completion_center(remaining_completions[0])
            return
        remaining_actions = self.ready_handoff_action_operators()
        if remaining_actions:
            for operator_agent_id in remaining_actions:
                self.reviewed_handoff_action_signatures.pop(operator_agent_id, None)
            await self.open_operator_ready_action(remaining_actions[0])
            return
        self.notify("No Agent or Operator alerts are pending.")

    async def open_agent_latest(self, agent_id: str) -> bool:
        if agent_id not in self.agents:
            return False
        self.record_navigation_destination()
        self.navigation_recording_suspended += 1
        try:
            self.activate_latest_tab()
            if self.is_compact_layout():
                self.move_agent_cursor(agent_id, focus=False)
            await self.select_agent(agent_id)
            selected_tab = self.active_agent_tab
            self.activate_latest_tab()
            if selected_tab != "latest-tab":
                if self.is_tmux_direct_enabled(agent_id):
                    await self.load_tmux_capture(agent_id)
                else:
                    await self.load_latest_report(agent_id)
            self.mark_latest_seen(agent_id)
            if self.is_compact_layout():
                detail = self.query_one_or_none("#detail", TextArea)
                if detail is not None:
                    detail.focus()
            else:
                self.focus_agent_row(agent_id)
        finally:
            self.navigation_recording_suspended = max(
                0,
                self.navigation_recording_suspended - 1,
            )
        self.record_navigation_destination()
        return True

    async def refresh_events(self) -> None:
        try:
            if self.remote_client_role == "observer":
                response = await self.api_client().get(
                    "/v2/events/snapshot",
                    params={"after_id": 0, "limit": 50, "include_state": "false"},
                    headers=auth_headers(self.token),
                )
            else:
                response = await self.api_client().get(
                    "/v1/events",
                    params={"tail": "true", "limit": 50},
                    headers=auth_headers(self.token),
                )
            response.raise_for_status()
            payload = response.json()
            if self.remote_client_role == "observer":
                raw_events = payload.get("events") if isinstance(payload, dict) else []
                self.events = list(raw_events or [])[-50:]
            else:
                self.events = payload[-50:]
        except Exception:
            return
        previous_last_seen_event_id = self.last_seen_event_id
        if self.events:
            self.last_seen_event_id = max(int(event["event_id"]) for event in self.events)
        if self.last_seen_event_id != previous_last_seen_event_id:
            self.save_settings()
        self.render_events()

    def selected_agent_detail_visible(self) -> bool:
        if not self.selected_agent_id:
            return False
        return not (self.is_collapsed_layout() and self.compact_view != "agent")

