    def focused_agent_table_id(self) -> str | None:
        try:
            focused = self.focused
        except ScreenStackError:
            focused = None
        if not isinstance(focused, DataTable):
            return None
        if focused.id == "agents":
            return self.agent_id_at_cursor()
        if focused.id == "operators":
            return self.operator_id_at_cursor()
        return None

    def selected_or_cursor_agent_id(self) -> str | None:
        focused_agent_id = self.focused_agent_table_id()
        if focused_agent_id:
            return focused_agent_id
        # Once focus leaves the entity tables (for example, for the command
        # palette), preserve the identity the operator explicitly selected.
        # A stale Agents-table cursor must not override a selected Operator.
        if self.selected_agent_id:
            return self.selected_agent_id
        cursor_agent_id = self.agent_id_at_cursor()
        if cursor_agent_id:
            return cursor_agent_id
        cursor_operator_id = self.operator_id_at_cursor()
        if cursor_operator_id:
            return cursor_operator_id
        agent_input = self.query_one_or_none("#agent-id", Input)
        if agent_input is not None:
            value = agent_input.value.strip()
            if value:
                return value
        return None

    def joplin_target_agent_id(
        self,
        *,
        focused: Widget | None = None,
    ) -> str | None:
        if focused is not None and isinstance(focused, DataTable):
            if focused.id == "agents":
                return self.agent_id_at_cursor()
            if focused.id == "operators":
                return self.operator_id_at_cursor()
        if focused is None:
            focused_agent_id = self.focused_agent_table_id()
            if focused_agent_id:
                return focused_agent_id
        agent_input = self.query_one_or_none("#agent-id", Input)
        if agent_input is not None:
            value = agent_input.value.strip()
            if value:
                return value
        if self.selected_agent_id:
            return self.selected_agent_id
        return None

    def palette_joplin_agent_id(self) -> str | None:
        agent_id = self.joplin_target_agent_id()
        if not agent_id:
            self.notify("Select an agent first.", severity="warning")
            return None
        agent_input = self.query_one_or_none("#agent-id", Input)
        if agent_input is not None:
            agent_input.value = agent_id
        self.selected_agent_id = agent_id
        return agent_id

    def toggle_selected_agent_star(self) -> None:
        agent_id = self.selected_or_cursor_agent_id()
        if not agent_id:
            self.notify("Select an agent before starring it.", severity="warning")
            return
        starred = agent_id not in self.starred_agent_ids
        self.update_agent_star_state(agent_id, starred=starred, focus=True)
        self.queue_agent_star_sync(agent_id, starred)
        self.notify(f"{'Starred' if starred else 'Unstarred'} {agent_id}.")

    def update_agent_star_state(
        self,
        agent_id: str,
        *,
        starred: bool,
        starred_at: float | None = None,
        focus: bool = False,
    ) -> None:
        if starred:
            self.starred_agent_ids.add(agent_id)
        else:
            self.starred_agent_ids.discard(agent_id)
        agent = self.agents.get(agent_id)
        if agent is not None:
            agent["starred"] = starred
            agent["starred_at"] = starred_at if starred else None
        self.save_settings()
        self.render_agents()
        if focus:
            self.focus_agent_row(agent_id)

    def queue_agent_star_sync(self, agent_id: str, starred: bool) -> None:
        if not self.is_running:
            return
        self.run_worker(
            self.set_agent_starred_remote(agent_id, starred=starred),
            name=f"agent-star-{agent_id}",
            group=f"agent-star-{agent_id}",
            exclusive=True,
        )

    async def set_agent_starred_remote(self, agent_id: str, *, starred: bool) -> None:
        try:
            method = self.api_client().post if starred else self.api_client().delete
            response = await method(
                f"/v1/agents/{agent_id}/star",
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            agent = response.json()
        except Exception:
            return
        if isinstance(agent, dict):
            if agent_id not in self.agents:
                self.agents[agent_id] = agent
            self.update_agent_star_state(
                agent_id,
                starred=bool(agent.get("starred")),
                starred_at=float_value(agent.get("starred_at")),
            )

    async def inspect_selected_lifecycle(self) -> None:
        agent_id = self.palette_agent_id()
        if agent_id is None:
            return
        try:
            response = await self.api_client().get(
                f"/v2/lifecycle/{agent_id}",
                headers=auth_headers(self.token),
                timeout=20,
            )
            response.raise_for_status()
            inspection = response.json()
        except Exception as exc:
            self.notify(f"Lifecycle inspection failed: {exc}", severity="error")
            return
        detail = self.query_one_or_none("#detail", TextArea)
        if detail is not None:
            detail.text = self.format_lifecycle_inspection(inspection)
        self.activate_latest_tab()
        self.notify(f"Inspected lifecycle state for {agent_id}.")

    async def preview_selected_lifecycle_repair(self) -> None:
        agent_id = self.palette_agent_id()
        if agent_id is None:
            return
        try:
            response = await self.api_client().post(
                f"/v2/lifecycle/{agent_id}/actions/repair_mapping/preview",
                headers=auth_headers(self.token),
                timeout=20,
            )
            response.raise_for_status()
            preview = response.json()
        except Exception as exc:
            self.notify(f"Runtime repair preview failed: {exc}", severity="error")
            return
        before = preview.get("before") if isinstance(preview, dict) else None
        if (
            isinstance(before, dict)
            and self.tmux_runtime_server.effective_mode is RuntimeServerMode.DEDICATED
            and str(before.get("server_id") or "") != self.tmux_runtime_server.server_id
        ):
            preview = {
                **preview,
                "safe": False,
                "reason": (
                    "repair candidate is on a different tmux server; use managed "
                    "cross-server resume after the source reaches a safe turn boundary"
                ),
            }
        self.latest_lifecycle_repair_preview_by_agent[agent_id] = preview
        detail = self.query_one_or_none("#detail", TextArea)
        if detail is not None:
            detail.text = self.format_lifecycle_repair_preview(preview)
        self.activate_latest_tab()
        if preview.get("safe"):
            self.notify("Runtime mapping repair is ready for explicit apply.")
        else:
            self.notify(
                f"Runtime mapping repair is guarded: {preview.get('reason') or 'unavailable'}",
                severity="warning",
            )

    async def apply_selected_lifecycle_repair(self) -> None:
        agent_id = self.palette_agent_id()
        if agent_id is None:
            return
        preview = self.latest_lifecycle_repair_preview_by_agent.get(agent_id)
        if not isinstance(preview, dict) or not preview.get("safe"):
            self.notify("Create a safe runtime repair preview first.", severity="warning")
            return
        try:
            response = await self.api_client().post(
                f"/v2/lifecycle/{agent_id}/actions/repair_mapping/apply",
                json={
                    "preview_token": str(preview.get("preview_token") or ""),
                    "metadata": {"source": "agent_pbx_tui"},
                },
                headers=auth_headers(self.token),
                timeout=30,
            )
            response.raise_for_status()
            result = response.json()
        except Exception as exc:
            self.notify(f"Runtime mapping repair failed: {exc}", severity="error")
            return
        self.latest_lifecycle_repair_preview_by_agent.pop(agent_id, None)
        mapping = result.get("mapping") if isinstance(result, dict) else None
        if isinstance(mapping, dict):
            self.tmux_runtime_mapping_by_agent[agent_id] = mapping
            pane_id = str(mapping.get("pane_id") or "")
            if pane_id:
                self.tmux_agent_targets[agent_id] = pane_id
        detail = self.query_one_or_none("#detail", TextArea)
        if detail is not None:
            detail.text = self.format_lifecycle_inspection(result.get("after") or {})
        await self.refresh_events()
        self.notify(f"Repaired runtime mapping for {agent_id}.")

    @staticmethod
    def format_lifecycle_inspection(payload: dict[str, Any]) -> str:
        agent = payload.get("agent") if isinstance(payload.get("agent"), dict) else {}
        codex = payload.get("codex") if isinstance(payload.get("codex"), dict) else {}
        workspace = (
            payload.get("workspace") if isinstance(payload.get("workspace"), dict) else {}
        )
        runtime = payload.get("runtime") if isinstance(payload.get("runtime"), dict) else {}
        actions = payload.get("actions") if isinstance(payload.get("actions"), dict) else {}
        lines = [
            f"Lifecycle: {payload.get('entity_id') or '-'}",
            f"Kind: {payload.get('entity_kind') or '-'}",
            f"State: {payload.get('lifecycle_state') or '-'}",
            f"PBX active: {agent.get('pbx_active')}",
            f"Starred: {agent.get('starred')} · Archived: {agent.get('archived')}",
            f"Codex session: {codex.get('session_id') or '-'}",
            f"Workspace: {workspace.get('path') or '-'} ({'ready' if workspace.get('available') else 'missing'})",
            f"Runtime: {runtime.get('state') or '-'} — {runtime.get('message') or ''}",
            "",
            "Guards:",
        ]
        guards = payload.get("guard_reasons")
        if guards:
            lines.extend(f"- {item}" for item in guards)
        else:
            lines.append("- none")
        lines.extend(["", "Actions:"])
        for action, state in sorted(actions.items()):
            if not isinstance(state, dict):
                continue
            marker = "ready" if state.get("available") else "guarded"
            reason = f" — {state.get('reason')}" if state.get("reason") else ""
            lines.append(f"- {action}: {marker}{reason}")
        return "\n".join(lines)

    @staticmethod
    def format_lifecycle_repair_preview(preview: dict[str, Any]) -> str:
        before = preview.get("before") if isinstance(preview.get("before"), dict) else {}
        candidate = (
            preview.get("candidate") if isinstance(preview.get("candidate"), dict) else {}
        )
        return "\n".join(
            [
                f"Runtime Repair Preview: {preview.get('entity_id') or '-'}",
                f"Safe: {bool(preview.get('safe'))}",
                f"Reason: {preview.get('reason') or '-'}",
                "",
                f"Recorded: {before.get('session_name') or '-'} {before.get('window_name') or '-'} {before.get('pane_id') or '-'}",
                f"Candidate: {candidate.get('session_name') or '-'} {candidate.get('window_name') or '-'} {candidate.get('pane_id') or '-'}",
                f"CWD: {candidate.get('cwd') or before.get('cwd') or '-'}",
                "",
                "Apply with /agent repair apply after reviewing this identity change.",
            ]
        )

    def agent_prune_request(self, preset: str) -> dict[str, Any]:
        return {
            "preset": preset,
            "min_age_days": 30.0,
            "include_hidden": False,
            "include_starred": False,
            "require_no_tmux_pane": True,
            "limit": 500,
            "metadata": {"source": "agent-pbx-tui"},
        }

    async def preview_agent_prune(self, preset: str = "terminal-callers") -> None:
        payload = self.agent_prune_request(preset)
        try:
            response = await self.api_client().post(
                "/v1/agents/prune/preview",
                json=payload,
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            preview = response.json()
        except Exception as exc:
            self.notify(f"Unable to preview agent prune: {exc}", severity="error")
            return
        self.latest_agent_prune_request = payload
        self.latest_agent_prune_preview = preview
        detail = self.query_one_or_none("#detail", TextArea)
        if detail is not None:
            detail.text = self.format_agent_prune_preview(preview)
        count = int(preview.get("candidate_count") or 0)
        if count:
            self.notify(f"Prune preview found {count} candidate(s); run /agents prune apply.")
        else:
            self.notify("Prune preview found no candidates.")

    async def apply_latest_agent_prune(self) -> None:
        if not self.latest_agent_prune_request or not self.latest_agent_prune_preview:
            self.notify("Run /agents prune before applying.", severity="warning")
            return
        count = int(self.latest_agent_prune_preview.get("candidate_count") or 0)
        if count <= 0:
            self.notify("Latest prune preview has no candidates.", severity="warning")
            return
        payload = dict(self.latest_agent_prune_request)
        metadata = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
        payload["metadata"] = {
            **metadata,
            "applied_from_tui_preview": True,
            "preview_candidate_count": count,
        }
        try:
            response = await self.api_client().post(
                "/v1/agents/prune/apply",
                json=payload,
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            result = response.json()
        except Exception as exc:
            self.notify(f"Unable to apply agent prune: {exc}", severity="error")
            return
        batch = result.get("batch") if isinstance(result, dict) else None
        if isinstance(batch, dict):
            self.last_agent_prune_batch_id = str(batch.get("batch_id") or "") or None
        detail = self.query_one_or_none("#detail", TextArea)
        if detail is not None:
            detail.text = self.format_agent_prune_apply(result)
        self.latest_agent_prune_request = None
        self.latest_agent_prune_preview = None
        await self.refresh_agents()
        await self.refresh_events()
        hidden = int(batch.get("hidden_count") or 0) if isinstance(batch, dict) else 0
        self.notify(f"Prune hid {hidden} agent(s).")

    async def latest_agent_prune_batch_id(self) -> str | None:
        if self.last_agent_prune_batch_id:
            return self.last_agent_prune_batch_id
        try:
            response = await self.api_client().get(
                "/v1/agents/prune/batches",
                params={"limit": "10"},
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            payload = response.json()
        except Exception:
            return None
        batches = payload.get("batches") if isinstance(payload, dict) else None
        if not isinstance(batches, list):
            return None
        for batch in batches:
            if isinstance(batch, dict) and batch.get("undone_at") is None:
                batch_id = str(batch.get("batch_id") or "").strip()
                if batch_id:
                    return batch_id
        return None

    async def undo_latest_agent_prune(self) -> None:
        batch_id = await self.latest_agent_prune_batch_id()
        if not batch_id:
            self.notify("No unapplied prune batch found to undo.", severity="warning")
            return
        try:
            response = await self.api_client().post(
                f"/v1/agents/prune/batches/{batch_id}/undo",
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            batch = response.json()
        except Exception as exc:
            self.notify(f"Unable to undo agent prune: {exc}", severity="error")
            return
        self.last_agent_prune_batch_id = None
        detail = self.query_one_or_none("#detail", TextArea)
        if detail is not None:
            detail.text = self.format_agent_prune_undo(batch)
        await self.refresh_agents()
        await self.refresh_events()
        undo_results = batch.get("undo_results") if isinstance(batch, dict) else []
        unhidden = sum(
            1
            for item in undo_results
            if isinstance(item, dict) and item.get("result") == "unhidden"
        )
        self.notify(f"Undo restored {unhidden} agent(s).")

    @staticmethod
    def agent_prune_skip_summary(preview: dict[str, Any]) -> list[str]:
        counts: dict[str, int] = {}
        for item in preview.get("skipped") or []:
            if not isinstance(item, dict):
                continue
            for reason in item.get("guard_reasons") or []:
                reason_text = str(reason)
                counts[reason_text] = counts.get(reason_text, 0) + 1
        return [f"- {reason}: {count}" for reason, count in sorted(counts.items())]

    def format_agent_prune_preview(self, preview: dict[str, Any]) -> str:
        candidates = [
            item for item in preview.get("candidates") or [] if isinstance(item, dict)
        ]
        lines = [
            "Agent Prune Preview",
            "",
            f"Preset: {preview.get('preset')}",
            f"Min age: {preview.get('min_age_days')} day(s)",
            "Mode: hide only; thread history retained",
            f"Candidates: {preview.get('candidate_count', 0)}",
            f"Protected/skipped: {preview.get('skipped_count', 0)}",
            "",
            "Candidates:",
        ]
        if not candidates:
            lines.append("- none")
        for item in candidates[:80]:
            age = float_value(item.get("age_days")) or 0.0
            lines.append(
                "- "
                f"{item.get('agent_id')} "
                f"[{item.get('project')}; {item.get('effective_status') or item.get('status')}; "
                f"{age:.1f}d]"
            )
        if len(candidates) > 80:
            lines.append(f"- ... {len(candidates) - 80} more")
        skip_lines = self.agent_prune_skip_summary(preview)
        if skip_lines:
            lines.extend(["", "Protected Skip Reasons:", *skip_lines])
        lines.extend(
            [
                "",
                "Run /agents prune apply to hide this exact class of agents using fresh live state.",
                "Run /agents prune undo after apply to restore the latest batch.",
            ]
        )
        return "\n".join(lines)

    @staticmethod
    def format_agent_prune_apply(result: dict[str, Any]) -> str:
        batch = result.get("batch") if isinstance(result, dict) else {}
        if not isinstance(batch, dict):
            batch = {}
        lines = [
            "Agent Prune Applied",
            "",
            f"Batch: {batch.get('batch_id')}",
            f"Preset: {batch.get('preset')}",
            "Mode: hide only; thread history retained",
            f"Hidden: {batch.get('hidden_count', 0)}",
            f"Skipped: {batch.get('skipped_count', 0)}",
            "",
            "Hidden Agents:",
        ]
        hidden = [
            item
            for item in batch.get("results") or []
            if isinstance(item, dict) and item.get("result") == "hidden"
        ]
        if not hidden:
            lines.append("- none")
        for item in hidden[:80]:
            lines.append(f"- {item.get('agent_id')} [{item.get('project')}]")
        if len(hidden) > 80:
            lines.append(f"- ... {len(hidden) - 80} more")
        lines.append("")
        lines.append("Run /agents prune undo to restore this batch.")
        return "\n".join(lines)

    @staticmethod
    def format_agent_prune_undo(batch: dict[str, Any]) -> str:
        undo_results = [
            item
            for item in batch.get("undo_results") or []
            if isinstance(item, dict)
        ]
        unhidden = [item for item in undo_results if item.get("result") == "unhidden"]
        skipped = [item for item in undo_results if item.get("result") == "skipped"]
        lines = [
            "Agent Prune Undo",
            "",
            f"Batch: {batch.get('batch_id')}",
            f"Restored: {len(unhidden)}",
            f"Skipped: {len(skipped)}",
            "",
            "Restored Agents:",
        ]
        if not unhidden:
            lines.append("- none")
        for item in unhidden[:80]:
            lines.append(f"- {item.get('agent_id')}")
        if len(unhidden) > 80:
            lines.append(f"- ... {len(unhidden) - 80} more")
        return "\n".join(lines)

    async def unhide_selected_agent(self) -> None:
        agent_id = self.selected_or_cursor_agent_id()
        if not agent_id:
            self.notify("Select a hidden agent before unhiding it.", severity="warning")
            return
        agent = self.agents.get(agent_id)
        if agent is not None and not self.is_hidden_agent(agent):
            self.notify(f"{agent_id} is not hidden.", severity="warning")
            return
        try:
            restored = await self.unhide_agent(agent_id)
        except Exception as exc:
            self.notify(f"Unable to unhide {agent_id}: {exc}", severity="error")
            return
        if isinstance(restored, dict):
            self.agents[agent_id] = restored
        detail = self.query_one_or_none("#detail", TextArea)
        if detail is not None:
            detail.text = f"Unhid {agent_id}.\n\nThe agent is visible in Agents again."
        self.notify(f"Unhid {agent_id}.")
        await self.refresh_agents()
        await self.refresh_events()

    def remember_cursor_after_agent_removal(self, agent_id: str) -> None:
        for table_id, attr in (
            ("#agents", "agent_cursor_fallback_row"),
            ("#operators", "operator_cursor_fallback_row"),
        ):
            table = self.query_one_or_none(table_id, DataTable)
            if table is None:
                continue
            try:
                row = table.get_row_index(agent_id)
            except Exception:
                continue
            next_count = max(0, table.row_count - 1)
            setattr(self, attr, min(row, max(0, next_count - 1)))

    async def dismiss_selected_agent(
        self,
        *,
        delete_thread: bool,
        agent_id: str | None = None,
        confirmed_operator_kill: bool = False,
    ) -> None:
        agent_id = agent_id or self.selected_or_cursor_agent_id()
        if not agent_id:
            self.notify("Select an agent before hiding it.", severity="warning")
            return
        pane_id = self.tui_owned_operator_pane_id(agent_id)
        if pane_id and not confirmed_operator_kill:
            self.push_screen(
                OperatorKillConfirmScreen(
                    agent_id=agent_id,
                    action="purge" if delete_thread else "hide",
                    delete_thread=delete_thread,
                )
            )
            return
        if pane_id and not await self.kill_tui_owned_operator_pane(agent_id):
            return
        self.remember_cursor_after_agent_removal(agent_id)
        try:
            await self.delete_agent(agent_id, delete_thread=delete_thread)
        except Exception as exc:
            self.notify(f"Unable to hide {agent_id}: {exc}", severity="error")
            return

        self.unseen_latest_agent_ids.discard(agent_id)
        self.latest_report_by_agent.pop(agent_id, None)
        self.codex_runtime_by_agent.pop(agent_id, None)
        self.workerbee_status_by_agent.pop(agent_id, None)
        self.pull_request_status_by_agent.pop(agent_id, None)
        self.pull_requests_by_agent.pop(agent_id, None)
        self.selected_pull_request_number_by_agent.pop(agent_id, None)
        self.issue_status_by_agent.pop(agent_id, None)
        self.issues_by_agent.pop(agent_id, None)
        self.selected_issue_number_by_agent.pop(agent_id, None)
        self.campaigns_by_operator.pop(agent_id, None)
        self.selected_campaign_id_by_operator.pop(agent_id, None)
        self.selected_campaign_report_id_by_operator.pop(agent_id, None)
        self.joplin_notes_by_agent.pop(agent_id, None)
        self.file_directory_entries_by_agent.pop(agent_id, None)
        self.active_agent_tab_by_agent.pop(agent_id, None)
        self.message_draft_by_agent.pop(agent_id, None)
        self.tmux_message_draft_by_agent.pop(agent_id, None)
        self.selected_thread_item_id_by_agent.pop(agent_id, None)
        self.tmux_liveness_by_agent.pop(agent_id, None)
        self.tmux_agent_targets.pop(agent_id, None)
        self.tmux_direct_agent_modes.pop(agent_id, None)
        self.tmux_manual_override_agent_ids.discard(agent_id)
        self.tmux_detached_agent_ids.discard(agent_id)
        if self.selected_agent_id == agent_id:
            self.selected_agent_id = None
            agent_input = self.query_one_or_none("#agent-id", Input)
            if agent_input is not None:
                agent_input.value = ""
            self.selected_thread_item_id = None
            self.selected_pull_request_number = None
            self.selected_issue_number = None
            self.thread_items = {}
            self.thread_order = []
            self.marked_thread_item_ids.clear()
            thread = self.query_one_or_none("#thread", DataTable)
            if thread is not None:
                thread.clear()
            thread_detail = self.query_one_or_none("#thread-detail", TextArea)
            if thread_detail is not None:
                thread_detail.text = ""
            if self.is_collapsed_layout():
                self.show_compact_home()

        detail = self.query_one_or_none("#detail", TextArea)
        if detail is not None:
            detail.text = (
                f"{'Purged' if delete_thread else 'Hidden'} {agent_id}.\n\n"
                + (
                    "Thread data was deleted. The agent will reappear if it "
                    "registers again."
                    if delete_thread
                    else "Thread data was retained. The agent will reappear "
                    "with its history if it registers again."
                )
            )
        self.notify(
            f"{'Purged' if delete_thread else 'Hidden'} {agent_id} from Agents."
        )
        await self.refresh_agents()
        await self.refresh_events()

    def next_operator_agent_id(self) -> str:
        index = 0
        while f"operator-{index}" in self.agents:
            index += 1
        return f"operator-{index}"

    def operator_fork_agent_id(
        self,
        logical_operator_id: str,
        source_caller_agent_id: str,
        source_codex_session_id: str,
        *,
        fork_track_id: str | None = None,
    ) -> str:
        resolved_track_id = self.normalize_operator_fork_track_id(fork_track_id)
        track_suffix = (
            ""
            if resolved_track_id == DEFAULT_OPERATOR_FORK_TRACK_ID
            else f"-{resolved_track_id}"
        )
        base = slugify(
            f"{logical_operator_id}-fork-{source_caller_agent_id}{track_suffix}"
        )[:96]
        digest_key = (
            f"{logical_operator_id}:{source_caller_agent_id}:"
            f"{source_codex_session_id}"
        )
        if resolved_track_id != DEFAULT_OPERATOR_FORK_TRACK_ID:
            digest_key = f"{digest_key}:{resolved_track_id}"
        digest = short_stable_hash(digest_key)
        return f"{base}-{digest}"

    def normalize_operator_fork_track_id(self, fork_track_id: str | None) -> str:
        normalized = slugify(fork_track_id or DEFAULT_OPERATOR_FORK_TRACK_ID).lower()
        return normalized[:80] or DEFAULT_OPERATOR_FORK_TRACK_ID

    def normalize_operator_fork_label(self, value: str | None, *, default: str) -> str:
        normalized = slugify(value or default).lower()
        return normalized[:80] or default

    def normalize_review_operator_fork_launch_mode(self, value: str | None) -> str:
        normalized = slugify(value or REVIEW_OPERATOR_FORK_LAUNCH_MODE_CODEX_FORK).lower()
        if normalized in {"fresh", "fresh-context", "fresh_context", "new", "start"}:
            return REVIEW_OPERATOR_FORK_LAUNCH_MODE_FRESH_CONTEXT
        return REVIEW_OPERATOR_FORK_LAUNCH_MODE_CODEX_FORK

    def review_operator_fork_launch_mode(self) -> str:
        return self.normalize_review_operator_fork_launch_mode(
            os.getenv(REVIEW_OPERATOR_FORK_LAUNCH_MODE_ENV)
        )

    def selected_caller_agent_id_for_fork(self) -> str | None:
        focused_agent_id = self.focused_agent_table_id()
        if focused_agent_id and focused_agent_id in self.agents:
            if self.agent_type(self.agents[focused_agent_id]) == CALLER_AGENT_TYPE:
                return focused_agent_id
        cursor_agent_id = self.agent_id_at_cursor()
        if cursor_agent_id and cursor_agent_id in self.agents:
            if self.agent_type(self.agents[cursor_agent_id]) == CALLER_AGENT_TYPE:
                return cursor_agent_id
        if self.selected_agent_id and self.selected_agent_id in self.agents:
            if self.agent_type(self.agents[self.selected_agent_id]) == CALLER_AGENT_TYPE:
                return self.selected_agent_id
        return None

    def start_operator_source_caller_agent_id(self) -> str | None:
        focused_agent_id = self.focused_agent_table_id()
        if focused_agent_id and focused_agent_id in self.agents:
            agent = self.agents[focused_agent_id]
            return (
                focused_agent_id
                if self.agent_type(agent) == CALLER_AGENT_TYPE
                else None
            )
        if self.selected_agent_id and self.selected_agent_id in self.agents:
            agent = self.agents[self.selected_agent_id]
            return (
                self.selected_agent_id
                if self.agent_type(agent) == CALLER_AGENT_TYPE
                else None
            )
        return None

    def focused_caller_agent_id_for_fork(self) -> str | None:
        try:
            focused = self.focused
        except ScreenStackError:
            focused = None
        if not isinstance(focused, DataTable) or focused.id != "agents":
            return None
        cursor_agent_id = self.agent_id_at_cursor()
        if cursor_agent_id and cursor_agent_id in self.agents:
            if self.agent_type(self.agents[cursor_agent_id]) == CALLER_AGENT_TYPE:
                return cursor_agent_id
        return None

    def operator_fork_start_blocker(self, source_caller_agent_id: str) -> str | None:
        caller = self.agents.get(source_caller_agent_id)
        if caller is None:
            return f"Caller {source_caller_agent_id} is not loaded."
        caller_metadata = (
            caller.get("metadata") if isinstance(caller.get("metadata"), dict) else {}
        )
        source_session_id = str(caller_metadata.get("codex_session_id") or "").strip()
        caller_cwd = str(caller_metadata.get("cwd") or "").strip()
        if not source_session_id:
            return f"{source_caller_agent_id} is missing metadata.codex_session_id."
        if not caller_cwd:
            return f"{source_caller_agent_id} is missing metadata.cwd."
        return None

    def operator_bootstrap_prompt(
        self,
        agent_id: str,
        cwd: str,
        *,
        logical_operator_id: str | None = None,
        source_caller_agent_id: str | None = None,
        source_codex_session_id: str | None = None,
        fork_track_id: str | None = None,
        fork_purpose: str | None = None,
        access_mode: str | None = None,
        source_cwd: str | None = None,
        work_root: str | None = None,
        review_launch_mode: str | None = None,
    ) -> str:
        logical_id = logical_operator_id or agent_id
        resolved_track_id = self.normalize_operator_fork_track_id(fork_track_id)
        resolved_purpose = self.normalize_operator_fork_label(
            fork_purpose,
            default=(
                DEFAULT_OPERATOR_FORK_PURPOSE
                if resolved_track_id == DEFAULT_OPERATOR_FORK_TRACK_ID
                else REVIEW_OPERATOR_FORK_PURPOSE
            ),
        )
        resolved_access_mode = self.normalize_operator_fork_label(
            access_mode,
            default=(
                DEFAULT_OPERATOR_FORK_ACCESS_MODE
                if resolved_purpose == DEFAULT_OPERATOR_FORK_PURPOSE
                else REVIEW_OPERATOR_FORK_ACCESS_MODE
            ),
        )
        resolved_review_launch_mode = self.normalize_review_operator_fork_launch_mode(
            review_launch_mode
        )
        extra = []
        if source_caller_agent_id:
            extra.extend(
                [
                    f"- metadata.operator_role: \"{OPERATOR_ROLE_FORK}\"",
                    f"- metadata.logical_operator_id: {logical_id}",
                    f"- metadata.source_caller_agent_id: {source_caller_agent_id}",
                    f"- metadata.source_codex_session_id: {source_codex_session_id or ''}",
                    f"- metadata.fork_track_id: {resolved_track_id}",
                    f"- metadata.fork_purpose: {resolved_purpose}",
                    f"- metadata.access_mode: {resolved_access_mode}",
                    f"- metadata.source_cwd: {source_cwd or cwd}",
                    f"- metadata.work_root: {work_root or cwd}",
                    "",
                    "This session is an Agent PBX fork associated with the "
                    "caller source and Codex session. "
                    "Keep work for this caller isolated in this fork and report "
                    "through Agent PBX for the logical operator to review. "
                    "This visible Agent PBX tmux pane is the fork. Native Codex "
                    "children may perform bounded local decomposition and inherit "
                    "this fork's workspace and tool restrictions, but may not act "
                    "as PBX identities, campaign assignees, or cross-project workers; "
                    "do not use the legacy multi_agent_v1 path. Register with Agent "
                    "PBX, then wait at the "
                    "Codex prompt for operator instructions. Do not begin "
                    "review or caller work until the operator sends a task.",
                    "",
                    "Startup readiness: after registration, call "
                    "pbx_operator_runbook once, send pbx_report_turn with "
                    "status=\"waiting\" and needs_input=true, then stop at the "
                    "Codex prompt until the operator sends a task.",
                ]
            )
            if resolved_purpose == REVIEW_OPERATOR_FORK_PURPOSE:
                extra.extend(
                    [
                        "",
                        "This is a review fork. Treat the caller source directory "
                        "as read-only. Put any generated notes, patches, logs, or "
                        "scratch files under metadata.work_root only. If review "
                        "findings require source edits, escalate them through "
                        "pbx_operator_route_review_escalation instead of editing "
                        "the caller project directly.",
                    ]
                )
                if (
                    resolved_review_launch_mode
                    == REVIEW_OPERATOR_FORK_LAUNCH_MODE_FRESH_CONTEXT
                ):
                    extra.extend(
                        [
                            "",
                            "This review fork was started as a fresh Codex session "
                            "instead of a Codex transcript continuation. Use the "
                            "source metadata, Agent PBX tools, KB context, and "
                            "operator prompts as the source of truth for context.",
                        ]
                    )
        else:
            extra.extend(
                [
                    f"- metadata.operator_role: \"{OPERATOR_ROLE_ROOT}\"",
                    "",
                    "This root operator session is the persistent coordination "
                    "pane for the logical operator. Keep campaign state, planning, "
                    "and human follow-up handling here. Caller-specific execution "
                    "runs only in visible Agent PBX fork sessions under this "
                    "operator; use @caller references and operator campaign tools "
                    "to target one or more forks without abandoning this root "
                    "session. The root operator must not implement caller repo "
                    "changes directly. Native Codex children may perform bounded "
                    "operator-local decomposition but inherit this session's policy "
                    "and may not become PBX assignees or route to peers; do not use "
                    "the legacy multi_agent_v1 path. If PBX fork delivery is "
                    "unavailable, mark the assignment blocked instead. Keep the root "
                    "turn active while campaign assignments are running and "
                    "periodically recheck campaign state until terminal.",
                ]
            )
        return "\n".join(
            [
                "Use Agent PBX as an operator agent.",
                "The TUI launched this Codex session with Agent PBX MCP "
                "configured and AGENT_PBX_TOKEN in the process environment.",
                "These launch-specific operator identity instructions override "
                "repository AGENTS.md guidance about caller agent registration.",
                "",
                "Register this session with:",
                f"- agent_id: {agent_id}",
                "- project: agent-pbx-operator",
                "- agent_type: operator",
                f"- metadata.cwd: {cwd}",
                '- metadata.pbx_mode: "report"',
                '- metadata.agent_type: "operator"',
                f"- metadata.reporting_agent_id: {agent_id}",
                *extra,
                "",
                "Every pbx_report_turn from this session must use "
                f"`agent_id={agent_id}`, `reporting_agent_id={agent_id}`, "
                f"and `metadata.reporting_agent_id={agent_id}`. Never report "
                "under a caller agent ID from this operator session; use "
                "operator campaign, fork, handoff, or KB tools for caller "
                "coordination.",
                "",
                "Call pbx_operator_runbook before starting campaign work. "
                "Use operator campaign tools to dispatch caller assignments, "
                "review caller threads, follow up until criteria are met or "
                "blocked, report each assignment state, and finish campaigns.",
            ]
        )

    def operator_fork_resume_identity(
        self,
        agent_id: str,
        *,
        cwd: str,
    ) -> dict[str, str] | None:
        """Return the durable fork identity required by a generic resume.

        A missing-pane resume is shared by root Operators and forks.  Forks must
        carry their source identity through the launch environment, PBX record,
        and bootstrap prompt; silently falling back to root semantics would let
        the resumed process coordinate outside its assigned fork boundary.
        """

        agent = self.agents.get(agent_id)
        if not isinstance(agent, dict) or self.operator_role(agent) != OPERATOR_ROLE_FORK:
            return None
        metadata = self.operator_metadata_for(agent_id)
        fork_track_id = self.normalize_operator_fork_track_id(
            str(metadata.get("fork_track_id") or "")
        )
        fork_purpose = self.normalize_operator_fork_label(
            str(metadata.get("fork_purpose") or ""),
            default=(
                DEFAULT_OPERATOR_FORK_PURPOSE
                if fork_track_id == DEFAULT_OPERATOR_FORK_TRACK_ID
                else REVIEW_OPERATOR_FORK_PURPOSE
            ),
        )
        identity = {
            "logical_operator_id": str(metadata.get("logical_operator_id") or "").strip(),
            "source_caller_agent_id": str(
                metadata.get("source_caller_agent_id") or ""
            ).strip(),
            "source_codex_session_id": str(
                metadata.get("source_codex_session_id") or ""
            ).strip(),
            "fork_track_id": fork_track_id,
            "fork_purpose": fork_purpose,
            "access_mode": self.normalize_operator_fork_label(
                str(metadata.get("access_mode") or ""),
                default=(
                    DEFAULT_OPERATOR_FORK_ACCESS_MODE
                    if fork_purpose == DEFAULT_OPERATOR_FORK_PURPOSE
                    else REVIEW_OPERATOR_FORK_ACCESS_MODE
                ),
            ),
            "source_cwd": str(metadata.get("source_cwd") or cwd).strip() or cwd,
            "work_root": str(
                metadata.get("work_root") or metadata.get("cwd") or cwd
            ).strip()
            or cwd,
            "review_launch_mode": self.normalize_review_operator_fork_launch_mode(
                str(metadata.get("review_launch_mode") or "")
            ),
        }
        missing = [
            key
            for key in (
                "logical_operator_id",
                "source_caller_agent_id",
                "source_codex_session_id",
            )
            if not identity[key]
        ]
        if missing:
            raise ValueError(
                f"Refused to resume {agent_id}: fork identity is missing "
                f"{', '.join(missing)}. Repair the fork mapping before resume."
            )
        return identity

    def operator_cwd(self) -> str:
        return os.getenv("AGENT_PBX_TUI_OPERATOR_CWD", os.getcwd()).strip() or os.getcwd()

    def operator_codex_command(self) -> str:
        return os.getenv("AGENT_PBX_TUI_CODEX_BIN", "codex").strip() or "codex"

    def operator_tmux_session_name(self) -> str:
        return (
            os.getenv("AGENT_PBX_TUI_OPERATOR_TMUX_SESSION", DEFAULT_OPERATOR_TMUX_SESSION)
            .strip()
            or DEFAULT_OPERATOR_TMUX_SESSION
        )

    def caller_tmux_session_name(self) -> str:
        return (
            os.getenv("AGENT_PBX_TUI_CALLER_TMUX_SESSION", self.operator_tmux_session_name())
            .strip()
            or self.operator_tmux_session_name()
        )

    def operator_launch_env(
        self,
        *,
        agent_id: str,
        cwd: str,
        mcp_url: str,
        model_preset: CodexModelPreset | None = None,
        operator_role: str = OPERATOR_ROLE_ROOT,
        logical_operator_id: str | None = None,
        source_caller_agent_id: str | None = None,
        source_codex_session_id: str | None = None,
        fork_track_id: str | None = None,
        fork_purpose: str | None = None,
        access_mode: str | None = None,
        source_cwd: str | None = None,
        work_root: str | None = None,
        review_launch_mode: str | None = None,
        workerbee_profile: str | None = None,
        workerbee_gateway_binding: Mapping[str, object] | None = None,
    ) -> dict[str, str]:
        logical_id = logical_operator_id or agent_id
        resolved_track_id = self.normalize_operator_fork_track_id(fork_track_id)
        resolved_purpose = self.normalize_operator_fork_label(
            fork_purpose,
            default=(
                DEFAULT_OPERATOR_FORK_PURPOSE
                if resolved_track_id == DEFAULT_OPERATOR_FORK_TRACK_ID
                else REVIEW_OPERATOR_FORK_PURPOSE
            ),
        )
        resolved_access_mode = self.normalize_operator_fork_label(
            access_mode,
            default=(
                DEFAULT_OPERATOR_FORK_ACCESS_MODE
                if resolved_purpose == DEFAULT_OPERATOR_FORK_PURPOSE
                else REVIEW_OPERATOR_FORK_ACCESS_MODE
            ),
        )
        resolved_review_launch_mode = self.normalize_review_operator_fork_launch_mode(
            review_launch_mode
        )
        env = {
            AGENT_PBX_SERVER_URL_ENV: self.server,
            AGENT_PBX_MCP_URL_ENV: mcp_url,
            "AGENT_PBX_AGENT_ID": agent_id,
            "AGENT_PBX_REPORTING_AGENT_ID": agent_id,
            "AGENT_PBX_AGENT_TYPE": OPERATOR_AGENT_TYPE,
            "AGENT_PBX_AGENT_PROJECT": "agent-pbx-operator",
            "AGENT_PBX_PBX_MODE": PBX_REPORT_MODE,
            "AGENT_PBX_OPERATOR_ID": agent_id,
            "AGENT_PBX_OPERATOR_ROLE": operator_role,
            "AGENT_PBX_LOGICAL_OPERATOR_ID": logical_id,
            "AGENT_PBX_OPERATOR_CWD": cwd,
            "AGENT_PBX_CWD": cwd,
            WORKERBEE_GATEWAY_TOKEN_ENV: "",
            "AGENT_PBX_WORKERBEE_BACKEND": "",
            "AGENT_PBX_WORKERBEE_BACKEND_GENERATION": "",
            "AGENT_PBX_WORKERBEE_WORKSPACE_BINDING_ID": "",
        }
        manifest_digest = self.mcp_tool_manifest_digest(agent_id)
        if manifest_digest:
            env[MCP_TOOL_MANIFEST_ENV] = manifest_digest
        if operator_role == OPERATOR_ROLE_FORK:
            env["AGENT_PBX_OPERATOR_FORK_TRACK_ID"] = resolved_track_id
            env["AGENT_PBX_OPERATOR_FORK_PURPOSE"] = resolved_purpose
            env["AGENT_PBX_OPERATOR_ACCESS_MODE"] = resolved_access_mode
            if resolved_purpose == REVIEW_OPERATOR_FORK_PURPOSE:
                env["AGENT_PBX_OPERATOR_FORK_LAUNCH_MODE"] = (
                    resolved_review_launch_mode
                )
        if source_caller_agent_id:
            env["AGENT_PBX_SOURCE_CALLER_AGENT_ID"] = source_caller_agent_id
        if source_codex_session_id:
            env["AGENT_PBX_SOURCE_CODEX_SESSION_ID"] = source_codex_session_id
        if source_cwd:
            env["AGENT_PBX_SOURCE_CWD"] = source_cwd
        if work_root:
            env["AGENT_PBX_OPERATOR_WORK_ROOT"] = work_root
        if model_preset is not None:
            env["AGENT_PBX_CODEX_MODEL_PRESET"] = model_preset.key
            env["AGENT_PBX_CODEX_MODEL"] = model_preset.model
            env["AGENT_PBX_CODEX_REASONING_EFFORT"] = model_preset.reasoning_effort
            if model_preset.reasoning_summary:
                env["AGENT_PBX_CODEX_REASONING_SUMMARY"] = (
                    model_preset.reasoning_summary
                )
            if model_preset.verbosity:
                env["AGENT_PBX_CODEX_VERBOSITY"] = model_preset.verbosity
        selected_workerbee_profile = str(workerbee_profile or "").strip()
        if not selected_workerbee_profile:
            agent = self.agents.get(agent_id)
            selected_workerbee_profile = (
                self.workerbee_profile_for_agent(agent)
                if isinstance(agent, dict)
                else WORKERBEE_PROFILE_LOCAL_DEPLOY
            )
        if selected_workerbee_profile not in WORKERBEE_ACCESS_PROFILES:
            raise WorkerBeeProfileIntentError(
                f"unsupported WorkerBee launch profile: {selected_workerbee_profile!r}"
            )
        env["AGENT_PBX_WORKERBEE_MCP_PROFILE"] = selected_workerbee_profile
        self.apply_workerbee_gateway_env(env, workerbee_gateway_binding)
        if self.token:
            env[AGENT_PBX_TOKEN_ENV] = self.token
        return managed_tmux_launch_environment(env, install=False)

    async def ensure_operator_auth_ready(self) -> bool:
        try:
            response = await self.api_client().get(
                "/v1/auth/check",
                headers=auth_headers(self.token),
            )
        except Exception as exc:
            self.notify(f"Unable to verify Agent PBX auth: {exc}", severity="error")
            return False
        if response.status_code in {401, 403}:
            if not self.token:
                self.notify(
                    "Agent PBX token is required to start an operator.",
                    severity="error",
                )
            else:
                self.notify("Agent PBX token was rejected.", severity="error")
            return False
        try:
            response.raise_for_status()
        except Exception as exc:
            self.notify(f"Unable to verify Agent PBX auth: {exc}", severity="error")
            return False
        return True

    async def configure_operator_codex_mcp(
        self,
        *,
        codex_command: str,
        mcp_url: str,
    ) -> None:
        await asyncio.to_thread(configure_codex_mcp, codex_command, mcp_url)

    def codex_home_dir(self) -> Path:
        configured = os.getenv("CODEX_HOME", "").strip()
        if configured:
            return Path(configured).expanduser()
        return Path.home() / ".codex"

    async def linked_edit_fork_git_admin_plan(
        self,
        work_root: str,
        *,
        fork_purpose: str,
        access_mode: str,
    ) -> LinkedWorktreeGitAdminPlan | None:
        roots = default_managed_project_roots(cwd=Path(work_root))
        return await asyncio.to_thread(
            qualify_linked_worktree_git_admin,
            work_root,
            approved_roots=roots,
            fork_purpose=fork_purpose,
            access_mode=access_mode,
            codex_home=self.codex_home_dir(),
        )

    @staticmethod
    def linked_edit_fork_config_overrides(
        plan: LinkedWorktreeGitAdminPlan | None,
        metadata: Mapping[str, object] | None = None,
    ) -> list[str]:
        if plan is None:
            return []
        if str((metadata or {}).get("operator_authority_profile") or "").strip() == "trusted-workbench":
            return []
        return [
            codex_config_override(key, value)
            for key, value in plan.config_overrides()
        ]

    def operator_resume_command(
        self,
        codex_command: str,
        session_id: str,
        *,
        cd: str | None = None,
        sandbox: str | None = None,
        config_overrides: Iterable[str] = (),
    ) -> str:
        command_parts = shlex.split(codex_command) if codex_command.strip() else ["codex"]
        resume_parts = [*command_parts, "resume"]
        if cd:
            resume_parts.extend(["--cd", cd])
        if sandbox:
            resume_parts.extend(["--sandbox", sandbox])
        for override in config_overrides:
            resume_parts.extend(["-c", override])
        resume_parts.append(session_id)
        return shlex.join(resume_parts)

    def operator_fork_command(
        self,
        codex_command: str,
        source_codex_session_id: str,
        prompt: str,
        *,
        cd: str | None = None,
        sandbox: str | None = None,
        config_overrides: Iterable[str] = (),
    ) -> str:
        command_parts = shlex.split(codex_command) if codex_command.strip() else ["codex"]
        fork_parts = [*command_parts, "fork"]
        if cd:
            fork_parts.extend(["--cd", cd])
        if sandbox:
            fork_parts.extend(["--sandbox", sandbox])
        for override in config_overrides:
            fork_parts.extend(["-c", override])
        fork_parts.extend([source_codex_session_id, prompt])
        return shlex.join(fork_parts)

    def codex_start_command(
        self,
        codex_command: str,
        prompt: str,
        *,
        cd: str | None = None,
        sandbox: str | None = None,
        config_overrides: Iterable[str] = (),
    ) -> str:
        command_parts = shlex.split(codex_command) if codex_command.strip() else ["codex"]
        start_parts = [*command_parts]
        if cd:
            start_parts.extend(["--cd", cd])
        if sandbox:
            start_parts.extend(["--sandbox", sandbox])
        for override in config_overrides:
            start_parts.extend(["-c", override])
        start_parts.append(prompt)
        return shlex.join(start_parts)

    def codex_interactive_command(
        self,
        codex_command: str,
        *,
        cd: str | None = None,
        sandbox: str | None = None,
        config_overrides: Iterable[str] = (),
    ) -> str:
        command_parts = shlex.split(codex_command) if codex_command.strip() else ["codex"]
        start_parts = list(command_parts)
        if cd:
            start_parts.extend(["--cd", cd])
        if sandbox:
            start_parts.extend(["--sandbox", sandbox])
        for override in config_overrides:
            start_parts.extend(["-c", override])
        return shlex.join(start_parts)

    def spawned_project_agent_id(self, project_slug: str) -> str:
        base = f"codex-{normalize_project_slug(project_slug, default='project')}"[:96]
        if base not in self.agents:
            return base
        index = 2
        while f"{base}-{index}" in self.agents:
            index += 1
        return f"{base}-{index}"

    def project_spawn_copy_ignore(self, _: str, names: list[str]) -> set[str]:
        ignored = set(PROJECT_SPAWN_COPY_EXCLUDES).intersection(names)
        ignored.update(name for name in names if name.endswith((".pyc", ".pyo")))
        return ignored

    def create_project_spawn_repo(self, request: dict[str, Any]) -> Path:
        preflight = validate_stored_project_spawn_preflight(request)
        source = preflight.source_path
        target = preflight.target_path
        mode = preflight.mode
        if mode == "clone_source" and (source / ".git").exists():
            result = subprocess.run(
                ["git", "clone", "--no-hardlinks", str(source), str(target)],
                capture_output=True,
                text=True,
                timeout=120,
            )
            if result.returncode != 0:
                raise RuntimeError(f"git clone failed: {process_error_summary(result)}")
            return target
        if mode == "clone_source":
            shutil.copytree(
                source,
                target,
                ignore=self.project_spawn_copy_ignore,
                symlinks=True,
                dirs_exist_ok=True,
            )
        else:
            target.mkdir(parents=True, exist_ok=True)
        result = subprocess.run(
            ["git", "init"],
            cwd=target,
            capture_output=True,
            text=True,
            timeout=30,
        )
        if result.returncode != 0:
            raise RuntimeError(f"git init failed: {process_error_summary(result)}")
        return target

    def spawned_project_bootstrap_prompt(
        self,
        *,
        agent_id: str,
        project: str,
        cwd: str,
        request: dict[str, Any],
    ) -> str:
        source_cwd = str(request.get("source_cwd") or "")
        return "\n".join(
            [
                "Use Agent PBX as a caller agent.",
                "The Agent PBX TUI created this project from an operator-mediated review request.",
                "Register this session with:",
                f"- agent_id: {agent_id}",
                f"- project: {project}",
                "- agent_type: caller",
                f"- metadata.cwd: {cwd}",
                '- metadata.pbx_mode: "report"',
                '- metadata.launched_by: "agent-pbx-tui"',
                f"- metadata.reporting_agent_id: {agent_id}",
                "",
                "Every pbx_report_turn from this session must use "
                f"`agent_id={agent_id}`, `reporting_agent_id={agent_id}`, "
                f"and `metadata.reporting_agent_id={agent_id}`.",
                "",
                f"Source project: {source_cwd}",
                f"Spawn request ID: {request.get('spawn_request_id')}",
                f"Review fork: {request.get('review_fork_agent_id')}",
                f"Mode: {request.get('mode')}",
                "",
                "Treat the source project as context unless the operator explicitly asks you to modify it.",
                "Work in the current project directory and report progress through Agent PBX.",
                "",
                "Initial instructions:",
                str(request.get("instructions") or "").strip(),
            ]
        )

    def caller_runtime_env(
        self,
        *,
        agent_id: str,
        project: str,
        cwd: str,
        mcp_url: str,
        model_preset: CodexModelPreset | None = None,
        workerbee_profile: str | None = None,
        workerbee_gateway_binding: Mapping[str, object] | None = None,
    ) -> dict[str, str]:
        env = {
            AGENT_PBX_SERVER_URL_ENV: self.server,
            AGENT_PBX_MCP_URL_ENV: mcp_url,
            "AGENT_PBX_AGENT_ID": agent_id,
            "AGENT_PBX_REPORTING_AGENT_ID": agent_id,
            "AGENT_PBX_AGENT_TYPE": CALLER_AGENT_TYPE,
            "AGENT_PBX_AGENT_PROJECT": project,
            "AGENT_PBX_PBX_MODE": PBX_REPORT_MODE,
            "AGENT_PBX_CWD": cwd,
            WORKERBEE_GATEWAY_TOKEN_ENV: "",
            "AGENT_PBX_WORKERBEE_BACKEND": "",
            "AGENT_PBX_WORKERBEE_BACKEND_GENERATION": "",
            "AGENT_PBX_WORKERBEE_WORKSPACE_BINDING_ID": "",
        }
        manifest_digest = self.mcp_tool_manifest_digest(agent_id)
        if manifest_digest:
            env[MCP_TOOL_MANIFEST_ENV] = manifest_digest
        if model_preset is not None:
            env["AGENT_PBX_CODEX_MODEL_PRESET"] = model_preset.key
            env["AGENT_PBX_CODEX_MODEL"] = model_preset.model
            env["AGENT_PBX_CODEX_REASONING_EFFORT"] = (
                model_preset.reasoning_effort
            )
            if model_preset.reasoning_summary:
                env["AGENT_PBX_CODEX_REASONING_SUMMARY"] = (
                    model_preset.reasoning_summary
                )
            if model_preset.verbosity:
                env["AGENT_PBX_CODEX_VERBOSITY"] = model_preset.verbosity
        normalized_workerbee_profile = str(
            workerbee_profile or WORKERBEE_PROFILE_LOCAL_DEPLOY
        ).strip()
        if normalized_workerbee_profile not in WORKERBEE_ACCESS_PROFILES:
            raise WorkerBeeProfileIntentError(
                f"unsupported WorkerBee launch profile: {normalized_workerbee_profile!r}"
            )
        env["AGENT_PBX_WORKERBEE_MCP_PROFILE"] = normalized_workerbee_profile
        self.apply_workerbee_gateway_env(env, workerbee_gateway_binding)
        if self.token:
            env[AGENT_PBX_TOKEN_ENV] = self.token
        return managed_tmux_launch_environment(env, install=False)

    @staticmethod
    def apply_workerbee_gateway_env(
        env: dict[str, str],
        binding: Mapping[str, object] | None,
    ) -> None:
        if not binding:
            return
        token = str(binding.get("token") or "").strip()
        if token:
            env[WORKERBEE_GATEWAY_TOKEN_ENV] = token
        lease = binding.get("lease") if isinstance(binding.get("lease"), dict) else {}
        workspace = (
            binding.get("workspace_binding")
            if isinstance(binding.get("workspace_binding"), dict)
            else {}
        )
        if lease.get("profile"):
            env["AGENT_PBX_WORKERBEE_MCP_PROFILE"] = str(lease["profile"])
        if lease.get("backend"):
            env["AGENT_PBX_WORKERBEE_BACKEND"] = str(lease["backend"])
        if lease.get("backend_generation") is not None:
            env["AGENT_PBX_WORKERBEE_BACKEND_GENERATION"] = str(
                lease["backend_generation"]
            )
        if workspace.get("binding_id"):
            env["AGENT_PBX_WORKERBEE_WORKSPACE_BINDING_ID"] = str(
                workspace["binding_id"]
            )

    def workerbee_profile_metadata(
        self,
        agent_id: str,
        metadata: Mapping[str, Any],
        *,
        profile: str,
        source_entity_id: str | None = None,
    ) -> dict[str, object]:
        intent = build_workerbee_profile_intent(
            agent_id,
            metadata,
            profile=profile,
            source_entity_id=source_entity_id,
        )
        return {
            CALLER_WORKERBEE_PROFILE_METADATA_KEY: intent.profile,
            WORKERBEE_PROFILE_INTENT_METADATA_KEY: intent.public_dict(),
        }

    async def operator_workerbee_server_authority(
        self,
        *,
        profile: str | None,
        expected_ceiling: str = "",
        expected_digest: str = "",
        durable_profile: bool = False,
    ) -> tuple[str, dict[str, str]]:
        """Resolve profile authority from the daemon, never the TUI environment."""

        try:
            response = await self.api_client().get(
                "/v2/workerbee/workspace-policy",
                headers=auth_headers(self.token),
                timeout=30,
            )
            response.raise_for_status()
            view = response.json()
        except Exception as exc:
            raise WorkerBeeProfileIntentError(
                "WorkerBee server policy evidence is unavailable"
            ) from exc
        if not isinstance(view, dict):
            raise WorkerBeeProfileIntentError(
                "WorkerBee server policy evidence is malformed"
            )
        access_posture = view.get("access_posture")
        if not isinstance(access_posture, dict):
            raise WorkerBeeProfileIntentError(
                "WorkerBee server access posture is unavailable"
            )
        configured_default = str(
            access_posture.get("operator_default_effective_profile") or ""
        ).strip()
        ceiling = str(access_posture.get("profile_ceiling") or "").strip()
        if configured_default not in {
            WORKERBEE_PROFILE_OBSERVE,
            WORKERBEE_PROFILE_LOCAL_DEPLOY,
            WORKERBEE_PROFILE_TRUSTED_WORKBENCH,
        } or ceiling not in {
            WORKERBEE_PROFILE_OBSERVE,
            WORKERBEE_PROFILE_LOCAL_DEPLOY,
            WORKERBEE_PROFILE_TRUSTED_WORKBENCH,
        }:
            raise WorkerBeeProfileIntentError(
                "WorkerBee server access posture contains an invalid Operator profile"
            )
        selected = str(profile or configured_default).strip()
        if selected not in {
            WORKERBEE_PROFILE_OBSERVE,
            WORKERBEE_PROFILE_LOCAL_DEPLOY,
            WORKERBEE_PROFILE_TRUSTED_WORKBENCH,
        } or WORKERBEE_PROFILE_RANK[selected] > WORKERBEE_PROFILE_RANK[ceiling]:
            if durable_profile:
                raise WorkerBeeProfileIntentError(
                    "existing WorkerBee profile exceeds the daemon-resolved ceiling; "
                    "a separately reviewed ready-mapping migration is required"
                )
            raise WorkerBeeProfileIntentError(
                "WorkerBee Operator profile exceeds the daemon-resolved ceiling"
            )
        if expected_ceiling:
            if expected_ceiling not in WORKERBEE_PROFILE_RANK:
                raise WorkerBeeProfileIntentError(
                    "WorkerBee durable access-profile ceiling is invalid"
                )
            if (
                WORKERBEE_PROFILE_RANK[expected_ceiling]
                > WORKERBEE_PROFILE_RANK[ceiling]
            ):
                raise WorkerBeeProfileIntentError(
                    "WorkerBee access-profile ceiling is stale or mismatched"
                )
        metadata = {WORKERBEE_PROFILE_CEILING_METADATA_KEY: ceiling}
        if selected != WORKERBEE_PROFILE_TRUSTED_WORKBENCH:
            return selected, metadata
        effective = view.get("effective")
        digest = str(view.get("effective_digest") or "").strip()
        if (
            not isinstance(effective, dict)
            or effective.get("policy") != "scoped-workbench"
            or not isinstance(effective.get("allowed_roots"), list)
            or not effective["allowed_roots"]
            or any(
                not isinstance(root, str) or not root.strip()
                for root in effective["allowed_roots"]
            )
            or bool(view.get("constrained"))
            or re.fullmatch(r"[0-9a-f]{64}", digest) is None
        ):
            raise WorkerBeeProfileIntentError(
                "trusted-workbench requires unconstrained scoped-workbench root-set evidence"
            )
        if expected_digest and expected_digest != digest:
            raise WorkerBeeProfileIntentError(
                "trusted-workbench workspace-policy digest is stale or mismatched"
            )
        metadata[WORKERBEE_WORKSPACE_POLICY_DIGEST_METADATA_KEY] = digest
        return selected, metadata

    async def prepare_workerbee_gateway_launch(
        self,
        *,
        agent_id: str,
        project: str,
        codex_session_id: str,
        profile: str,
        source_root: str | None = None,
    ) -> dict[str, Any] | None:
        """Prepare one exact backend workspace and a one-time launch lease."""

        try:
            runtime_response = await self.api_client().get(
                "/v2/workerbee/runtime",
                headers=auth_headers(self.token),
                timeout=30,
            )
            if runtime_response.status_code == 404:
                return None
            if runtime_response.status_code >= 400:
                raise WorkerBeeLaunchPreflightError.from_response(
                    runtime_response,
                    agent_id=agent_id,
                    phase="runtime discovery",
                )
            runtime_response.raise_for_status()
            runtime_posture = runtime_response.json()
            if not isinstance(runtime_posture, dict) or not isinstance(
                runtime_posture.get("selected"), dict
            ):
                return None
            workspace_payload: dict[str, object] = {
                "project": project,
                "source_root": source_root,
            }
            workspace_response = await self.api_client().post(
                f"/v2/agents/{quote(agent_id, safe='')}/workerbee/workspaces",
                json=workspace_payload,
                headers=auth_headers(self.token),
                timeout=330,
            )
            if workspace_response.status_code == 404:
                return None
            if workspace_response.status_code >= 400:
                raise WorkerBeeLaunchPreflightError.from_response(
                    workspace_response,
                    agent_id=agent_id,
                    phase="workspace staging",
                )
            workspace_response.raise_for_status()
            workspace = workspace_response.json()
            lease_response = await self.api_client().post(
                f"/v2/agents/{quote(agent_id, safe='')}/workerbee/leases",
                json={
                    "codex_session_id": codex_session_id,
                    "profile": profile,
                    "workspace_binding_id": workspace.get("binding_id"),
                },
                headers=auth_headers(self.token),
                timeout=30,
            )
            if lease_response.status_code >= 400:
                raise WorkerBeeLaunchPreflightError.from_response(
                    lease_response,
                    agent_id=agent_id,
                    phase="gateway lease",
                )
            lease_response.raise_for_status()
            binding = lease_response.json()
        except WorkerBeeLaunchPreflightError:
            raise
        except Exception as exc:
            raise RuntimeError(
                f"WorkerBee launch preflight failed for {agent_id}: {exc}. "
                "No Codex process was started or replaced."
            ) from exc
        if not isinstance(binding, dict) or not isinstance(workspace, dict):
            raise RuntimeError("WorkerBee runtime binding returned invalid data")
        lease = binding.get("lease") if isinstance(binding.get("lease"), dict) else {}
        if not (
            str(workspace.get("binding_id") or "").strip()
            and str(binding.get("gateway_url") or "").strip()
            and str(binding.get("token") or "").strip()
            and str(lease.get("lease_id") or "").strip()
        ):
            raise RuntimeError("WorkerBee runtime binding response is incomplete")
        binding["workspace_binding"] = workspace
        return binding

    async def prepare_operator_fork_workerbee_launch(
        self,
        *,
        fork_agent_id: str,
        logical_operator_id: str,
        source_session_id: str,
        source_root: str,
        fork_metadata: dict[str, Any],
        profile: str,
    ) -> tuple[str, dict[str, Any] | None]:
        """Revalidate inherited daemon authority before preparing a fork lease."""

        selected = profile
        if str(fork_metadata.get("fork_purpose") or "") != REVIEW_OPERATOR_FORK_PURPOSE:
            selected, server_metadata = (
                await self.operator_workerbee_server_authority(
                    profile=selected,
                    expected_ceiling=str(
                        fork_metadata.get(WORKERBEE_PROFILE_CEILING_METADATA_KEY)
                        or ""
                    ).strip(),
                    expected_digest=str(
                        fork_metadata.get(
                            WORKERBEE_WORKSPACE_POLICY_DIGEST_METADATA_KEY
                        )
                        or ""
                    ).strip(),
                    durable_profile=True,
                )
            )
            fork_metadata.update(server_metadata)
        fork_metadata.update(
            self.workerbee_profile_metadata(
                fork_agent_id,
                fork_metadata,
                profile=selected,
                source_entity_id=logical_operator_id,
            )
        )
        binding = await self.prepare_workerbee_gateway_launch(
            agent_id=fork_agent_id,
            project="agent-pbx-operator",
            codex_session_id=source_session_id,
            profile=selected,
            source_root=source_root,
        )
        fork_metadata.update(self.workerbee_gateway_metadata(binding))
        return selected, binding

    @staticmethod
    def workerbee_gateway_metadata(
        binding: Mapping[str, object] | None,
    ) -> dict[str, object]:
        if not binding:
            return {}
        lease = binding.get("lease") if isinstance(binding.get("lease"), dict) else {}
        workspace = (
            binding.get("workspace_binding")
            if isinstance(binding.get("workspace_binding"), dict)
            else {}
        )
        path_domain = (
            workspace.get("path_domain")
            if isinstance(workspace.get("path_domain"), dict)
            else {}
        )
        values = {
            WORKERBEE_WORKSPACE_BINDING_METADATA_KEY: workspace.get("binding_id"),
            WORKERBEE_GATEWAY_LEASE_METADATA_KEY: lease.get("lease_id"),
            "workerbee_bound_backend": lease.get("backend"),
            "workerbee_backend_generation": lease.get("backend_generation"),
            "workerbee_binding_state": workspace.get("state"),
            CALLER_WORKERBEE_PROFILE_METADATA_KEY: lease.get("profile"),
            WORKERBEE_WORKSPACE_POLICY_DIGEST_METADATA_KEY: path_domain.get(
                "workspace_policy_digest"
            ),
            "workerbee_path_domain_receipt_sha256": path_domain.get(
                "receipt_sha256"
            ),
        }
        return {key: value for key, value in values.items() if value is not None}

    def caller_launch_env(
        self,
        *,
        agent_id: str,
        project: str,
        cwd: str,
        mcp_url: str,
        request: dict[str, Any],
        workerbee_gateway_binding: Mapping[str, object] | None = None,
    ) -> dict[str, str]:
        env = self.caller_runtime_env(
            agent_id=agent_id,
            project=project,
            cwd=cwd,
            mcp_url=mcp_url,
            workerbee_profile=WORKERBEE_PROFILE_LOCAL_DEPLOY,
            workerbee_gateway_binding=workerbee_gateway_binding,
        )
        env.update(
            {
            "AGENT_PBX_PROJECT_SPAWN_REQUEST_ID": str(
                request.get("spawn_request_id") or ""
            ),
            }
        )
        source_caller = str(request.get("source_caller_agent_id") or "").strip()
        if source_caller:
            env["AGENT_PBX_SOURCE_CALLER_AGENT_ID"] = source_caller
        source_cwd = str(request.get("source_cwd") or "").strip()
        if source_cwd:
            env["AGENT_PBX_SOURCE_CWD"] = source_cwd
        return env

    async def register_spawned_project_caller(
        self,
        *,
        agent_id: str,
        project: str,
        cwd: str,
        pane_id: str,
        codex_command: str,
        mcp_url: str,
        request: dict[str, Any],
        tmux_session_name: str | None = None,
        workerbee_gateway_binding: Mapping[str, object] | None = None,
    ) -> dict[str, Any]:
        metadata = {
            "agent_type": CALLER_AGENT_TYPE,
            "pbx_mode": PBX_REPORT_MODE,
            "cwd": cwd,
            "reporting_agent_id": agent_id,
            "launched_by": "agent-pbx-tui",
            "server_url": self.server,
            "mcp_url": mcp_url,
            "token_env": AGENT_PBX_TOKEN_ENV,
            "tmux_session": tmux_session_name or self.caller_tmux_session_name(),
            "tmux_pane_id": pane_id,
            "codex_command": codex_command,
            "project_spawn_request_id": request.get("spawn_request_id"),
            "source_review_fork_id": request.get("review_fork_id"),
            "source_review_fork_agent_id": request.get("review_fork_agent_id"),
            "source_caller_agent_id": request.get("source_caller_agent_id"),
            "source_cwd": request.get("source_cwd"),
            "spawn_mode": request.get("mode"),
            **self.workerbee_gateway_metadata(workerbee_gateway_binding),
            **self.mcp_tool_manifest_metadata(agent_id),
        }
        metadata.update(
            self.workerbee_profile_metadata(
                agent_id,
                {**metadata, "agent_type": CALLER_AGENT_TYPE},
                profile=WORKERBEE_PROFILE_LOCAL_DEPLOY,
            )
        )
        response = await self.api_client().post(
            "/v1/agents/register",
            json={
                "agent_id": agent_id,
                "project": project,
                "name": agent_id,
                "agent_type": CALLER_AGENT_TYPE,
                "pbx_active": True,
                "metadata": metadata,
            },
            headers=auth_headers(self.token),
        )
        response.raise_for_status()
        agent = response.json()
        if isinstance(agent, dict):
            self.agents[agent_id] = agent
            return agent
        raise RuntimeError("spawned caller registration returned a non-object")

    def operator_root_metadata(
        self,
        agent_id: str,
        *,
        cwd: str,
        codex_command: str,
        mcp_url: str,
        session_name: str,
        tmux_pane_id: str | None = None,
        resumed_codex_session_id: str | None = None,
        operator_session_history: list[dict[str, Any]] | None = None,
        model_preset: CodexModelPreset | None = None,
        default_source_caller_agent_id: str | None = None,
        default_source_caller_project: str | None = None,
        default_source_codex_session_id: str | None = None,
        restart_mode: str | None = None,
    ) -> dict[str, Any]:
        metadata = {
            "agent_type": OPERATOR_AGENT_TYPE,
            "operator_role": OPERATOR_ROLE_ROOT,
            "pbx_mode": PBX_REPORT_MODE,
            "cwd": cwd,
            "reporting_agent_id": agent_id,
            "logical_only": False,
            "launched_by": "agent-pbx-tui",
            "server_url": self.server,
            "mcp_url": mcp_url,
            "token_env": AGENT_PBX_TOKEN_ENV,
            "tmux_session": session_name,
            "codex_command": codex_command,
            **self.mcp_tool_manifest_metadata(agent_id),
        }
        if any(
            value is not None
            for value in (
                default_source_caller_agent_id,
                default_source_caller_project,
                default_source_codex_session_id,
            )
        ):
            metadata.update(
                {
                    "default_source_caller_agent_id": default_source_caller_agent_id or "",
                    "default_source_caller_project": default_source_caller_project or "",
                    "default_source_codex_session_id": default_source_codex_session_id or "",
                }
            )
        if tmux_pane_id:
            metadata["tmux_pane_id"] = tmux_pane_id
        if resumed_codex_session_id:
            metadata["last_resume_codex_session_id"] = resumed_codex_session_id
        if operator_session_history is not None:
            metadata["operator_session_history"] = operator_session_history
        if restart_mode:
            metadata["last_tmux_restart_at"] = time.time()
            metadata["last_tmux_restart_mode"] = restart_mode
        if model_preset is not None:
            metadata.update(model_preset.metadata())
        return metadata

    async def register_operator_root(
        self,
        agent_id: str,
        *,
        cwd: str,
        codex_command: str,
        mcp_url: str,
        session_name: str,
        tmux_pane_id: str | None = None,
        resumed_codex_session_id: str | None = None,
        operator_session_history: list[dict[str, Any]] | None = None,
        model_preset: CodexModelPreset | None = None,
        default_source_caller_agent_id: str | None = None,
        default_source_caller_project: str | None = None,
        default_source_codex_session_id: str | None = None,
        restart_mode: str | None = None,
        workerbee_gateway_binding: Mapping[str, object] | None = None,
    ) -> dict[str, Any]:
        existing_entity = isinstance(self.agents.get(agent_id), dict)
        existing_metadata = self.operator_metadata_for(agent_id)
        generated_metadata = self.operator_root_metadata(
            agent_id,
            cwd=cwd,
            codex_command=codex_command,
            mcp_url=mcp_url,
            session_name=session_name,
            tmux_pane_id=tmux_pane_id,
            resumed_codex_session_id=resumed_codex_session_id,
            operator_session_history=operator_session_history,
            model_preset=model_preset,
            default_source_caller_agent_id=default_source_caller_agent_id,
            default_source_caller_project=default_source_caller_project,
            default_source_codex_session_id=default_source_codex_session_id,
            restart_mode=restart_mode,
        )
        profile_metadata = {
            **existing_metadata,
            **generated_metadata,
            "agent_type": OPERATOR_AGENT_TYPE,
        }
        lease_profile = (
            str(
                (workerbee_gateway_binding or {}).get("lease", {}).get("profile")
            ).strip()
            if isinstance((workerbee_gateway_binding or {}).get("lease"), dict)
            else ""
        )
        explicit_profile = has_explicit_workerbee_profile(profile_metadata)
        legacy_existing_profile = existing_entity and not explicit_profile
        entity_profile = configured_operator_workerbee_profile(
            agent_id,
            profile_metadata,
            configured_default=WORKERBEE_PROFILE_LOCAL_DEPLOY,
            existing_entity=existing_entity,
        )
        if lease_profile and existing_entity and lease_profile != entity_profile:
            raise WorkerBeeProfileIntentError(
                "WorkerBee lease profile does not match durable entity intent"
            )
        if legacy_existing_profile:
            workerbee_profile, _server_metadata = (
                await self.operator_workerbee_server_authority(
                    profile=lease_profile or entity_profile,
                    expected_ceiling=str(
                        profile_metadata.get(WORKERBEE_PROFILE_CEILING_METADATA_KEY)
                        or ""
                    ).strip(),
                    expected_digest=str(
                        profile_metadata.get(
                            WORKERBEE_WORKSPACE_POLICY_DIGEST_METADATA_KEY
                        )
                        or ""
                    ).strip(),
                    durable_profile=True,
                )
            )
        else:
            server_profile, server_metadata = (
                await self.operator_workerbee_server_authority(
                    profile=lease_profile or (entity_profile if explicit_profile else None),
                    expected_ceiling=str(
                        profile_metadata.get(WORKERBEE_PROFILE_CEILING_METADATA_KEY)
                        or ""
                    ).strip(),
                    expected_digest=str(
                        profile_metadata.get(
                            WORKERBEE_WORKSPACE_POLICY_DIGEST_METADATA_KEY
                        )
                        or ""
                    ).strip(),
                    durable_profile=explicit_profile,
                )
            )
            if not explicit_profile:
                profile_metadata.update(server_metadata)
            workerbee_profile = (
                entity_profile
                if explicit_profile
                else configured_operator_workerbee_profile(
                    agent_id,
                    profile_metadata,
                    configured_default=server_profile,
                    existing_entity=False,
                )
            )
        gateway_metadata = self.workerbee_gateway_metadata(workerbee_gateway_binding)
        if legacy_existing_profile:
            gateway_metadata.pop(CALLER_WORKERBEE_PROFILE_METADATA_KEY, None)
        profile_projection = (
            {}
            if legacy_existing_profile
            else self.workerbee_profile_metadata(
                agent_id,
                profile_metadata,
                profile=workerbee_profile,
            )
        )
        response = await self.api_client().post(
            "/v1/agents/register",
            json={
                "agent_id": agent_id,
                "project": "agent-pbx-operator",
                "name": agent_id,
                "agent_type": OPERATOR_AGENT_TYPE,
                "pbx_active": True,
                "metadata": {
                    **profile_metadata,
                    **gateway_metadata,
                    **profile_projection,
                },
            },
            headers=auth_headers(self.token),
        )
        response.raise_for_status()
        agent = response.json()
        if isinstance(agent, dict):
            self.agents[agent_id] = agent
            return agent
        raise RuntimeError("operator root registration returned a non-object")

    def operator_metadata_for(self, agent_id: str) -> dict[str, Any]:
        agent = self.agents.get(agent_id) or {}
        metadata = agent.get("metadata") if isinstance(agent.get("metadata"), dict) else {}
        return dict(metadata)

    def operator_session_history_entries(self, agent_id: str) -> list[dict[str, Any]]:
        metadata = self.operator_metadata_for(agent_id)
        entries: list[dict[str, Any]] = []
        for key in (
            "codex_session_id",
            "codex_thread_id",
            "fork_codex_session_id",
            "last_resume_codex_session_id",
        ):
            session_id = str(metadata.get(key) or "").strip()
            if session_id:
                entries.append(
                    {
                        "session_id": session_id,
                        "timestamp": float_value(metadata.get("last_seen_at")) or 0.0,
                        "source": f"metadata.{key}",
                    }
                )
        raw_history = metadata.get("operator_session_history")
        if isinstance(raw_history, list):
            for item in raw_history:
                if isinstance(item, str):
                    session_id = item.strip()
                    if session_id:
                        entries.append(
                            {
                                "session_id": session_id,
                                "timestamp": 0.0,
                                "source": "metadata.operator_session_history",
                            }
                        )
                    continue
                if not isinstance(item, dict):
                    continue
                session_id = str(item.get("session_id") or "").strip()
                if not session_id:
                    continue
                entries.append(
                    {
                        "session_id": session_id,
                        "timestamp": float_value(item.get("timestamp")) or 0.0,
                        "source": str(item.get("source") or "metadata.operator_session_history"),
                        "path": str(item.get("path") or ""),
                        "summary": str(item.get("summary") or ""),
                    }
                )
        return self.dedupe_operator_session_entries(entries)

    def dedupe_operator_session_entries(
        self,
        entries: Iterable[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        by_session: dict[str, dict[str, Any]] = {}
        for entry in entries:
            session_id = str(entry.get("session_id") or "").strip()
            if not session_id:
                continue
            timestamp = float_value(entry.get("timestamp")) or 0.0
            existing = by_session.get(session_id)
            if existing is None or timestamp >= (float_value(existing.get("timestamp")) or 0.0):
                by_session[session_id] = {**entry, "session_id": session_id, "timestamp": timestamp}
        return sorted(
            by_session.values(),
            key=lambda item: (
                float_value(item.get("timestamp")) or 0.0,
                str(item.get("session_id") or ""),
            ),
            reverse=True,
        )

    def current_operator_session_ids(self, agent_id: str) -> set[str]:
        metadata = self.operator_metadata_for(agent_id)
        session_ids: set[str] = set()
        for key in (
            "codex_session_id",
            "codex_thread_id",
            "fork_codex_session_id",
            "last_resume_codex_session_id",
        ):
            value = str(metadata.get(key) or "").strip()
            if value:
                session_ids.add(value)
        return session_ids

    def codex_invalid_encrypted_content_detected(self, text: str) -> bool:
        normalized = text.lower()
        return any(
            marker in normalized for marker in CODEX_INVALID_ENCRYPTED_CONTENT_MARKERS
        )

    async def review_fork_pane_has_invalid_encrypted_content(
        self,
        pane_id: str,
        *,
        tmux_bin: str = "tmux",
        socket_path: str | None = None,
    ) -> bool:
        attempts = max(1, int(REVIEW_FORK_HEALTH_CHECK_ATTEMPTS))
        interval = max(0.0, float(REVIEW_FORK_HEALTH_CHECK_INTERVAL_SECONDS))
        for attempt in range(attempts):
            if await self.tmux_pane_has_invalid_encrypted_content(
                pane_id,
                tmux_bin=tmux_bin,
                socket_path=socket_path,
            ):
                return True
            if attempt < attempts - 1 and interval > 0:
                await asyncio.sleep(interval)
        return False

    def operator_fork_matches_source_session(
        self,
        fork: dict[str, Any],
        *,
        logical_operator_id: str,
        source_caller_agent_id: str,
        source_codex_session_id: str,
    ) -> bool:
        metadata = fork.get("metadata") if isinstance(fork.get("metadata"), dict) else {}
        fork_logical_operator_id = str(
            fork.get("logical_operator_agent_id")
            or metadata.get("logical_operator_id")
            or ""
        ).strip()
        if fork_logical_operator_id and fork_logical_operator_id != logical_operator_id:
            return False
        fork_source_caller_agent_id = str(
            fork.get("source_caller_agent_id")
            or metadata.get("source_caller_agent_id")
            or ""
        ).strip()
        if fork_source_caller_agent_id != source_caller_agent_id:
            return False
        fork_source_codex_session_id = str(
            fork.get("source_codex_session_id")
            or metadata.get("source_codex_session_id")
            or ""
        ).strip()
        return fork_source_codex_session_id == source_codex_session_id

    def review_source_continuation_previously_disabled(
        self,
        forks: Iterable[dict[str, Any]],
        *,
        logical_operator_id: str,
        source_caller_agent_id: str,
        source_codex_session_id: str,
    ) -> bool:
        for fork in forks:
            if not isinstance(fork, dict):
                continue
            if not self.operator_fork_matches_source_session(
                fork,
                logical_operator_id=logical_operator_id,
                source_caller_agent_id=source_caller_agent_id,
                source_codex_session_id=source_codex_session_id,
            ):
                continue
            metadata = fork.get("metadata") if isinstance(fork.get("metadata"), dict) else {}
            fork_track = self.normalize_operator_fork_track_id(
                str(fork.get("fork_track_id") or metadata.get("fork_track_id") or "")
            )
            fork_purpose = self.normalize_operator_fork_label(
                str(fork.get("fork_purpose") or metadata.get("fork_purpose") or ""),
                default=(
                    DEFAULT_OPERATOR_FORK_PURPOSE
                    if fork_track == DEFAULT_OPERATOR_FORK_TRACK_ID
                    else REVIEW_OPERATOR_FORK_PURPOSE
                ),
            )
            if fork_purpose != REVIEW_OPERATOR_FORK_PURPOSE:
                continue
            reason = str(metadata.get("source_continuation_disabled_reason") or "")
            if self.codex_invalid_encrypted_content_detected(reason):
                return True
        return False

    def operator_session_tail_text(
        self,
        candidate: OperatorSessionCandidate,
        *,
        max_bytes: int,
    ) -> str:
        path_text = str(candidate.path or "").strip()
        if not path_text:
            return ""
        path = Path(path_text).expanduser()
        try:
            size = path.stat().st_size
        except OSError:
            return ""
        start_at = max(size - max(0, max_bytes), 0)
        try:
            with path.open("rb") as handle:
                handle.seek(start_at)
                if start_at:
                    handle.readline()
                return handle.read().decode("utf-8", errors="replace")
        except OSError:
            return ""

    def operator_session_has_invalid_encrypted_content(
        self,
        candidate: OperatorSessionCandidate,
    ) -> bool:
        return self.codex_invalid_encrypted_content_detected(
            self.operator_session_tail_text(
                candidate,
                max_bytes=OPERATOR_SESSION_HEALTH_SCAN_BYTES,
            )
        )

    async def tmux_pane_has_invalid_encrypted_content(
        self,
        pane_id: str,
        *,
        tmux_bin: str = "tmux",
        socket_path: str | None = None,
    ) -> bool:
        runtime_kwargs: dict[str, str | None]
        if socket_path is not None or tmux_bin != "tmux":
            runtime_kwargs = {"tmux_bin": tmux_bin, "socket_path": socket_path}
        else:
            runtime_kwargs = self.runtime_tmux_command_kwargs_for_pane(pane_id)
        try:
            captured = await asyncio.to_thread(
                tmux_support.capture_pane,
                pane_id,
                lines=REVIEW_FORK_HEALTH_CAPTURE_LINES,
                **runtime_kwargs,
            )
        except Exception:
            return False
        return self.codex_invalid_encrypted_content_detected(captured)

    def codex_history_summaries(self, codex_home: Path) -> dict[str, tuple[float, str]]:
        path = codex_home / "history.jsonl"
        if not path.is_file():
            return {}
        summaries: dict[str, tuple[float, str]] = {}
        try:
            with path.open("r", encoding="utf-8", errors="replace") as handle:
                for line in handle:
                    try:
                        payload = json.loads(line)
                    except json.JSONDecodeError:
                        continue
                    if not isinstance(payload, dict):
                        continue
                    session_id = str(payload.get("session_id") or "").strip()
                    if not session_id:
                        continue
                    timestamp = float_value(payload.get("ts")) or 0.0
                    text = str(payload.get("text") or "").strip()
                    summary = text.splitlines()[0][:180] if text else ""
                    existing = summaries.get(session_id)
                    if existing is None or timestamp >= existing[0]:
                        summaries[session_id] = (timestamp, summary)
        except OSError:
            return summaries
        return summaries

    def codex_session_file_id(self, path: Path) -> str:
        match = re.search(r"([0-9a-f]{8}-[0-9a-f-]{27})", path.name)
        return match.group(1) if match else ""

    def read_codex_session_meta(self, path: Path) -> dict[str, Any]:
        try:
            with path.open("r", encoding="utf-8", errors="replace") as handle:
                line = handle.readline()
        except OSError:
            return {}
        if not line:
            return {}
        try:
            payload = json.loads(line)
        except json.JSONDecodeError:
            return {}
        if not isinstance(payload, dict) or payload.get("type") != "session_meta":
            return {}
        session = payload.get("payload")
        return session if isinstance(session, dict) else {}

    def operator_session_file_matches(self, path: Path, agent_id: str) -> bool:
        try:
            with path.open("r", encoding="utf-8", errors="replace") as handle:
                for line in handle:
                    try:
                        item = json.loads(line)
                    except json.JSONDecodeError:
                        continue
                    if not isinstance(item, dict):
                        continue
                    payload = item.get("payload")
                    if not isinstance(payload, dict):
                        continue
                    if self.codex_record_registers_operator(payload, agent_id):
                        return True
                    if self.codex_record_contains_operator_bootstrap(payload, agent_id):
                        return True
        except OSError:
            return False
        return False

    def codex_record_registers_operator(
        self,
        payload: dict[str, Any],
        agent_id: str,
    ) -> bool:
        tool_name = str(payload.get("name") or "").strip()
        arguments: Any = payload.get("arguments")
        if payload.get("type") == "mcp_tool_call_end":
            invocation = payload.get("invocation")
            if not isinstance(invocation, dict):
                return False
            tool_name = str(invocation.get("tool") or "").strip()
            arguments = invocation.get("arguments")
        if tool_name != "pbx_register_agent":
            return False
        if isinstance(arguments, str):
            try:
                decoded = json.loads(arguments)
            except json.JSONDecodeError:
                decoded = {}
            arguments = decoded
        if not isinstance(arguments, dict):
            return False
        return (
            str(arguments.get("agent_id") or "").strip() == agent_id
            and str(arguments.get("project") or "").strip() == "agent-pbx-operator"
            and str(arguments.get("agent_type") or "").strip() == OPERATOR_AGENT_TYPE
        )

    def codex_record_contains_operator_bootstrap(
        self,
        payload: dict[str, Any],
        agent_id: str,
    ) -> bool:
        messages: list[str] = []
        if payload.get("type") == "user_message":
            messages.append(str(payload.get("message") or ""))
        elif payload.get("type") == "message" and payload.get("role") == "user":
            content = payload.get("content")
            if isinstance(content, list):
                for item in content:
                    if isinstance(item, dict):
                        messages.append(str(item.get("text") or item.get("input_text") or ""))
        for message in messages:
            if (
                "Use Agent PBX as an operator agent." in message
                and "Register this session with:" in message
                and f"- agent_id: {agent_id}" in message
                and "- agent_type: operator" in message
            ):
                return True
        return False

    def local_operator_codex_session_entries(
        self,
        agent_id: str,
        *,
        max_files: int = 500,
    ) -> list[dict[str, Any]]:
        codex_home = self.codex_home_dir()
        sessions_dir = codex_home / "sessions"
        if not sessions_dir.is_dir():
            return []
        metadata = self.operator_metadata_for(agent_id)
        operator_cwd = str(metadata.get("cwd") or self.operator_cwd()).strip()
        normalized_operator_cwd = (
            str(Path(operator_cwd).expanduser().resolve(strict=False))
            if operator_cwd
            else ""
        )
        summaries = self.codex_history_summaries(codex_home)
        candidates: list[tuple[float, Path]] = []
        for path in sessions_dir.rglob("*.jsonl"):
            try:
                candidates.append((path.stat().st_mtime, path))
            except OSError:
                continue
        entries: list[dict[str, Any]] = []
        for mtime, path in sorted(candidates, key=lambda item: item[0], reverse=True)[:max_files]:
            session_meta = self.read_codex_session_meta(path)
            session_id = str(session_meta.get("id") or self.codex_session_file_id(path)).strip()
            if not session_id:
                continue
            session_cwd = str(session_meta.get("cwd") or "").strip()
            if normalized_operator_cwd and session_cwd:
                normalized_session_cwd = str(
                    Path(session_cwd).expanduser().resolve(strict=False)
                )
                if normalized_session_cwd != normalized_operator_cwd:
                    continue
            if not self.operator_session_file_matches(path, agent_id):
                continue
            history_timestamp, summary = summaries.get(session_id, (0.0, ""))
            entries.append(
                {
                    "session_id": session_id,
                    "timestamp": history_timestamp or mtime,
                    "source": "codex.sessions",
                    "path": str(path),
                    "summary": summary,
                }
            )
        return self.dedupe_operator_session_entries(entries)

    def operator_session_candidates(self, agent_id: str) -> list[OperatorSessionCandidate]:
        raw_entries = [
            *self.operator_session_history_entries(agent_id),
            *self.local_operator_codex_session_entries(agent_id),
        ]
        return [
            OperatorSessionCandidate(
                session_id=str(entry.get("session_id") or ""),
                timestamp=float_value(entry.get("timestamp")) or 0.0,
                source=str(entry.get("source") or "unknown"),
                path=str(entry.get("path") or ""),
                summary=str(entry.get("summary") or ""),
            )
            for entry in self.dedupe_operator_session_entries(raw_entries)
        ]

    @staticmethod
    def codex_session_pbx_report_agent_id_from_record(
        record: dict[str, Any],
    ) -> str | None:
        payload = record.get("payload")
        if not isinstance(payload, dict):
            return None
        arguments: object | None = None
        if (
            payload.get("type") == "function_call"
            and payload.get("name") == "pbx_report_turn"
        ):
            arguments = payload.get("arguments")
        elif payload.get("type") == "mcp_tool_call_end":
            invocation = payload.get("invocation")
            if (
                isinstance(invocation, dict)
                and invocation.get("tool") == "pbx_report_turn"
            ):
                arguments = invocation.get("arguments")
        if isinstance(arguments, str):
            try:
                arguments = json.loads(arguments)
            except json.JSONDecodeError:
                return None
        if not isinstance(arguments, dict):
            return None
        agent_id = str(arguments.get("agent_id") or "").strip()
        return agent_id or None

    def operator_session_pbx_report_agent_ids(
        self,
        candidate: OperatorSessionCandidate,
    ) -> set[str]:
        path_text = str(candidate.path or "").strip()
        if not path_text:
            return set()
        path = Path(path_text).expanduser()
        try:
            size = path.stat().st_size
        except OSError:
            return set()
        start_at = max(size - OPERATOR_SESSION_IDENTITY_SCAN_BYTES, 0)
        try:
            with path.open("rb") as handle:
                handle.seek(start_at)
                if start_at:
                    handle.readline()
                text = handle.read().decode("utf-8", errors="replace")
        except OSError:
            return set()
        agent_ids: set[str] = set()
        for line in text.splitlines():
            if "pbx_report_turn" not in line:
                continue
            try:
                record = json.loads(line)
            except json.JSONDecodeError:
                continue
            agent_id = self.codex_session_pbx_report_agent_id_from_record(record)
            if agent_id:
                agent_ids.add(agent_id)
        return agent_ids

    def operator_session_has_report_identity_conflict(
        self,
        agent_id: str,
        candidate: OperatorSessionCandidate,
    ) -> bool:
        report_agent_ids = self.operator_session_pbx_report_agent_ids(candidate)
        return bool(report_agent_ids and report_agent_ids != {agent_id})

    def operator_resume_target(
        self,
        agent_id: str,
        candidates: list[OperatorSessionCandidate],
    ) -> OperatorSessionCandidate | None:
        if not candidates:
            return None
        safe_candidates = [
            candidate
            for candidate in candidates
            if (
                not self.operator_session_has_report_identity_conflict(
                    agent_id,
                    candidate,
                )
                and not self.operator_session_has_invalid_encrypted_content(candidate)
                and self.operator_session_can_resume(agent_id, candidate.session_id)
            )
        ]
        if not safe_candidates:
            return None
        candidates = safe_candidates
        current_session_ids = self.current_operator_session_ids(agent_id)
        for candidate in candidates:
            if candidate.session_id in current_session_ids:
                return candidate
        if (
            not current_session_ids
            and self.tmux_agent_targets.get(agent_id)
            and len(candidates) > 1
        ):
            return candidates[1]
        for candidate in candidates:
            if candidate.session_id not in current_session_ids:
                return candidate
        if self.tmux_agent_targets.get(agent_id) and len(candidates) > 1:
            return candidates[1]
        return candidates[0]

    def operator_session_history_metadata(
        self,
        agent_id: str,
        *,
        include: Iterable[OperatorSessionCandidate | dict[str, Any]] = (),
    ) -> list[dict[str, Any]]:
        entries = self.operator_session_history_entries(agent_id)
        for item in include:
            if isinstance(item, OperatorSessionCandidate):
                entries.append(
                    {
                        "session_id": item.session_id,
                        "timestamp": item.timestamp,
                        "source": item.source,
                        "path": item.path,
                        "summary": item.summary,
                    }
                )
            elif isinstance(item, dict):
                entries.append(dict(item))
        trimmed = self.dedupe_operator_session_entries(entries)[:20]
        return [
            {
                key: value
                for key, value in entry.items()
                if key in {"session_id", "timestamp", "source", "path", "summary"} and value
            }
            for entry in trimmed
        ]

    def format_operator_session_history(
        self,
        agent_id: str,
        candidates: list[OperatorSessionCandidate],
    ) -> str:
        resume_target = self.operator_resume_target(agent_id, candidates)
        current_session_ids = self.current_operator_session_ids(agent_id)
        lines = [
            f"Operator Session History: {agent_id}",
            "",
        ]
        if not candidates:
            lines.append("No local Codex sessions were found for this operator.")
            return "\n".join(lines)
        if resume_target is not None:
            lines.extend(
                [
                    f"Resume target: `{resume_target.session_id}`",
                    "",
                ]
            )
        for index, candidate in enumerate(candidates, start=1):
            marker = " current" if candidate.session_id in current_session_ids else ""
            created = (
                datetime.fromtimestamp(candidate.timestamp, timezone.utc).isoformat()
                if candidate.timestamp
                else "unknown time"
            )
            lines.append(f"{index}. `{candidate.session_id}`{marker}")
            lines.append(f"   source: {candidate.source}; updated: {created}")
            if candidate.summary:
                lines.append(f"   latest prompt: {candidate.summary}")
            if candidate.path:
                lines.append(f"   file: {candidate.path}")
        return "\n".join(lines)

    async def show_selected_operator_history(
        self,
        *,
        agent_id: str | None = None,
    ) -> None:
        agent_id = agent_id or self.selected_operator_agent_id()
        if not agent_id:
            return
        candidates = await asyncio.to_thread(self.operator_session_candidates, agent_id)
        resume_target = self.operator_resume_target(agent_id, candidates)
        self.push_screen(
            OperatorHistoryScreen(
                agent_id=agent_id,
                candidates=candidates,
                resume_target=resume_target,
            )
        )
        self.notify(f"Found {len(candidates)} operator session candidate(s) for {agent_id}.")

    async def refresh_operator_history_screen(
        self,
        screen: OperatorHistoryScreen,
    ) -> None:
        candidates = await asyncio.to_thread(
            self.operator_session_candidates,
            screen.agent_id,
        )
        screen.update_candidates(
            candidates,
            self.operator_resume_target(screen.agent_id, candidates),
        )
        self.notify(
            f"Refreshed {len(candidates)} operator session candidate(s) for "
            f"{screen.agent_id}."
        )

    async def record_operator_session_history(
        self,
        agent_id: str,
        *,
        include: Iterable[OperatorSessionCandidate | dict[str, Any]] = (),
    ) -> list[dict[str, Any]]:
        history = self.operator_session_history_metadata(agent_id, include=include)
        agent = self.agents.get(agent_id) or {"agent_id": agent_id}
        metadata = self.operator_metadata_for(agent_id)
        payload_metadata = {**metadata, "operator_session_history": history}
        response = await self.api_client().post(
            "/v1/agents/register",
            json={
                "agent_id": agent_id,
                "project": str(agent.get("project") or "agent-pbx-operator"),
                "name": str(agent.get("name") or agent_id),
                "agent_type": OPERATOR_AGENT_TYPE,
                "pbx_active": bool(agent.get("pbx_active", True)),
                "metadata": payload_metadata,
            },
            headers=auth_headers(self.token),
        )
        response.raise_for_status()
        updated = response.json()
        if isinstance(updated, dict):
            self.agents[agent_id] = updated
        return history

    async def live_operator_root_pane_id(self, agent_id: str) -> str | None:
        mapping = await self.fetch_tmux_runtime_mapping(agent_id)
        if isinstance(mapping, dict) and str(mapping.get("state") or "") == "ready":
            pane_id = str(mapping.get("pane_id") or "").strip()
            if pane_id:
                runtime_kwargs = self.runtime_tmux_command_kwargs(agent_id)
                try:
                    if await asyncio.to_thread(
                        tmux_support.pane_exists,
                        pane_id,
                        **runtime_kwargs,
                    ):
                        return pane_id
                except Exception:
                    pass
        try:
            panes = await asyncio.to_thread(tmux_support.list_panes)
        except Exception:
            return None
        agent = self.agents.get(
            agent_id,
            {"agent_id": agent_id, "agent_type": OPERATOR_AGENT_TYPE},
        )
        matches = [
            pane
            for pane in panes
            if self.tmux_pane_allowed_for_agent(agent, pane)
        ]
        saved = self.saved_tmux_target_pane_for_agent(agent_id, agent, panes)
        if saved is not None:
            return saved.pane_id
        if len(matches) == 1:
            return matches[0].pane_id
        if len(matches) > 1:
            pane_list = ", ".join(
                f"{pane.pane_id} ({pane.target_label})" for pane in matches
            )
            raise RuntimeError(
                f"multiple live tmux panes match {agent_id}: {pane_list}; "
                "select the intended pane or prune stale operator panes before reuse"
            )
        return None

    async def ensure_operator_root_from_tui(
        self,
        *,
        agent_id: str,
        cwd: str,
        codex_command: str,
        mcp_url: str,
        session_name: str,
        source_caller_agent_id: str | None = None,
    ) -> tuple[dict[str, Any], str, bool]:
        existing_metadata = self.operator_metadata_for(agent_id)
        launch_preset = (
            codex_model_preset_from_metadata(existing_metadata)
            or self.codex_model_policy.profile_for_role("operator")
        )
        source_caller = self.agents.get(source_caller_agent_id or "")
        source_metadata = (
            source_caller.get("metadata")
            if isinstance(source_caller, dict)
            and isinstance(source_caller.get("metadata"), dict)
            else {}
        )
        existing_agent = self.agents.get(agent_id)
        if isinstance(existing_agent, dict):
            pane_id = await self.live_operator_root_pane_id(agent_id)
            if pane_id:
                existing_metadata = self.operator_metadata_for(agent_id)
                existing_cwd = str(existing_metadata.get("cwd") or "").strip() or cwd
                agent = await self.register_operator_root(
                    agent_id,
                    cwd=existing_cwd,
                    codex_command=codex_command,
                    mcp_url=mcp_url,
                    session_name=session_name,
                    tmux_pane_id=pane_id,
                    default_source_caller_agent_id=source_caller_agent_id,
                    default_source_caller_project=(
                        str(source_caller.get("project") or "")
                        if isinstance(source_caller, dict)
                        else None
                    ),
                    default_source_codex_session_id=str(
                        source_metadata.get("codex_session_id") or ""
                    ),
                    model_preset=launch_preset,
                )
                self.tmux_agent_targets[agent_id] = pane_id
                self.tmux_detached_agent_ids.discard(agent_id)
                self.tmux_direct_agent_modes[agent_id] = True
                return agent, pane_id, False

        agent = await self.register_operator_root(
            agent_id,
            cwd=cwd,
            codex_command=codex_command,
            mcp_url=mcp_url,
            session_name=session_name,
            default_source_caller_agent_id=source_caller_agent_id,
            default_source_caller_project=(
                str(source_caller.get("project") or "")
                if isinstance(source_caller, dict)
                else None
            ),
            default_source_codex_session_id=str(
                source_metadata.get("codex_session_id") or ""
            ),
            model_preset=launch_preset,
        )
        pane_id = await self.live_operator_root_pane_id(agent_id)
        if pane_id:
            self.tmux_agent_targets[agent_id] = pane_id
            self.tmux_detached_agent_ids.discard(agent_id)
            self.tmux_direct_agent_modes[agent_id] = True
            metadata = agent.get("metadata") if isinstance(agent.get("metadata"), dict) else {}
            if metadata.get("tmux_pane_id") != pane_id:
                agent = await self.register_operator_root(
                    agent_id,
                    cwd=cwd,
                    codex_command=codex_command,
                    mcp_url=mcp_url,
                    session_name=session_name,
                    tmux_pane_id=pane_id,
                    default_source_caller_agent_id=source_caller_agent_id,
                    default_source_caller_project=(
                        str(source_caller.get("project") or "")
                        if isinstance(source_caller, dict)
                        else None
                    ),
                    default_source_codex_session_id=str(
                        source_metadata.get("codex_session_id") or ""
                    ),
                    model_preset=launch_preset,
                )
            return agent, pane_id, False

        workerbee_gateway_binding = await self.prepare_workerbee_gateway_launch(
            agent_id=agent_id,
            project="agent-pbx-operator",
            codex_session_id="",
            profile=self.workerbee_profile_for_agent(agent),
            source_root=cwd,
        )
        runtime_session_name, runtime_kwargs = await self.configured_runtime_launch_target(
            agent_id,
            fallback_session_name=session_name,
        )
        pane_id = await asyncio.to_thread(
            tmux_support.launch_pane,
            session_name=runtime_session_name,
            window_name=agent_id,
            command=self.codex_interactive_command(
                codex_command,
                cd=cwd,
                sandbox=operator_authority_sandbox(existing_metadata),
                config_overrides=operator_agent_config_overrides(
                    mcp_url=mcp_url,
                    codex_home=self.codex_home_dir(),
                    work_root=cwd,
                    include_campaign_lifecycle=True,
                    terminal_mode=self.codex_terminal_mode,
                    workerbee_gateway_binding=workerbee_gateway_binding,
                    authority_metadata=existing_metadata,
                )
                + codex_model_preset_config_overrides(launch_preset),
            ),
            cwd=cwd,
            env=self.operator_launch_env(
                agent_id=agent_id,
                cwd=cwd,
                mcp_url=mcp_url,
                model_preset=launch_preset,
                workerbee_gateway_binding=workerbee_gateway_binding,
            ),
            width=self.detached_tmux_width,
            height=self.detached_tmux_height,
            **runtime_kwargs,
        )
        self.tmux_agent_targets[agent_id] = pane_id
        self.tmux_manual_override_agent_ids.add(agent_id)
        self.tmux_detached_agent_ids.discard(agent_id)
        self.tmux_direct_agent_modes[agent_id] = True
        agent = await self.register_operator_root(
            agent_id,
            cwd=cwd,
            codex_command=codex_command,
            mcp_url=mcp_url,
            session_name=runtime_session_name,
            tmux_pane_id=pane_id,
            default_source_caller_agent_id=source_caller_agent_id,
            default_source_caller_project=(
                str(source_caller.get("project") or "")
                if isinstance(source_caller, dict)
                else None
            ),
            default_source_codex_session_id=str(
                source_metadata.get("codex_session_id") or ""
            ),
            model_preset=launch_preset,
            workerbee_gateway_binding=workerbee_gateway_binding,
        )
        await self.register_launched_tmux_runtime(
            agent_id,
            pane_id,
            runtime_kwargs=runtime_kwargs,
            mapping_source="operator_root_launch",
        )
        await self.mark_operator_authority_activated(agent_id)
        await asyncio.sleep(1.0)
        sent = await self.send_text_to_tmux_pane(
            pane_id,
            self.operator_bootstrap_prompt(agent_id, cwd),
        )
        if not sent:
            self.notify(f"Started {agent_id}, but bootstrap paste failed.", severity="warning")
        return agent, pane_id, True

    async def record_operator_fork(
        self,
        *,
        logical_operator_id: str,
        source_caller_agent_id: str,
        fork_agent_id: str,
        tmux_pane_id: str,
        metadata: dict[str, Any],
        fork_track_id: str | None = None,
        fork_purpose: str | None = None,
        access_mode: str | None = None,
        source_cwd: str | None = None,
        work_root: str | None = None,
        fork_codex_session_id: str | None = None,
        clear_fork_codex_session_id: bool = False,
    ) -> dict[str, Any]:
        response = await self.api_client().post(
            "/v1/operator/forks/ensure",
            json={
                "operator_agent_id": logical_operator_id,
                "source_caller_agent_id": source_caller_agent_id,
                "fork_agent_id": fork_agent_id,
                "fork_track_id": fork_track_id,
                "fork_purpose": fork_purpose,
                "access_mode": access_mode,
                "source_cwd": source_cwd,
                "work_root": work_root,
                "fork_codex_session_id": fork_codex_session_id,
                "clear_fork_codex_session_id": clear_fork_codex_session_id,
                "tmux_pane_id": tmux_pane_id,
                "status": "running",
                "summary": "Fork launched from Agent PBX TUI.",
                "metadata": metadata,
            },
            headers=auth_headers(self.token),
        )
        response.raise_for_status()
        fork = response.json()
        if isinstance(fork, dict):
            return fork
        raise RuntimeError("operator fork response was not an object")

    async def ensure_operator_fork_from_tui(
        self,
        *,
        logical_operator_id: str,
        source_caller_agent_id: str,
        fork_track_id: str | None = None,
        fork_purpose: str | None = None,
        access_mode: str | None = None,
        work_root: str | None = None,
    ) -> dict[str, Any] | None:
        caller = self.agents.get(source_caller_agent_id)
        blocker = self.operator_fork_start_blocker(source_caller_agent_id)
        if blocker:
            self.notify(blocker, severity="error")
            return None
        if caller is None:
            return None
        caller_metadata = caller.get("metadata") if isinstance(caller.get("metadata"), dict) else {}
        source_session_id = str(caller_metadata.get("codex_session_id") or "").strip()
        caller_cwd = str(caller_metadata.get("cwd") or "").strip()
        caller_host_id = str(caller_metadata.get("codex_host_id") or "").strip()
        resolved_track_id = self.normalize_operator_fork_track_id(fork_track_id)
        resolved_purpose = self.normalize_operator_fork_label(
            fork_purpose,
            default=(
                DEFAULT_OPERATOR_FORK_PURPOSE
                if resolved_track_id == DEFAULT_OPERATOR_FORK_TRACK_ID
                else REVIEW_OPERATOR_FORK_PURPOSE
            ),
        )
        resolved_access_mode = self.normalize_operator_fork_label(
            access_mode,
            default=(
                DEFAULT_OPERATOR_FORK_ACCESS_MODE
                if resolved_purpose == DEFAULT_OPERATOR_FORK_PURPOSE
                else REVIEW_OPERATOR_FORK_ACCESS_MODE
            ),
        )
        launch_cwd = str(work_root or caller_cwd).strip()
        try:
            panes = await asyncio.to_thread(tmux_support.list_panes)
        except Exception:
            panes = []
        self.tmux_panes = panes
        existing_response = await self.api_client().get(
            "/v1/operator/forks",
            params={
                "operator_agent_id": logical_operator_id,
                "source_caller_agent_id": source_caller_agent_id,
                "limit": 100,
            },
            headers=auth_headers(self.token),
        )
        existing_response.raise_for_status()
        existing_payload = existing_response.json()
        existing_forks = (
            existing_payload.get("forks", [])
            if isinstance(existing_payload, dict)
            else []
        )
        source_continuation_previously_disabled = (
            resolved_purpose == REVIEW_OPERATOR_FORK_PURPOSE
            and self.review_source_continuation_previously_disabled(
                existing_forks,
                logical_operator_id=logical_operator_id,
                source_caller_agent_id=source_caller_agent_id,
                source_codex_session_id=source_session_id,
            )
        )
        stale_rebind_candidates: list[dict[str, Any]] = []
        for fork in existing_forks:
            if not isinstance(fork, dict):
                continue
            fork_metadata = (
                fork.get("metadata") if isinstance(fork.get("metadata"), dict) else {}
            )
            fork_track = str(
                fork.get("fork_track_id")
                or fork_metadata.get("fork_track_id")
                or DEFAULT_OPERATOR_FORK_TRACK_ID
            ).strip()
            if fork_track != resolved_track_id:
                continue
            fork_source_session_id = str(
                fork.get("source_codex_session_id")
                or fork_metadata.get("source_codex_session_id")
                or ""
            ).strip()
            if fork_source_session_id != source_session_id:
                stale_source_cwd = str(
                    fork.get("source_cwd") or fork_metadata.get("source_cwd") or ""
                ).strip()
                stale_work_root = str(
                    fork.get("work_root") or fork_metadata.get("work_root") or ""
                ).strip()
                stale_host_id = str(
                    fork.get("codex_host_id") or fork_metadata.get("codex_host_id") or ""
                ).strip()
                if (
                    fork_source_session_id
                    and stale_source_cwd == caller_cwd
                    and (not stale_work_root or stale_work_root == launch_cwd)
                    and (not stale_host_id or not caller_host_id or stale_host_id == caller_host_id)
                    and str(fork.get("status") or "").lower()
                    in {"starting", "running", "ready"}
                ):
                    stale_rebind_candidates.append(fork)
                continue
            if str(fork.get("status") or "").lower() in {"starting", "running", "ready"}:
                fork_agent_id = str(fork.get("fork_agent_id") or "")
                tmux_pane_id = str(fork.get("tmux_pane_id") or "").strip()
                if not fork_agent_id:
                    continue
                fork_agent = self.operator_fork_record_agent(fork)
                self.agents[fork_agent_id] = fork_agent
                pane = None
                runtime_mapping = await self.fetch_tmux_runtime_mapping(fork_agent_id)
                if (
                    isinstance(runtime_mapping, dict)
                    and str(runtime_mapping.get("state") or "") == "ready"
                ):
                    runtime_pane_id = str(runtime_mapping.get("pane_id") or "").strip()
                    runtime_kwargs = self.runtime_tmux_command_kwargs(fork_agent_id)
                    try:
                        runtime_panes = await asyncio.to_thread(
                            tmux_support.list_panes,
                            **runtime_kwargs,
                        )
                    except Exception:
                        runtime_panes = []
                    pane = next(
                        (
                            item
                            for item in runtime_panes
                            if item.pane_id == runtime_pane_id
                        ),
                        None,
                    )
                if pane is None:
                    pane = self.validated_operator_fork_pane(
                        fork_agent_id,
                        panes,
                        tmux_pane_id=tmux_pane_id,
                    )
                if pane is None:
                    pane = self.validated_operator_fork_pane(fork_agent_id, panes)
                if pane is None:
                    self.clear_saved_tmux_target(fork_agent_id)
                    continue
                if pane.pane_id != tmux_pane_id:
                    metadata = fork_metadata
                    repaired = await self.record_operator_fork(
                        logical_operator_id=logical_operator_id,
                        source_caller_agent_id=source_caller_agent_id,
                        fork_agent_id=fork_agent_id,
                        tmux_pane_id=pane.pane_id,
                        fork_track_id=resolved_track_id,
                        fork_purpose=resolved_purpose,
                        access_mode=resolved_access_mode,
                        source_cwd=caller_cwd,
                        work_root=launch_cwd,
                        metadata={
                            **metadata,
                            "agent_type": OPERATOR_AGENT_TYPE,
                            "operator_role": OPERATOR_ROLE_FORK,
                            "logical_operator_id": logical_operator_id,
                            "source_caller_agent_id": source_caller_agent_id,
                            "source_codex_session_id": source_session_id,
                            "fork_track_id": resolved_track_id,
                            "fork_purpose": resolved_purpose,
                            "access_mode": resolved_access_mode,
                            "source_cwd": caller_cwd,
                            "work_root": launch_cwd,
                            "cwd": launch_cwd,
                            "tmux_pane_id": pane.pane_id,
                            "operator_fork_pending": False,
                        },
                    )
                    if isinstance(repaired, dict):
                        fork = repaired
                self.tmux_agent_targets[fork_agent_id] = pane.pane_id
                self.tmux_direct_agent_modes[fork_agent_id] = True
                local_agent = self.agents.get(fork_agent_id)
                if local_agent is not None:
                    metadata = (
                        local_agent.get("metadata")
                        if isinstance(local_agent.get("metadata"), dict)
                        else {}
                    )
                    local_agent["metadata"] = {
                        **metadata,
                        "agent_type": OPERATOR_AGENT_TYPE,
                        "operator_role": OPERATOR_ROLE_FORK,
                        "logical_operator_id": logical_operator_id,
                        "source_caller_agent_id": source_caller_agent_id,
                        "source_codex_session_id": source_session_id,
                        "fork_track_id": resolved_track_id,
                        "fork_purpose": resolved_purpose,
                        "access_mode": resolved_access_mode,
                        "source_cwd": caller_cwd,
                        "work_root": launch_cwd,
                        "cwd": launch_cwd,
                        "tmux_pane_id": pane.pane_id,
                    }
                return fork
        rebound_fork = await self.rebind_stale_operator_fork_from_tui(
            stale_rebind_candidates,
            logical_operator_id=logical_operator_id,
            source_caller_agent_id=source_caller_agent_id,
            source_codex_session_id=source_session_id,
            source_cwd=caller_cwd,
            codex_host_id=caller_host_id,
            fork_track_id=resolved_track_id,
            fork_purpose=resolved_purpose,
            access_mode=resolved_access_mode,
            work_root=launch_cwd,
            panes=panes,
        )
        if rebound_fork is not None:
            return rebound_fork

        codex_command = self.operator_codex_command()
        mcp_url = agent_pbx_mcp_url(self.server)
        session_name = self.operator_tmux_session_name()
        await self.configure_operator_codex_mcp(
            codex_command=codex_command,
            mcp_url=mcp_url,
        )
        fork_agent_id = self.operator_fork_agent_id(
            logical_operator_id,
            source_caller_agent_id,
            source_session_id,
            fork_track_id=resolved_track_id,
        )
        launch_preset = self.codex_model_policy.profile_for_role(
            "review_fork"
            if resolved_purpose == REVIEW_OPERATOR_FORK_PURPOSE
            else "edit_fork"
        )
        fork_metadata = {
            "agent_type": OPERATOR_AGENT_TYPE,
            "operator_role": OPERATOR_ROLE_FORK,
            "reporting_agent_id": fork_agent_id,
            "logical_operator_id": logical_operator_id,
            "source_caller_agent_id": source_caller_agent_id,
            "source_codex_session_id": source_session_id,
            "fork_track_id": resolved_track_id,
            "fork_purpose": resolved_purpose,
            "access_mode": resolved_access_mode,
            "source_cwd": caller_cwd,
            "work_root": launch_cwd,
            "pbx_mode": PBX_REPORT_MODE,
            "cwd": launch_cwd,
            "launched_by": "agent-pbx-tui",
            "server_url": self.server,
            "mcp_url": mcp_url,
            "token_env": AGENT_PBX_TOKEN_ENV,
            "codex_command": codex_command,
            **launch_preset.metadata(),
            **self.mcp_tool_manifest_metadata(fork_agent_id),
        }
        logical_agent = self.agents.get(logical_operator_id)
        logical_metadata = self.agent_metadata(logical_agent)
        if resolved_purpose == DEFAULT_OPERATOR_FORK_PURPOSE:
            for key in (
                "operator_authority_profile",
                "operator_authority_profile_label",
                "operator_authority_workspace_roots",
                "operator_authority_git_admin_paths",
                "operator_authority_git_common_dirs",
                "operator_workspace_set_id",
                "operator_workspace_set_version",
                "operator_workspace_set_digest",
                "workerbee_access_profile_ceiling",
                "workerbee_workspace_policy_digest",
            ):
                if key in logical_metadata:
                    fork_metadata[key] = logical_metadata[key]
        review_mcp_approval_servers: tuple[str, ...] = ()
        if resolved_purpose == REVIEW_OPERATOR_FORK_PURPOSE:
            review_mcp_approval_servers = review_operator_mcp_approval_server_names()
            fork_metadata["review_mcp_approval_servers"] = list(
                review_mcp_approval_servers
            )
        review_launch_mode = (
            self.review_operator_fork_launch_mode()
            if resolved_purpose == REVIEW_OPERATOR_FORK_PURPOSE
            else REVIEW_OPERATOR_FORK_LAUNCH_MODE_CODEX_FORK
        )
        if resolved_purpose == REVIEW_OPERATOR_FORK_PURPOSE:
            fork_metadata["review_launch_mode"] = review_launch_mode
        if (
            resolved_purpose == REVIEW_OPERATOR_FORK_PURPOSE
            and review_launch_mode == REVIEW_OPERATOR_FORK_LAUNCH_MODE_CODEX_FORK
            and source_continuation_previously_disabled
        ):
            review_launch_mode = REVIEW_OPERATOR_FORK_LAUNCH_MODE_FRESH_CONTEXT
            fork_metadata["review_launch_mode"] = review_launch_mode
            fork_metadata["source_continuation_disabled_reason"] = (
                "invalid_encrypted_content"
            )
            self.notify(
                "Source continuation previously failed encrypted-content verification; "
                "starting review fork with fresh context.",
                severity="warning",
            )
        try:
            git_admin_plan = await self.linked_edit_fork_git_admin_plan(
                launch_cwd,
                fork_purpose=resolved_purpose,
                access_mode=resolved_access_mode,
            )
        except LinkedWorktreeQualificationError as exc:
            self.notify(
                f"Refused to launch {fork_agent_id}: linked-worktree Git "
                f"administration did not qualify. {exc}",
                severity="error",
            )
            return None
        if git_admin_plan is not None:
            fork_metadata["linked_git_admin"] = git_admin_plan.public_dict()
        workerbee_profile = (
            WORKERBEE_PROFILE_REVIEW
            if resolved_purpose == REVIEW_OPERATOR_FORK_PURPOSE
            else (
                self.workerbee_profile_for_agent(logical_agent)
                if isinstance(logical_agent, dict)
                else WORKERBEE_PROFILE_LOCAL_DEPLOY
            )
        )
        workerbee_profile, workerbee_gateway_binding = (
            await self.prepare_operator_fork_workerbee_launch(
                fork_agent_id=fork_agent_id,
                logical_operator_id=logical_operator_id,
                source_session_id=source_session_id,
                source_root=launch_cwd,
                fork_metadata=fork_metadata,
                profile=workerbee_profile,
            )
        )
        launch_config_overrides = (
            review_operator_config_overrides(
                review_mcp_approval_servers,
                mcp_url=mcp_url,
                codex_home=self.codex_home_dir(),
                work_root=launch_cwd,
                terminal_mode=self.codex_terminal_mode,
                workerbee_gateway_binding=workerbee_gateway_binding,
            )
            if resolved_purpose == REVIEW_OPERATOR_FORK_PURPOSE
            else operator_agent_config_overrides(
                mcp_url=mcp_url,
                codex_home=self.codex_home_dir(),
                work_root=launch_cwd,
                terminal_mode=self.codex_terminal_mode,
                workerbee_gateway_binding=workerbee_gateway_binding,
                authority_metadata=fork_metadata,
                linked_git_admin_plan=git_admin_plan,
            )
        )
        launch_config_overrides = [
            *launch_config_overrides,
            *codex_model_preset_config_overrides(launch_preset),
            *self.linked_edit_fork_config_overrides(git_admin_plan, fork_metadata),
        ]
        sandbox = operator_authority_sandbox(fork_metadata)

        def build_bootstrap(mode: str) -> str:
            return self.operator_bootstrap_prompt(
                fork_agent_id,
                launch_cwd,
                logical_operator_id=logical_operator_id,
                source_caller_agent_id=source_caller_agent_id,
                source_codex_session_id=source_session_id,
                fork_track_id=resolved_track_id,
                fork_purpose=resolved_purpose,
                access_mode=resolved_access_mode,
                source_cwd=caller_cwd,
                work_root=launch_cwd,
                review_launch_mode=mode,
            )

        def build_command(mode: str) -> str:
            bootstrap_prompt = build_bootstrap(mode)
            if (
                resolved_purpose == REVIEW_OPERATOR_FORK_PURPOSE
                and mode == REVIEW_OPERATOR_FORK_LAUNCH_MODE_FRESH_CONTEXT
            ):
                return self.codex_start_command(
                    codex_command,
                    bootstrap_prompt,
                    cd=launch_cwd if launch_cwd and launch_cwd != caller_cwd else None,
                    sandbox=sandbox,
                    config_overrides=launch_config_overrides,
                )
            return self.operator_fork_command(
                codex_command,
                source_session_id,
                bootstrap_prompt,
                cd=launch_cwd if launch_cwd and launch_cwd != caller_cwd else None,
                sandbox=sandbox,
                config_overrides=launch_config_overrides,
            )

        def build_env(mode: str) -> dict[str, str]:
            return self.operator_launch_env(
                agent_id=fork_agent_id,
                cwd=launch_cwd,
                mcp_url=mcp_url,
                operator_role=OPERATOR_ROLE_FORK,
                logical_operator_id=logical_operator_id,
                source_caller_agent_id=source_caller_agent_id,
                source_codex_session_id=source_session_id,
                fork_track_id=resolved_track_id,
                fork_purpose=resolved_purpose,
                access_mode=resolved_access_mode,
                source_cwd=caller_cwd,
                work_root=launch_cwd,
                review_launch_mode=mode,
                model_preset=launch_preset,
                workerbee_profile=workerbee_profile,
                workerbee_gateway_binding=workerbee_gateway_binding,
            )

        runtime_session_name, runtime_kwargs = await self.configured_runtime_launch_target(
            fork_agent_id,
            fallback_session_name=session_name,
        )
        fork_metadata["tmux_session"] = runtime_session_name
        pane_id = await self.launch_restart_pane(
            session_name=runtime_session_name,
            window_name=fork_agent_id,
            command=build_command(review_launch_mode),
            label=fork_agent_id,
            cwd=launch_cwd,
            env=build_env(review_launch_mode),
            **runtime_kwargs,
        )
        if (
            resolved_purpose == REVIEW_OPERATOR_FORK_PURPOSE
            and review_launch_mode == REVIEW_OPERATOR_FORK_LAUNCH_MODE_CODEX_FORK
            and await self.review_fork_pane_has_invalid_encrypted_content(
                pane_id,
                **runtime_kwargs,
            )
        ):
            self.notify(
                "Codex fork continuation failed encrypted-content verification; "
                "restarting review fork with fresh context.",
                severity="warning",
            )
            await self.quit_or_kill_tmux_pane(
                pane_id,
                label=fork_agent_id,
                **runtime_kwargs,
            )
            review_launch_mode = REVIEW_OPERATOR_FORK_LAUNCH_MODE_FRESH_CONTEXT
            fork_metadata["review_launch_mode"] = review_launch_mode
            fork_metadata["source_continuation_disabled_reason"] = (
                "invalid_encrypted_content"
            )
            pane_id = await self.launch_restart_pane(
                session_name=runtime_session_name,
                window_name=fork_agent_id,
                command=build_command(review_launch_mode),
                label=fork_agent_id,
                cwd=launch_cwd,
                env=build_env(review_launch_mode),
                **runtime_kwargs,
            )
        self.tmux_agent_targets[fork_agent_id] = pane_id
        self.tmux_manual_override_agent_ids.add(fork_agent_id)
        self.tmux_detached_agent_ids.discard(fork_agent_id)
        self.tmux_direct_agent_modes[fork_agent_id] = True
        fork_metadata["tmux_pane_id"] = pane_id
        fork = await self.record_operator_fork(
            logical_operator_id=logical_operator_id,
            source_caller_agent_id=source_caller_agent_id,
            fork_agent_id=fork_agent_id,
            tmux_pane_id=pane_id,
            metadata=fork_metadata,
            fork_track_id=resolved_track_id,
            fork_purpose=resolved_purpose,
            access_mode=resolved_access_mode,
            source_cwd=caller_cwd,
            work_root=launch_cwd,
        )
        if isinstance(fork, dict):
            self.agents[fork_agent_id] = self.operator_fork_record_agent(fork)
        inherited_profile = str(
            fork_metadata.get("operator_authority_profile") or ""
        ).strip()
        if inherited_profile:
            authority_response = await self.api_client().put(
                f"/v2/agents/{fork_agent_id}/operator-authority",
                json={
                    "profile": inherited_profile,
                    "workspace_set_id": fork_metadata.get(
                        "operator_workspace_set_id"
                    ),
                    "profile_label": fork_metadata.get(
                        "operator_authority_profile_label"
                    ),
                },
                headers=auth_headers(self.token),
            )
            authority_response.raise_for_status()
            await self.mark_operator_authority_activated(fork_agent_id)
        await self.register_launched_tmux_runtime(
            fork_agent_id,
            pane_id,
            runtime_kwargs=runtime_kwargs,
            mapping_source="operator_fork_launch",
        )
        self.notify(
            f"Started {resolved_purpose} fork {fork_agent_id} for {source_caller_agent_id}."
        )
        return fork

    async def rebind_stale_operator_fork_from_tui(
        self,
        candidates: list[dict[str, Any]],
        *,
        logical_operator_id: str,
        source_caller_agent_id: str,
        source_codex_session_id: str,
        source_cwd: str,
        codex_host_id: str,
        fork_track_id: str,
        fork_purpose: str,
        access_mode: str,
        work_root: str,
        panes: list[tmux_support.TmuxPane],
    ) -> dict[str, Any] | None:
        live_candidates: list[tuple[dict[str, Any], tmux_support.TmuxPane]] = []
        for fork in candidates:
            fork_agent_id = str(fork.get("fork_agent_id") or "").strip()
            tmux_pane_id = str(fork.get("tmux_pane_id") or "").strip()
            if not fork_agent_id:
                continue
            pane = self.validated_operator_fork_pane(
                fork_agent_id,
                panes,
                tmux_pane_id=tmux_pane_id,
            )
            if pane is None:
                pane = self.validated_operator_fork_pane(fork_agent_id, panes)
            if pane is not None:
                live_candidates.append((fork, pane))
        if not live_candidates:
            return None
        if len(live_candidates) > 1:
            raise RuntimeError(
                f"multiple stale {fork_track_id} forks have live panes; "
                "select one before rebinding"
            )

        fork, pane = live_candidates[0]
        fork_agent_id = str(fork.get("fork_agent_id") or "").strip()
        old_source_session_id = str(fork.get("source_codex_session_id") or "").strip()
        operator_fork_id = str(fork.get("operator_fork_id") or "").strip()
        if not old_source_session_id or not operator_fork_id:
            return None
        try:
            response = await self.api_client().post(
                "/v1/operator/forks/rebind-source-session",
                json={
                    "operator_agent_id": logical_operator_id,
                    "operator_fork_id": operator_fork_id,
                    "source_caller_agent_id": source_caller_agent_id,
                    "old_source_codex_session_id": old_source_session_id,
                    "new_source_codex_session_id": source_codex_session_id,
                    "source_cwd": source_cwd,
                    "codex_host_id": codex_host_id or None,
                    "reason": "TUI matched stale live fork for restarted source caller.",
                    "metadata": {
                        "agent_type": OPERATOR_AGENT_TYPE,
                        "operator_role": OPERATOR_ROLE_FORK,
                        "logical_operator_id": logical_operator_id,
                        "source_caller_agent_id": source_caller_agent_id,
                        "source_codex_session_id": source_codex_session_id,
                        "fork_track_id": fork_track_id,
                        "fork_purpose": fork_purpose,
                        "access_mode": access_mode,
                        "source_cwd": source_cwd,
                        "work_root": work_root,
                        "cwd": work_root,
                        "tmux_pane_id": pane.pane_id,
                        "operator_fork_pending": False,
                    },
                },
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            payload = response.json()
        except Exception as exc:
            raise RuntimeError(f"unable to rebind stale operator fork: {exc}") from exc
        if not isinstance(payload, dict):
            return None
        rebound_metadata = (
            payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
        )
        rebound_metadata = {
            **rebound_metadata,
            "agent_type": OPERATOR_AGENT_TYPE,
            "operator_role": OPERATOR_ROLE_FORK,
            "logical_operator_id": logical_operator_id,
            "source_caller_agent_id": source_caller_agent_id,
            "source_codex_session_id": source_codex_session_id,
            "fork_track_id": fork_track_id,
            "fork_purpose": fork_purpose,
            "access_mode": access_mode,
            "source_cwd": source_cwd,
            "work_root": work_root,
            "cwd": work_root,
            "tmux_pane_id": pane.pane_id,
        }
        payload["metadata"] = rebound_metadata
        payload["source_codex_session_id"] = source_codex_session_id
        payload["tmux_pane_id"] = pane.pane_id
        self.agents[fork_agent_id] = self.operator_fork_record_agent(payload)
        local_agent = self.agents.get(fork_agent_id)
        if local_agent is not None:
            local_agent["metadata"] = rebound_metadata
        self.tmux_agent_targets[fork_agent_id] = pane.pane_id
        self.tmux_direct_agent_modes[fork_agent_id] = True
        self.notify(
            f"Rebound {fork_track_id} fork {fork_agent_id} to current source session."
        )
        return payload

    async def fetch_pending_project_spawn_requests(
        self,
        logical_operator_id: str,
    ) -> list[dict[str, Any]]:
        response = await self.api_client().get(
            "/v1/operator/project-spawns",
            params={
                "operator_agent_id": logical_operator_id,
                "status": "pending",
                "limit": 20,
            },
            headers=auth_headers(self.token),
        )
        response.raise_for_status()
        payload = response.json()
        if not isinstance(payload, dict):
            return []
        requests = payload.get("project_spawns")
        if not isinstance(requests, list):
            return []
        return [item for item in requests if isinstance(item, dict)]

    async def inspect_pending_project_spawn_request(self) -> None:
        operator_agent_id = self.selected_operator_agent_id()
        if not operator_agent_id:
            self.notify("Select an operator first.", severity="warning")
            return
        operator = self.agents.get(operator_agent_id)
        if operator is None:
            self.notify("Select a known operator first.", severity="warning")
            return
        logical_operator_id = self.logical_operator_id_for_agent(operator)
        try:
            pending = await self.fetch_pending_project_spawn_requests(
                logical_operator_id
            )
        except Exception as exc:
            self.notify(f"Unable to inspect project spawn requests: {exc}", severity="error")
            return
        if not pending:
            self.notify(f"No pending project spawn requests for {logical_operator_id}.")
            return
        request = pending[0]
        detail = self.query_one_or_none("#detail", TextArea)
        if detail is not None:
            detail.text = (
                "Pending project spawn\n\n"
                f"Request: {request.get('spawn_request_id') or '-'}\n"
                f"Project: {request.get('project_name') or '-'}\n"
                f"Mode: {request.get('mode') or '-'}\n"
                f"Source: {request.get('source_cwd') or '-'}\n"
                f"Target: {request.get('target_path') or '-'}\n"
                f"Review fork: {request.get('review_fork_agent_id') or '-'}\n\n"
                f"{request.get('instructions') or ''}"
            )
        self.notify(
            f"Inspected project spawn {request.get('spawn_request_id') or '-'}; "
            "use /operator project spawn cancel to cancel it."
        )

