    async def start_operator_kb_seed_run(
        self,
        operator_agent_id: str,
        *,
        seed_type: str = "operator_self_seed",
        scope: str = "project",
        project: str | None = None,
        repo_root: str | None = None,
        git_remote: str | None = None,
        branch: str | None = None,
        delivery: str = "auto",
        metadata: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        response = await self.api_client().post(
            "/v1/operator/kb/seed-runs",
            json={
                "operator_agent_id": operator_agent_id,
                "seed_type": seed_type,
                "scope": scope,
                "project": project,
                "repo_root": repo_root,
                "git_remote": git_remote,
                "branch": branch,
                "delivery": delivery,
                "metadata": metadata or {},
            },
            headers=auth_headers(self.token),
        )
        response.raise_for_status()
        payload = response.json()
        if isinstance(payload, dict):
            return payload
        raise RuntimeError("KB seed response was not an object")

    async def compile_operator_kb_report(
        self,
        operator_agent_id: str,
        report_id: str,
    ) -> dict[str, Any]:
        response = await self.api_client().post(
            "/v1/operator/kb/compile-report",
            json={
                "operator_agent_id": operator_agent_id,
                "report_id": report_id,
            },
            headers=auth_headers(self.token),
        )
        response.raise_for_status()
        payload = response.json()
        if isinstance(payload, dict):
            return payload
        raise RuntimeError("KB compile response was not an object")

    async def rebuild_operator_kb_index(self) -> dict[str, Any]:
        created = await self.api_client().post(
            "/v1/operator/kb/index-jobs",
            json={
                "operation": "rebuild",
                "metadata": {"requested_by": "agent-pbx-tui"},
            },
            headers=auth_headers(self.token),
        )
        created.raise_for_status()
        run = await self.api_client().post(
            "/v1/operator/kb/index-jobs/run",
            params={"limit": 1000},
            headers=auth_headers(self.token),
        )
        run.raise_for_status()
        payload = run.json()
        if isinstance(payload, dict):
            return payload
        raise RuntimeError("KB index response was not an object")

    def operator_kb_seed_context(
        self,
        operator_agent_id: str,
        operator_agent: dict[str, Any],
    ) -> dict[str, Any]:
        metadata = self.agent_metadata(operator_agent)
        source_caller_agent_id = str(
            metadata.get("source_caller_agent_id")
            or metadata.get("default_source_caller_agent_id")
            or ""
        ).strip()
        source_agent = (
            self.agents.get(source_caller_agent_id) if source_caller_agent_id else None
        )
        source_metadata = self.agent_metadata(source_agent)
        project = (
            str(source_agent.get("project") or "").strip()
            if isinstance(source_agent, dict)
            else ""
        ) or str(operator_agent.get("project") or "").strip()
        repo_root = (
            str(metadata.get("source_cwd") or "").strip()
            or str(source_metadata.get("cwd") or "").strip()
            or str(metadata.get("cwd") or "").strip()
        )
        git_remote = (
            str(metadata.get("git_remote") or "").strip()
            or str(source_metadata.get("git_remote") or "").strip()
        )
        branch = (
            str(metadata.get("branch") or "").strip()
            or str(source_metadata.get("branch") or "").strip()
        )
        return {
            "scope": "repo" if repo_root else "project",
            "project": project or None,
            "repo_root": repo_root or None,
            "git_remote": git_remote or None,
            "branch": branch or None,
            "metadata": {
                "triggered_by": "agent-pbx-tui",
                "selected_operator_agent_id": operator_agent_id,
                "selected_logical_operator_id": self.logical_operator_id_for_agent(
                    operator_agent
                ),
                "source_caller_agent_id": source_caller_agent_id or None,
            },
        }

    def operator_kb_operator_id_for_agent(self, agent_id: str) -> str | None:
        agent = self.agents.get(agent_id)
        if agent is None or self.agent_type(agent) != OPERATOR_AGENT_TYPE:
            return None
        return self.logical_operator_id_for_agent(agent)

    def selected_operator_kb_agent_id(self) -> str | None:
        if (
            self.active_agent_tab == "operator-kb-tab"
            and self.selected_agent_id
            and self.is_operator_agent_id(self.selected_agent_id)
        ):
            return self.selected_agent_id
        return self.selected_operator_agent_id()

    async def show_selected_operator_kb(self, *, status: str = "active") -> None:
        operator_agent_id = self.selected_operator_kb_agent_id()
        if not operator_agent_id:
            return
        await self.open_operator_kb_for_agent(operator_agent_id, status=status)

    async def load_operator_kb(
        self,
        agent_id: str,
        *,
        status: str | None = None,
    ) -> None:
        status_label = self.query_one_or_none("#operator-kb-status", Static)
        detail = self.query_one_or_none("#operator-kb-detail", TextArea)
        logical_operator_id = self.operator_kb_operator_id_for_agent(agent_id)
        resolved_status = status or (
            self.operator_kb_status_filter_by_operator.get(agent_id) or "active"
        )
        if logical_operator_id is None:
            self.render_operator_kb("", [], status=resolved_status)
            if status_label is not None:
                status_label.update("KB: select an operator agent")
            if detail is not None:
                detail.text = "Operator KB entries are shown for operator agents only."
            return
        resolved_status = status or (
            self.operator_kb_status_filter_by_operator.get(logical_operator_id)
            or "active"
        )
        self.operator_kb_status_filter_by_operator[logical_operator_id] = resolved_status
        self.operator_kb_mode_by_operator[logical_operator_id] = "entries"
        if status_label is not None:
            status_label.update(
                f"KB: loading {resolved_status} entries for "
                f"{logical_operator_id}..."
            )
        try:
            entries = await self.fetch_operator_kb_entries(
                logical_operator_id,
                status=resolved_status,
                limit=100,
            )
        except Exception as exc:
            self.render_operator_kb(logical_operator_id, [], status=resolved_status)
            if status_label is not None:
                status_label.update(f"KB: unable to load ({exc})")
            if detail is not None:
                detail.text = f"Unable to load operator KB for {logical_operator_id}: {exc}"
            return
        entries = self.order_operator_kb_entries(entries, status=resolved_status)
        self.operator_kb_entries_by_operator[logical_operator_id] = {
            str(entry.get("kb_id") or "").strip(): entry
            for entry in entries
            if str(entry.get("kb_id") or "").strip()
        }
        self.render_operator_kb(logical_operator_id, entries, status=resolved_status)
        if status_label is not None:
            status_label.update(
                f"KB: {len(entries)} {resolved_status} entr"
                f"{'y' if len(entries) == 1 else 'ies'} for {logical_operator_id}"
            )
        selected = self.selected_operator_kb_id_by_operator.get(logical_operator_id)
        if selected not in self.operator_kb_entries_by_operator.get(
            logical_operator_id,
            {},
        ):
            entry = self.primary_operator_kb_entry(entries, status=resolved_status)
            selected = str(entry.get("kb_id") or "") if entry else ""
        if selected:
            self.select_operator_kb_entry(
                selected,
                logical_operator_id=logical_operator_id,
            )
        elif detail is not None:
            detail.text = (
                f"No {resolved_status} operator KB entries for "
                f"{logical_operator_id}."
            )

    async def search_operator_kb(self) -> None:
        operator_agent_id = self.selected_operator_kb_agent_id()
        if not operator_agent_id:
            self.notify("Select an operator before searching KB.", severity="warning")
            return
        logical_operator_id = self.operator_kb_operator_id_for_agent(operator_agent_id)
        if not logical_operator_id:
            self.notify("KB search is available for operator agents only.", severity="warning")
            return
        query_input = self.query_one_or_none("#operator-kb-query", Input)
        query = str(query_input.value if query_input is not None else "").strip()
        if not query:
            self.notify("Enter a KB query before searching.", severity="warning")
            return
        status_label = self.query_one_or_none("#operator-kb-status", Static)
        detail = self.query_one_or_none("#operator-kb-detail", TextArea)
        self.operator_kb_search_query_by_operator[logical_operator_id] = query
        self.operator_kb_mode_by_operator[logical_operator_id] = "search"
        if status_label is not None:
            status_label.update(f"KB: searching for {query!r}...")
        try:
            entries = await self.fetch_operator_kb_entries(
                logical_operator_id,
                status="active",
                query=query,
                semantic=True,
                limit=50,
            )
        except Exception as exc:
            self.render_operator_kb(logical_operator_id, [], status="search")
            if status_label is not None:
                status_label.update(f"KB: search failed ({exc})")
            if detail is not None:
                detail.text = f"Unable to search operator KB for {logical_operator_id}: {exc}"
            return
        self.operator_kb_entries_by_operator[logical_operator_id] = {
            str(entry.get("kb_id") or "").strip(): entry
            for entry in entries
            if str(entry.get("kb_id") or "").strip()
        }
        self.render_operator_kb(logical_operator_id, entries, status="search")
        if status_label is not None:
            status_label.update(
                f"KB: {len(entries)} search result"
                f"{'' if len(entries) == 1 else 's'} for {logical_operator_id}"
            )
        if entries:
            self.select_operator_kb_entry(
                str(entries[0].get("kb_id") or ""),
                logical_operator_id=logical_operator_id,
            )
        elif detail is not None:
            detail.text = f"No KB matches for {query!r}."

    async def load_operator_kb_queries_for_selected(self, *, misses: bool = False) -> None:
        operator_agent_id = self.selected_operator_kb_agent_id()
        if not operator_agent_id:
            self.notify("Select an operator before loading KB history.", severity="warning")
            return
        await self.load_operator_kb_queries(operator_agent_id, misses=misses)

    async def load_operator_kb_queries(
        self,
        agent_id: str,
        *,
        misses: bool = False,
    ) -> None:
        status_label = self.query_one_or_none("#operator-kb-status", Static)
        detail = self.query_one_or_none("#operator-kb-detail", TextArea)
        logical_operator_id = self.operator_kb_operator_id_for_agent(agent_id)
        if logical_operator_id is None:
            self.render_operator_kb_queries("", [], misses=misses)
            if status_label is not None:
                status_label.update("KB: select an operator agent")
            if detail is not None:
                detail.text = "KB query history is shown for operator agents only."
            return
        mode = "misses" if misses else "history"
        self.operator_kb_mode_by_operator[logical_operator_id] = mode
        if status_label is not None:
            status_label.update(f"KB: loading {mode} for {logical_operator_id}...")
        try:
            queries = await self.fetch_operator_kb_queries(
                logical_operator_id,
                misses=misses,
                limit=100,
            )
        except Exception as exc:
            self.render_operator_kb_queries(logical_operator_id, [], misses=misses)
            if status_label is not None:
                status_label.update(f"KB: unable to load {mode} ({exc})")
            if detail is not None:
                detail.text = f"Unable to load KB {mode} for {logical_operator_id}: {exc}"
            return
        self.operator_kb_queries_by_operator[logical_operator_id] = {
            str(query.get("query_id") or "").strip(): query
            for query in queries
            if str(query.get("query_id") or "").strip()
        }
        self.render_operator_kb_queries(logical_operator_id, queries, misses=misses)
        if status_label is not None:
            status_label.update(
                f"KB: {len(queries)} {mode} quer"
                f"{'y' if len(queries) == 1 else 'ies'} for {logical_operator_id}"
            )
        selected = self.selected_operator_kb_query_id_by_operator.get(logical_operator_id)
        if selected not in self.operator_kb_queries_by_operator.get(
            logical_operator_id,
            {},
        ):
            selected = str(queries[0].get("query_id") or "") if queries else ""
        if selected:
            self.select_operator_kb_query(
                selected,
                logical_operator_id=logical_operator_id,
            )
        elif detail is not None:
            detail.text = f"No KB {mode} queries for {logical_operator_id}."

    @staticmethod
    def order_operator_kb_entries(
        entries: list[dict[str, Any]],
        *,
        status: str,
    ) -> list[dict[str, Any]]:
        if status == "proposed":
            return sorted(
                entries,
                key=lambda item: (
                    float_value(item.get("created_at")) or 0.0,
                    str(item.get("kb_id") or ""),
                ),
            )
        return sorted(
            entries,
            key=lambda item: (
                float_value(item.get("updated_at")) or 0.0,
                str(item.get("kb_id") or ""),
            ),
            reverse=True,
        )

    def render_operator_kb(
        self,
        logical_operator_id: str,
        entries: list[dict[str, Any]],
        *,
        status: str,
    ) -> None:
        table = self.query_one_or_none("#operator-kb", DataTable)
        if table is None:
            return
        position = self.data_table_position(table)
        table.clear(columns=True)
        if status == "search":
            table.add_columns("Mode", "Score", "Feedback", "Project", "Title", "Tags", "Updated")
        else:
            table.add_columns("Status", "Redact", "Scope", "Project", "Title", "Tags", "Updated")
        for entry in entries:
            kb_id = str(entry.get("kb_id") or "").strip()
            if not kb_id:
                continue
            retrieval = self.operator_kb_entry_retrieval(entry)
            tags = entry.get("tags") if isinstance(entry.get("tags"), list) else []
            tag_text = ", ".join(str(tag) for tag in tags[:3]) or "-"
            if len(tags) > 3:
                tag_text = f"{tag_text}, +{len(tags) - 3}"
            updated_at = float_value(entry.get("updated_at"))
            updated_text = (
                self.format_short_time(updated_at)
                if updated_at is not None
                else "-"
            )
            if status == "search":
                score = float_value(retrieval.get("score"))
                score_text = f"{score:.3f}" if score is not None else "-"
                feedback = str(retrieval.get("feedback") or "-")
                table.add_row(
                    str(retrieval.get("mode") or "-"),
                    score_text,
                    feedback,
                    str(entry.get("project") or "-"),
                    str(entry.get("title") or kb_id),
                    tag_text,
                    updated_text,
                    key=kb_id,
                )
            else:
                table.add_row(
                    str(entry.get("status") or status or "-"),
                    str(entry.get("redaction_status") or "-"),
                    str(entry.get("scope") or "-"),
                    str(entry.get("project") or "-"),
                    str(entry.get("title") or kb_id),
                    tag_text,
                    updated_text,
                    key=kb_id,
                )
        selected = self.selected_operator_kb_id_by_operator.get(logical_operator_id)
        if selected and selected in self.operator_kb_entries_by_operator.get(
            logical_operator_id,
            {},
        ):
            try:
                table.move_cursor(
                    row=table.get_row_index(selected),
                    animate=False,
                    scroll=False,
                )
            except Exception:
                pass
        self.restore_data_table_position(table, position)

    def render_operator_kb_queries(
        self,
        logical_operator_id: str,
        queries: list[dict[str, Any]],
        *,
        misses: bool,
    ) -> None:
        table = self.query_one_or_none("#operator-kb", DataTable)
        if table is None:
            return
        position = self.data_table_position(table)
        table.clear(columns=True)
        table.add_columns("When", "Matches", "Feedback", "Mode", "Query", "Project", "Source")
        for query in queries:
            query_id = str(query.get("query_id") or "").strip()
            if not query_id:
                continue
            created_at = float_value(query.get("created_at"))
            created_text = (
                self.format_short_time(created_at)
                if created_at is not None
                else "-"
            )
            feedback_summary = (
                query.get("feedback_summary")
                if isinstance(query.get("feedback_summary"), dict)
                else {}
            )
            feedback_text = ", ".join(
                f"{key}:{value}"
                for key, value in sorted(feedback_summary.items())
                if value
            ) or "-"
            table.add_row(
                created_text,
                str(query.get("match_count") or 0),
                feedback_text,
                str(query.get("retrieval_mode") or "-"),
                str(query.get("query") or query_id),
                str(query.get("project") or "-"),
                str(query.get("source") or ("misses" if misses else "history")),
                key=f"query:{query_id}",
            )
        selected = self.selected_operator_kb_query_id_by_operator.get(logical_operator_id)
        if selected and selected in self.operator_kb_queries_by_operator.get(
            logical_operator_id,
            {},
        ):
            try:
                table.move_cursor(
                    row=table.get_row_index(f"query:{selected}"),
                    animate=False,
                    scroll=False,
                )
            except Exception:
                pass
        self.restore_data_table_position(table, position)

    def select_operator_kb_entry(
        self,
        kb_id: str,
        *,
        logical_operator_id: str | None = None,
    ) -> None:
        resolved_operator_id = logical_operator_id
        if resolved_operator_id is None and self.selected_agent_id:
            resolved_operator_id = self.operator_kb_operator_id_for_agent(
                self.selected_agent_id
            )
        if not resolved_operator_id:
            return
        entry = self.operator_kb_entries_by_operator.get(
            resolved_operator_id,
            {},
        ).get(kb_id)
        if entry is None:
            return
        self.selected_operator_kb_id_by_operator[resolved_operator_id] = kb_id
        self.selected_operator_kb_query_id_by_operator.pop(resolved_operator_id, None)
        table = self.query_one_or_none("#operator-kb", DataTable)
        if table is not None:
            try:
                table.move_cursor(
                    row=table.get_row_index(kb_id),
                    animate=False,
                    scroll=True,
                )
            except Exception:
                pass
        detail = self.query_one_or_none("#operator-kb-detail", TextArea)
        if detail is not None:
            detail.text = self.format_operator_kb_entry_detail(
                resolved_operator_id,
                entry,
            )

    def select_operator_kb_query(
        self,
        query_id: str,
        *,
        logical_operator_id: str | None = None,
    ) -> None:
        resolved_operator_id = logical_operator_id
        if resolved_operator_id is None and self.selected_agent_id:
            resolved_operator_id = self.operator_kb_operator_id_for_agent(
                self.selected_agent_id
            )
        if not resolved_operator_id:
            return
        query = self.operator_kb_queries_by_operator.get(
            resolved_operator_id,
            {},
        ).get(query_id)
        if query is None:
            return
        self.selected_operator_kb_query_id_by_operator[resolved_operator_id] = query_id
        self.selected_operator_kb_id_by_operator.pop(resolved_operator_id, None)
        table = self.query_one_or_none("#operator-kb", DataTable)
        if table is not None:
            try:
                table.move_cursor(
                    row=table.get_row_index(f"query:{query_id}"),
                    animate=False,
                    scroll=True,
                )
            except Exception:
                pass
        detail = self.query_one_or_none("#operator-kb-detail", TextArea)
        if detail is not None:
            detail.text = self.format_operator_kb_query_detail(
                resolved_operator_id,
                query,
            )

    def selected_operator_kb_entry_for_operator(
        self,
        logical_operator_id: str,
    ) -> dict[str, Any] | None:
        kb_id = self.selected_operator_kb_id_by_operator.get(logical_operator_id)
        if not kb_id:
            return None
        return self.operator_kb_entries_by_operator.get(
            logical_operator_id,
            {},
        ).get(kb_id)

    def selected_operator_kb_entry_for_action(
        self,
        logical_operator_id: str,
        *,
        status: str,
    ) -> dict[str, Any] | None:
        entry = self.selected_operator_kb_entry_for_operator(logical_operator_id)
        if (
            entry is not None
            and self.active_agent_tab == "operator-kb-tab"
            and str(entry.get("status") or "") == status
        ):
            return entry
        return None

    async def promote_oldest_operator_kb_proposal(self) -> None:
        operator_agent_id = self.selected_operator_kb_agent_id()
        if not operator_agent_id:
            return
        operator_agent = self.agents.get(operator_agent_id)
        if operator_agent is None:
            self.notify("Select a known operator first.", severity="warning")
            return
        logical_operator_id = self.logical_operator_id_for_agent(operator_agent)
        selected_entry = self.selected_operator_kb_entry_for_operator(logical_operator_id)
        if self.active_agent_tab == "operator-kb-tab" and selected_entry is not None:
            if str(selected_entry.get("status") or "") != "proposed":
                self.notify(
                    "Select a proposed KB entry before promoting.",
                    severity="warning",
                )
                return
            entry = selected_entry
        else:
            entry = None
        if entry is None:
            try:
                entries = await self.fetch_operator_kb_entries(
                    logical_operator_id,
                    status="proposed",
                    limit=100,
                )
            except Exception as exc:
                self.notify(f"Unable to fetch KB proposals: {exc}", severity="error")
                return
            clean_entries = [
                item
                for item in entries
                if str(item.get("redaction_status") or "") == "clean"
            ]
            if not clean_entries:
                if entries:
                    self.notify(
                        "KB proposals exist but need redaction review before promotion.",
                        severity="warning",
                    )
                else:
                    self.notify(f"No proposed KB entries for {logical_operator_id}.")
                return
            entry = self.primary_operator_kb_entry(clean_entries, status="proposed")
        elif str(entry.get("redaction_status") or "") != "clean":
            self.notify(
                "Selected KB proposal needs redaction review before promotion.",
                severity="warning",
            )
            return
        if entry is None:
            self.notify(f"No proposed KB entries for {logical_operator_id}.")
            return
        kb_id = str(entry.get("kb_id") or "").strip()
        if not kb_id:
            self.notify("KB proposal is missing an id.", severity="error")
            return
        try:
            promoted = await self.promote_operator_kb_entry(
                logical_operator_id,
                kb_id,
            )
        except Exception as exc:
            self.notify(f"Unable to promote KB entry: {exc}", severity="error")
            return
        promoted_id = str(promoted.get("kb_id") or kb_id)
        self.selected_operator_kb_id_by_operator[logical_operator_id] = promoted_id
        await self.load_operator_kb(operator_agent_id, status="active")
        self.notify(f"Promoted operator KB entry {kb_id}.")
        await self.refresh_events()

    async def show_selected_operator_kb_detail(self, *, status: str = "active") -> None:
        operator_agent_id = self.selected_operator_kb_agent_id()
        if not operator_agent_id:
            return
        operator_agent = self.agents.get(operator_agent_id)
        if operator_agent is None:
            self.notify("Select a known operator first.", severity="warning")
            return
        await self.open_operator_kb_for_agent(operator_agent_id, status=status)

    async def seed_selected_operator_kb(self) -> None:
        operator_agent_id = self.selected_operator_kb_agent_id()
        if not operator_agent_id:
            return
        operator_agent = self.agents.get(operator_agent_id)
        if not isinstance(operator_agent, dict):
            self.notify("Select a known operator first.", severity="warning")
            return
        if self.agent_type(operator_agent) != OPERATOR_AGENT_TYPE:
            self.notify("Select an operator before starting a KB seed run.", severity="warning")
            return
        context = self.operator_kb_seed_context(operator_agent_id, operator_agent)
        try:
            result = await self.start_operator_kb_seed_run(
                operator_agent_id,
                scope=str(context.get("scope") or "project"),
                project=(
                    context.get("project")
                    if isinstance(context.get("project"), str)
                    else None
                ),
                repo_root=(
                    context.get("repo_root")
                    if isinstance(context.get("repo_root"), str)
                    else None
                ),
                git_remote=(
                    context.get("git_remote")
                    if isinstance(context.get("git_remote"), str)
                    else None
                ),
                branch=(
                    context.get("branch")
                    if isinstance(context.get("branch"), str)
                    else None
                ),
                metadata=(
                    context.get("metadata")
                    if isinstance(context.get("metadata"), dict)
                    else {}
                ),
            )
        except Exception as exc:
            self.notify(f"Unable to start KB seed run: {exc}", severity="error")
            return
        seed_run = result.get("seed_run") if isinstance(result.get("seed_run"), dict) else {}
        seed_run_id = str(seed_run.get("seed_run_id") or "").strip()
        status = str(seed_run.get("status") or "requested").strip()
        command = result.get("command") if isinstance(result.get("command"), dict) else None
        await self.open_operator_kb_for_agent(operator_agent_id, status="proposed")
        detail = self.query_one_or_none("#operator-kb-detail", TextArea)
        if detail is not None:
            detail.text = self.format_operator_kb_seed_run_detail(result)
        await self.refresh_events()
        label = seed_run_id or "requested"
        command_note = ""
        if command:
            command_note = f" via {command.get('status') or 'command'}"
        severity = "error" if status == "failed" else "information"
        self.notify(
            f"KB seed run {label} {status or 'started'}{command_note}.",
            severity=severity,
        )

    async def compile_selected_operator_kb_report(self) -> None:
        operator_agent_id = self.selected_operator_kb_agent_id()
        if not operator_agent_id:
            return
        operator_agent = self.agents.get(operator_agent_id)
        if not isinstance(operator_agent, dict):
            self.notify("Select a known operator first.", severity="warning")
            return
        if self.agent_type(operator_agent) != OPERATOR_AGENT_TYPE:
            self.notify("Select an operator before compiling KB proposals.", severity="warning")
            return
        latest = self.latest_report_by_agent.get(operator_agent_id)
        report_id = str((latest or {}).get("report_id") or "").strip()
        if not report_id:
            report_id = str(operator_agent.get("latest_report_id") or "").strip()
        if not report_id:
            self.notify("Selected operator has no latest report to compile.", severity="warning")
            return
        try:
            result = await self.compile_operator_kb_report(operator_agent_id, report_id)
        except Exception as exc:
            self.notify(f"Unable to compile KB proposals: {exc}", severity="error")
            return
        logical_operator_id = self.logical_operator_id_for_agent(operator_agent)
        detail = self.query_one_or_none("#operator-kb-detail", TextArea)
        await self.open_operator_kb_for_agent(operator_agent_id, status="proposed")
        if detail is not None:
            detail.text = self.format_operator_kb_compile_result(result)
        await self.refresh_events()
        proposed_count = int_value(result.get("proposed_count")) or 0
        skipped_count = int_value(result.get("skipped_count")) or 0
        self.notify(
            f"Compiled KB proposals for {logical_operator_id}: "
            f"{proposed_count} proposed, {skipped_count} skipped."
        )

    async def reindex_operator_kb(self) -> None:
        try:
            result = await self.rebuild_operator_kb_index()
        except Exception as exc:
            self.notify(f"Unable to rebuild KB index: {exc}", severity="error")
            return
        detail = self.query_one_or_none("#operator-kb-detail", TextArea)
        if detail is not None:
            detail.text = self.format_operator_kb_index_result(result)
        processed = int_value(result.get("processed_count")) or 0
        failed = int_value(result.get("failed_count")) or 0
        severity = "error" if failed else "information"
        self.notify(
            f"KB index rebuild processed {processed} job{'s' if processed != 1 else ''}; "
            f"{failed} failed.",
            severity=severity,
        )

    async def reject_oldest_operator_kb_proposal(self) -> None:
        operator_agent_id = self.selected_operator_kb_agent_id()
        if not operator_agent_id:
            return
        operator_agent = self.agents.get(operator_agent_id)
        if operator_agent is None:
            self.notify("Select a known operator first.", severity="warning")
            return
        logical_operator_id = self.logical_operator_id_for_agent(operator_agent)
        selected_entry = self.selected_operator_kb_entry_for_operator(logical_operator_id)
        if self.active_agent_tab == "operator-kb-tab" and selected_entry is not None:
            if str(selected_entry.get("status") or "") != "proposed":
                self.notify(
                    "Select a proposed KB entry before rejecting.",
                    severity="warning",
                )
                return
            entry = selected_entry
        else:
            entry = None
        if entry is None:
            try:
                entries = await self.fetch_operator_kb_entries(
                    logical_operator_id,
                    status="proposed",
                    limit=100,
                )
            except Exception as exc:
                self.notify(f"Unable to fetch KB proposals: {exc}", severity="error")
                return
            entry = self.primary_operator_kb_entry(entries, status="proposed")
        if entry is None:
            self.notify(f"No proposed KB entries for {logical_operator_id}.")
            return
        kb_id = str(entry.get("kb_id") or "").strip()
        if not kb_id:
            self.notify("KB proposal is missing an id.", severity="error")
            return
        try:
            rejected = await self.reject_operator_kb_entry(
                logical_operator_id,
                kb_id,
                summary="Rejected from the Agent PBX TUI.",
            )
        except Exception as exc:
            self.notify(f"Unable to reject KB entry: {exc}", severity="error")
            return
        rejected_id = str(rejected.get("kb_id") or kb_id)
        self.selected_operator_kb_id_by_operator[logical_operator_id] = rejected_id
        await self.load_operator_kb(operator_agent_id, status="rejected")
        self.notify(f"Rejected operator KB entry {kb_id}.")
        await self.refresh_events()

    async def retire_selected_operator_kb_entry(self) -> None:
        operator_agent_id = self.selected_operator_kb_agent_id()
        if not operator_agent_id:
            return
        operator_agent = self.agents.get(operator_agent_id)
        if operator_agent is None:
            self.notify("Select a known operator first.", severity="warning")
            return
        logical_operator_id = self.logical_operator_id_for_agent(operator_agent)
        entry = self.selected_operator_kb_entry_for_action(
            logical_operator_id,
            status="active",
        )
        if entry is None and self.active_agent_tab != "operator-kb-tab":
            try:
                entries = await self.fetch_operator_kb_entries(
                    logical_operator_id,
                    status="active",
                    limit=100,
                )
            except Exception as exc:
                self.notify(f"Unable to fetch active KB entries: {exc}", severity="error")
                return
            entry = self.primary_operator_kb_entry(entries, status="active")
        if entry is None:
            self.notify(
                f"Select an active KB entry for {logical_operator_id} before retiring.",
                severity="warning",
            )
            return
        kb_id = str(entry.get("kb_id") or "").strip()
        if not kb_id:
            self.notify("KB entry is missing an id.", severity="error")
            return
        try:
            retired = await self.retire_operator_kb_entry(
                logical_operator_id,
                kb_id,
                summary="Retired from the Agent PBX TUI.",
            )
        except Exception as exc:
            self.notify(f"Unable to retire KB entry: {exc}", severity="error")
            return
        retired_id = str(retired.get("kb_id") or kb_id)
        self.selected_operator_kb_id_by_operator[logical_operator_id] = retired_id
        await self.load_operator_kb(operator_agent_id, status="retired")
        self.notify(f"Retired operator KB entry {kb_id}.")
        await self.refresh_events()

    async def feedback_selected_operator_kb(self, feedback: str) -> None:
        operator_agent_id = self.selected_operator_kb_agent_id()
        if not operator_agent_id:
            self.notify("Select an operator before recording KB feedback.", severity="warning")
            return
        logical_operator_id = self.operator_kb_operator_id_for_agent(operator_agent_id)
        if not logical_operator_id:
            self.notify("KB feedback is available for operator agents only.", severity="warning")
            return
        entry = self.selected_operator_kb_entry_for_operator(logical_operator_id)
        query = None
        query_id = ""
        match_id = None
        kb_id = None
        if entry is not None:
            retrieval = self.operator_kb_entry_retrieval(entry)
            query_id = str(retrieval.get("query_id") or "").strip()
            match_id = str(retrieval.get("match_id") or "").strip() or None
            kb_id = str(entry.get("kb_id") or "").strip() or None
        if not query_id:
            selected_query_id = self.selected_operator_kb_query_id_by_operator.get(
                logical_operator_id,
                "",
            )
            query = self.operator_kb_queries_by_operator.get(
                logical_operator_id,
                {},
            ).get(selected_query_id)
            query_id = selected_query_id if query is not None else ""
        if not query_id:
            self.notify(
                "Select a KB search result or query history row before recording feedback.",
                severity="warning",
            )
            return
        summary = {
            "accepted": "Marked useful from the Agent PBX TUI.",
            "rejected": "Marked wrong from the Agent PBX TUI.",
            "miss": "Marked as a KB miss from the Agent PBX TUI.",
        }.get(feedback, f"Marked {feedback} from the Agent PBX TUI.")
        try:
            result = await self.submit_operator_kb_feedback(
                logical_operator_id,
                query_id=query_id,
                match_id=match_id,
                kb_id=kb_id,
                feedback=feedback,
                summary=summary,
                metadata={"source": "agent-pbx-tui"},
            )
        except Exception as exc:
            self.notify(f"Unable to record KB feedback: {exc}", severity="error")
            return
        detail = self.query_one_or_none("#operator-kb-detail", TextArea)
        if detail is not None:
            detail.text = (
                f"Recorded KB feedback {result.get('feedback')} for query {query_id}."
            )
        self.notify(f"Recorded KB feedback: {feedback}.")
        await self.refresh_events()

    def format_operator_kb_seed_run_detail(self, result: dict[str, Any]) -> str:
        seed_run = (
            result.get("seed_run") if isinstance(result.get("seed_run"), dict) else {}
        )
        command = result.get("command") if isinstance(result.get("command"), dict) else {}
        metadata = (
            seed_run.get("metadata")
            if isinstance(seed_run.get("metadata"), dict)
            else {}
        )
        evidence = (
            metadata.get("delivery_evidence")
            if isinstance(metadata.get("delivery_evidence"), dict)
            else {}
        )
        lines = [
            "Operator KB seed run",
            "",
            f"Seed Run: {seed_run.get('seed_run_id') or '-'}",
            f"Logical Operator: {seed_run.get('logical_operator_agent_id') or '-'}",
            f"Source Operator: {seed_run.get('source_operator_agent_id') or '-'}",
            f"Status: {seed_run.get('status') or '-'}",
            f"Delivery: {seed_run.get('delivery_status') or '-'}",
            f"Command: {seed_run.get('command_id') or command.get('command_id') or '-'}",
            f"Tmux Pane: {seed_run.get('tmux_pane_id') or evidence.get('tmux_pane_id') or '-'}",
            f"Seed Type: {seed_run.get('seed_type') or '-'}",
            f"Scope: {seed_run.get('scope') or '-'}",
            f"Project: {seed_run.get('project') or '-'}",
            f"Repo: {seed_run.get('repo_root') or '-'}",
            f"Remote: {seed_run.get('git_remote') or '-'}",
            f"Branch: {seed_run.get('branch') or '-'}",
            f"Sync Key: {metadata.get('seed_sync_key') or '-'}",
        ]
        if seed_run.get("error"):
            lines.extend(["", "Error:", str(seed_run.get("error"))])
        lines.extend(
            [
                "",
                "Next:",
                "Review proposed entries in this KB tab after the operator completes the seed run.",
            ]
        )
        return "\n".join(lines)

    def format_operator_kb_compile_result(self, result: dict[str, Any]) -> str:
        entries = result.get("entries") if isinstance(result.get("entries"), list) else []
        skipped = result.get("skipped") if isinstance(result.get("skipped"), list) else []
        lines = [
            "Operator KB compile result",
            "",
            f"Operator: {result.get('operator_agent_id') or '-'}",
            f"Logical operator: {result.get('logical_operator_agent_id') or '-'}",
            f"Report: {result.get('report_id') or '-'}",
            f"Proposed: {result.get('proposed_count') or 0}",
            f"Skipped: {result.get('skipped_count') or 0}",
            "",
            "Proposals:",
        ]
        if not entries:
            lines.append("- none")
        else:
            for entry in entries[:20]:
                if isinstance(entry, dict):
                    lines.append(
                        f"- {entry.get('kb_id')}: {entry.get('title') or '-'} "
                        f"({entry.get('redaction_status') or '-'})"
                    )
        lines.append("")
        lines.append("Skipped:")
        if not skipped:
            lines.append("- none")
        else:
            for item in skipped[:20]:
                if isinstance(item, dict):
                    lines.append(
                        f"- index {item.get('index')}: {item.get('reason') or '-'}"
                    )
        return "\n".join(lines)

    def format_operator_kb_index_result(self, result: dict[str, Any]) -> str:
        jobs = result.get("jobs") if isinstance(result.get("jobs"), list) else []
        failed = result.get("failed") if isinstance(result.get("failed"), list) else []
        lines = [
            "Operator KB index result",
            "",
            f"Processed: {result.get('processed_count') or 0}",
            f"Failed: {result.get('failed_count') or 0}",
            "",
            "Jobs:",
        ]
        if not jobs:
            lines.append("- none")
        else:
            for job in jobs[:20]:
                if isinstance(job, dict):
                    lines.append(
                        f"- {job.get('job_id')}: {job.get('operation')} "
                        f"{job.get('status')}"
                    )
        if failed:
            lines.extend(["", "Failures:"])
            for job in failed[:20]:
                if isinstance(job, dict):
                    lines.append(
                        f"- {job.get('job_id')}: {job.get('error') or 'failed'}"
                    )
        return "\n".join(lines)

    @staticmethod
    def primary_operator_kb_entry(
        entries: list[dict[str, Any]],
        *,
        status: str,
    ) -> dict[str, Any] | None:
        if not entries:
            return None
        if status == "proposed":
            return sorted(
                entries,
                key=lambda item: (
                    float_value(item.get("created_at")) or 0.0,
                    str(item.get("kb_id") or ""),
                ),
            )[0]
        return sorted(
            entries,
            key=lambda item: (
                float_value(item.get("updated_at")) or 0.0,
                str(item.get("kb_id") or ""),
            ),
            reverse=True,
        )[0]

    def format_operator_kb_entries(
        self,
        logical_operator_id: str,
        entries: list[dict[str, Any]],
        *,
        status: str | None,
    ) -> str:
        title_status = status or "all"
        lines = [
            f"Operator KB entries: {logical_operator_id} ({title_status})",
            "",
        ]
        if not entries:
            lines.append("No operator KB entries.")
            return "\n".join(lines)
        for entry in entries:
            tags = entry.get("tags") if isinstance(entry.get("tags"), list) else []
            sources = (
                entry.get("sources")
                if isinstance(entry.get("sources"), list)
                else []
            )
            source_count = len(sources)
            updated_at = float_value(entry.get("updated_at"))
            updated_text = (
                self.format_short_time(updated_at)
                if updated_at is not None
                else "-"
            )
            expires_at = float_value(entry.get("expires_at"))
            expires_text = (
                self.format_short_time(expires_at)
                if expires_at is not None
                else "-"
            )
            lines.extend(
                [
                    f"- {entry.get('kb_id')}",
                    f"  title: {entry.get('title') or '-'}",
                    f"  status: {entry.get('status')}  redaction: {entry.get('redaction_status')}",
                    f"  scope: {entry.get('scope')}  project: {entry.get('project') or '-'}",
                    f"  repo: {entry.get('repo_root') or '-'}",
                    f"  tags: {', '.join(str(tag) for tag in tags) or '-'}",
                    f"  sources: {source_count}  updated: {updated_text}  expires: {expires_text}",
                    f"  summary: {entry.get('summary') or '-'}",
                ]
            )
        return "\n".join(lines)

    @staticmethod
    def operator_kb_entry_retrieval(entry: dict[str, Any]) -> dict[str, Any]:
        metadata = entry.get("metadata") if isinstance(entry.get("metadata"), dict) else {}
        retrieval = (
            metadata.get("retrieval")
            if isinstance(metadata.get("retrieval"), dict)
            else {}
        )
        return dict(retrieval) if isinstance(retrieval, dict) else {}

    def format_operator_kb_query_detail(
        self,
        logical_operator_id: str,
        query: dict[str, Any],
    ) -> str:
        matches = (
            query.get("matches")
            if isinstance(query.get("matches"), list)
            else []
        )
        feedback_summary = (
            query.get("feedback_summary")
            if isinstance(query.get("feedback_summary"), dict)
            else {}
        )
        created_at = float_value(query.get("created_at"))
        created_text = (
            self.format_short_time(created_at)
            if created_at is not None
            else "-"
        )
        lines = [
            f"Operator KB query: {logical_operator_id}",
            "",
            f"Query ID: {query.get('query_id')}",
            f"Query: {query.get('query') or '-'}",
            f"Created: {created_text}",
            f"Source: {query.get('source') or '-'}",
            f"Mode: {query.get('retrieval_mode') or '-'}",
            f"Provider: {query.get('retrieval_provider') or '-'}",
            f"Model: {query.get('retrieval_model') or '-'}",
            f"Index: {query.get('index_version') or '-'}",
            f"Project: {query.get('project') or '-'}",
            f"Repo: {query.get('repo_root') or '-'}",
            f"Matches: {query.get('match_count') or 0}",
            f"Semantic matches: {query.get('semantic_match_count') or 0}",
            f"Feedback: {json.dumps(feedback_summary, sort_keys=True)}",
            "",
            "Top Matches:",
        ]
        if not matches:
            lines.append("- none")
        for match in matches[:5]:
            if not isinstance(match, dict):
                continue
            score = float_value(match.get("score"))
            semantic_score = float_value(match.get("semantic_score"))
            score_text = f"{score:.3f}" if score is not None else "-"
            lines.append(
                f"- rank {match.get('rank')}: {match.get('kb_id') or '-'} "
                f"mode={match.get('retrieval_mode') or '-'} score={score_text}"
            )
            if semantic_score is not None:
                lines.append(f"  semantic_score: {semantic_score:.3f}")
            chunks = (
                match.get("semantic_chunks")
                if isinstance(match.get("semantic_chunks"), list)
                else []
            )
            for chunk in chunks[:3]:
                if isinstance(chunk, dict):
                    lines.append(
                        "  chunk "
                        f"{chunk.get('chunk_index')}: score={chunk.get('score')} "
                        f"tokens={chunk.get('token_count')}"
                    )
        return "\n".join(lines)

    def format_operator_kb_entry_detail(
        self,
        logical_operator_id: str,
        entry: dict[str, Any],
    ) -> str:
        tags = entry.get("tags") if isinstance(entry.get("tags"), list) else []
        sources = entry.get("sources") if isinstance(entry.get("sources"), list) else []
        metadata = (
            entry.get("metadata")
            if isinstance(entry.get("metadata"), dict)
            else {}
        )
        retrieval = self.operator_kb_entry_retrieval(entry)
        lines = [
            f"Operator KB entry: {logical_operator_id}",
            "",
            f"KB ID: {entry.get('kb_id')}",
            f"Title: {entry.get('title') or '-'}",
            f"Status: {entry.get('status')}",
            f"Redaction: {entry.get('redaction_status')}",
            f"Scope: {entry.get('scope')}",
            f"Project: {entry.get('project') or '-'}",
            f"Repo: {entry.get('repo_root') or '-'}",
            f"Remote: {entry.get('git_remote') or '-'}",
            f"Branch: {entry.get('branch') or '-'}",
            f"Tags: {', '.join(str(tag) for tag in tags) or '-'}",
            f"Source link: {entry.get('source_knowledge_link_id') or '-'}",
            f"Source handoff: {entry.get('source_handoff_id') or '-'}",
            "",
            "Summary:",
            str(entry.get("summary") or "-"),
            "",
            "Body:",
            str(entry.get("body") or "-"),
            "",
            "Sources:",
        ]
        if not sources:
            lines.append("- none")
        else:
            for source in sources:
                if isinstance(source, dict):
                    lines.append(
                        f"- {source.get('source_type')}: {source.get('source_id')}"
                    )
        if retrieval:
            lines.extend(
                [
                    "",
                    "Retrieval:",
                    f"query_id: {retrieval.get('query_id') or '-'}",
                    f"match_id: {retrieval.get('match_id') or '-'}",
                    f"mode: {retrieval.get('mode') or '-'}",
                    f"sources: {', '.join(str(item) for item in retrieval.get('sources', [])) or '-'}",
                    f"score: {retrieval.get('score') if retrieval.get('score') is not None else '-'}",
                    f"semantic_score: {retrieval.get('semantic_score') if retrieval.get('semantic_score') is not None else '-'}",
                    "chunks:",
                ]
            )
            chunks = (
                retrieval.get("semantic_chunks")
                if isinstance(retrieval.get("semantic_chunks"), list)
                else []
            )
            if not chunks:
                lines.append("- none")
            for chunk in chunks[:5]:
                if isinstance(chunk, dict):
                    lines.append(
                        f"- {chunk.get('chunk_index')}: "
                        f"score={chunk.get('score')} tokens={chunk.get('token_count')}"
                    )
        lines.extend(
            [
                "",
                "Metadata:",
                json.dumps(metadata, indent=2, sort_keys=True),
            ]
        )
        return "\n".join(lines)

    async def update_project_spawn_request_status(
        self,
        spawn_request_id: str,
        *,
        status: str,
        launched_agent_id: str | None = None,
        tmux_pane_id: str | None = None,
        error: str | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        response = await self.api_client().post(
            f"/v1/operator/project-spawns/{spawn_request_id}/status",
            json={
                "status": status,
                "launched_agent_id": launched_agent_id,
                "tmux_pane_id": tmux_pane_id,
                "error": error,
                "metadata": metadata or {},
            },
            headers=auth_headers(self.token),
        )
        response.raise_for_status()
        payload = response.json()
        if isinstance(payload, dict):
            return payload
        raise RuntimeError("project spawn status response was not an object")

    async def fail_project_spawn_request(
        self,
        request: dict[str, Any],
        error: str,
    ) -> None:
        spawn_request_id = str(request.get("spawn_request_id") or "").strip()
        if not spawn_request_id:
            return
        try:
            await self.update_project_spawn_request_status(
                spawn_request_id,
                status="failed",
                error=error[:4000],
            )
        except Exception as exc:
            self.notify(
                f"Unable to record project spawn failure: {exc}",
                severity="warning",
            )

    async def launch_pending_project_spawn_request(self) -> None:
        operator_agent_id = self.selected_operator_agent_id()
        if not operator_agent_id:
            return
        operator_agent = self.agents.get(operator_agent_id)
        if operator_agent is None:
            self.notify("Select a known operator first.", severity="warning")
            return
        logical_operator_id = self.logical_operator_id_for_agent(operator_agent)
        if not self.tmux_features_available:
            self.notify("Tmux is required to launch project spawn requests.", severity="warning")
            return
        if not await self.ensure_operator_auth_ready():
            return
        try:
            pending = await self.fetch_pending_project_spawn_requests(logical_operator_id)
        except Exception as exc:
            self.notify(f"Unable to fetch project spawn requests: {exc}", severity="error")
            return
        if not pending:
            self.notify(f"No pending project spawn requests for {logical_operator_id}.")
            return
        request = pending[0]
        launched = await self.launch_project_spawn_request(request)
        if launched and len(pending) > 1:
            self.notify(
                f"Launched oldest project spawn; {len(pending) - 1} pending request(s) remain."
            )

    async def launch_project_spawn_request(self, request: dict[str, Any]) -> bool:
        spawn_request_id = str(request.get("spawn_request_id") or "").strip()
        if not spawn_request_id:
            self.notify("Project spawn request is missing an id.", severity="error")
            return False
        try:
            await asyncio.to_thread(validate_stored_project_spawn_preflight, request)
        except Exception as exc:
            error = str(exc)
            detail = self.query_one_or_none("#detail", TextArea)
            if detail is not None:
                detail.text = (
                    "Project spawn approval blocked before launch.\n\n"
                    f"Request: {spawn_request_id}\n"
                    f"Target: {request.get('target_path') or '-'}\n"
                    f"Error: {error}\n\n"
                    "The request remains pending so it can be inspected or canceled."
                )
            self.notify(f"Project spawn approval blocked: {error}", severity="warning")
            return False
        try:
            request = await self.update_project_spawn_request_status(
                spawn_request_id,
                status="launching",
            )
            target_path = await asyncio.to_thread(self.create_project_spawn_repo, request)
            codex_command = self.operator_codex_command()
            mcp_url = agent_pbx_mcp_url(self.server)
            await self.configure_operator_codex_mcp(
                codex_command=codex_command,
                mcp_url=mcp_url,
            )
            project = target_path.name
            agent_id = self.spawned_project_agent_id(project)
            workerbee_gateway_binding = await self.prepare_workerbee_gateway_launch(
                agent_id=agent_id,
                project=project,
                codex_session_id="",
                profile=WORKERBEE_PROFILE_OBSERVE,
                source_root=str(target_path),
            )
            bootstrap = self.spawned_project_bootstrap_prompt(
                agent_id=agent_id,
                project=project,
                cwd=str(target_path),
                request=request,
            )
            command = self.codex_start_command(
                codex_command,
                bootstrap,
                cd=str(target_path),
                sandbox="workspace-write",
                config_overrides=caller_agent_config_overrides(
                    mcp_url=mcp_url,
                    work_root=str(target_path),
                    terminal_mode=self.codex_terminal_mode,
                    workerbee_profile=WORKERBEE_PROFILE_OBSERVE,
                    workerbee_gateway_binding=workerbee_gateway_binding,
                ),
            )
            runtime_session_name, runtime_kwargs = await self.configured_runtime_launch_target(
                agent_id,
                fallback_session_name=self.caller_tmux_session_name(),
            )
            pane_id = await self.launch_restart_pane(
                session_name=runtime_session_name,
                window_name=agent_id,
                command=command,
                label=agent_id,
                cwd=str(target_path),
                env=self.caller_launch_env(
                    agent_id=agent_id,
                    project=project,
                    cwd=str(target_path),
                    mcp_url=mcp_url,
                    request=request,
                    workerbee_gateway_binding=workerbee_gateway_binding,
                ),
                **runtime_kwargs,
            )
            await self.register_spawned_project_caller(
                agent_id=agent_id,
                project=project,
                cwd=str(target_path),
                pane_id=pane_id,
                codex_command=codex_command,
                mcp_url=mcp_url,
                request=request,
                tmux_session_name=runtime_session_name,
                workerbee_gateway_binding=workerbee_gateway_binding,
            )
            await self.register_launched_tmux_runtime(
                agent_id,
                pane_id,
                runtime_kwargs=runtime_kwargs,
                mapping_source="project_spawn",
            )
            await self.update_project_spawn_request_status(
                spawn_request_id,
                status="launched",
                launched_agent_id=agent_id,
                tmux_pane_id=pane_id,
                metadata={"target_path": str(target_path)},
            )
        except Exception as exc:
            error = str(exc)
            await self.fail_project_spawn_request(request, error)
            detail = self.query_one_or_none("#detail", TextArea)
            if detail is not None:
                detail.text = (
                    f"Project spawn failed.\n\n"
                    f"Request: {spawn_request_id}\n"
                    f"Target: {request.get('target_path') or '-'}\n"
                    f"Error: {error}"
                )
            self.notify(f"Unable to launch project spawn: {error}", severity="error")
            await self.refresh_events()
            return False

        self.tmux_agent_targets[agent_id] = pane_id
        self.tmux_manual_override_agent_ids.add(agent_id)
        self.tmux_detached_agent_ids.discard(agent_id)
        self.tmux_direct_agent_modes[agent_id] = True
        self.save_settings()
        detail = self.query_one_or_none("#detail", TextArea)
        if detail is not None:
            detail.text = (
                f"Launched project spawn.\n\n"
                f"Request: {spawn_request_id}\n"
                f"Agent: {agent_id}\n"
                f"Project: {project}\n"
                f"Path: {target_path}\n"
                f"Pane: {pane_id}"
            )
        self.notify(f"Launched {agent_id} for {target_path.name}.")
        await self.refresh_agents()
        await self.refresh_events()
        await self.open_latest_for_agent(agent_id)
        return True

    def source_caller_agent_id_for_review_fork(
        self,
        operator_agent_id: str,
    ) -> str | None:
        operator_agent = self.agents.get(operator_agent_id)
        if not isinstance(operator_agent, dict):
            return None
        metadata = (
            operator_agent.get("metadata")
            if isinstance(operator_agent.get("metadata"), dict)
            else {}
        )
        if self.operator_role(operator_agent) == OPERATOR_ROLE_FORK:
            source_agent_id = str(metadata.get("source_caller_agent_id") or "").strip()
            return source_agent_id or None
        default_source = str(metadata.get("default_source_caller_agent_id") or "").strip()
        if default_source:
            return default_source
        active_source = self.single_active_operator_fork_source_agent_id(
            self.logical_operator_id_for_agent(operator_agent)
        )
        if active_source:
            return active_source
        return None

    def operator_review_work_root(
        self,
        *,
        logical_operator_id: str,
        source_caller_agent_id: str,
        source_cwd: str,
        fork_track_id: str,
    ) -> str:
        source_root = Path(source_cwd).expanduser().resolve()
        configured = os.getenv("AGENT_PBX_TUI_OPERATOR_REVIEW_ROOT", "").strip()
        if configured:
            base = Path(configured).expanduser()
        else:
            base = source_root.parent / ".agent-pbx-review"
        work_root = (
            base
            / slugify(
                f"{logical_operator_id}-{source_caller_agent_id}-{fork_track_id}"
            )[:140]
        ).resolve()
        if work_root == source_root or work_root.is_relative_to(source_root):
            raise RuntimeError(
                "review work_root resolves inside the caller project; set "
                "AGENT_PBX_TUI_OPERATOR_REVIEW_ROOT outside the repo"
            )
        work_root.mkdir(parents=True, exist_ok=True)
        return str(work_root)

    async def next_operator_review_fork_track_id(
        self,
        *,
        logical_operator_id: str,
        source_caller_agent_id: str,
        source_codex_session_id: str,
    ) -> str:
        forks: list[dict[str, Any]] = []
        try:
            response = await self.api_client().get(
                "/v1/operator/forks",
                params={
                    "operator_agent_id": logical_operator_id,
                    "source_caller_agent_id": source_caller_agent_id,
                    "limit": 100,
                },
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            payload = response.json()
            if isinstance(payload, dict) and isinstance(payload.get("forks"), list):
                forks.extend(item for item in payload["forks"] if isinstance(item, dict))
        except Exception:
            pass
        for fork in self.operator_fork_agents():
            if self.logical_operator_id_for_agent(fork) == logical_operator_id:
                forks.append(fork)
        used: set[int] = set()
        for fork in forks:
            metadata = fork.get("metadata") if isinstance(fork.get("metadata"), dict) else {}
            if (
                str(
                    fork.get("source_caller_agent_id")
                    or metadata.get("source_caller_agent_id")
                    or ""
                ).strip()
                != source_caller_agent_id
            ):
                continue
            if (
                str(
                    fork.get("source_codex_session_id")
                    or metadata.get("source_codex_session_id")
                    or ""
                ).strip()
                != source_codex_session_id
            ):
                continue
            track_id = str(
                fork.get("fork_track_id")
                or metadata.get("fork_track_id")
                or ""
            ).strip()
            match = re.fullmatch(r"review-(\d+)", track_id)
            if match:
                used.add(int(match.group(1)))
        index = 1
        while index in used:
            index += 1
        return f"review-{index}"

    async def start_review_operator_fork(self) -> None:
        if not self.tmux_features_available:
            self.notify(
                "Tmux is required to start an operator review fork from the TUI.",
                severity="warning",
            )
            return
        operator_agent_id = self.selected_operator_agent_id()
        if not operator_agent_id:
            return
        operator_agent = self.agents.get(operator_agent_id)
        if not isinstance(operator_agent, dict):
            return
        await self.reconcile_operator_tmux_targets()
        logical_operator_id = self.logical_operator_id_for_agent(operator_agent)
        source_caller_agent_id = await self.resolve_source_caller_agent_id_for_review_fork(
            operator_agent_id
        )
        if not source_caller_agent_id:
            self.notify(
                "Selected operator has no default or active source caller. "
                "Start or bind the operator to a caller first.",
                severity="warning",
            )
            return
        await self.ensure_agent_loaded(source_caller_agent_id)
        blocker = self.operator_fork_start_blocker(source_caller_agent_id)
        if blocker:
            self.notify(blocker, severity="error")
            return
        caller = self.agents.get(source_caller_agent_id)
        if not isinstance(caller, dict):
            self.notify(f"Caller {source_caller_agent_id} is not loaded.", severity="error")
            return
        caller_metadata = (
            caller.get("metadata") if isinstance(caller.get("metadata"), dict) else {}
        )
        source_session_id = str(caller_metadata.get("codex_session_id") or "").strip()
        source_cwd = str(caller_metadata.get("cwd") or "").strip()
        if not await self.ensure_operator_auth_ready():
            return
        fork_track_id = await self.next_operator_review_fork_track_id(
            logical_operator_id=logical_operator_id,
            source_caller_agent_id=source_caller_agent_id,
            source_codex_session_id=source_session_id,
        )
        try:
            work_root = self.operator_review_work_root(
                logical_operator_id=logical_operator_id,
                source_caller_agent_id=source_caller_agent_id,
                source_cwd=source_cwd,
                fork_track_id=fork_track_id,
            )
            fork = await self.ensure_operator_fork_from_tui(
                logical_operator_id=logical_operator_id,
                source_caller_agent_id=source_caller_agent_id,
                fork_track_id=fork_track_id,
                fork_purpose=REVIEW_OPERATOR_FORK_PURPOSE,
                access_mode=REVIEW_OPERATOR_FORK_ACCESS_MODE,
                work_root=work_root,
            )
        except Exception as exc:
            self.notify(f"Unable to start review fork: {exc}", severity="error")
            return
        if fork is None:
            return
        self.save_settings()
        await self.refresh_agents()
        fork_agent_id = str(fork.get("fork_agent_id") or "").strip()
        if fork_agent_id:
            await self.open_latest_for_agent(fork_agent_id)
        self.notify(
            f"Started review fork {fork_agent_id or fork_track_id} for "
            f"{source_caller_agent_id} in {work_root}."
        )

    async def start_operator_agent(
        self,
        agent_id: str | None = None,
        *,
        source_caller_agent_id: str | None = None,
    ) -> None:
        if not self.tmux_features_available:
            self.notify(
                "Tmux is required to start an operator from the TUI.",
                severity="warning",
            )
            return
        source_caller_agent_id = source_caller_agent_id or (
            self.start_operator_source_caller_agent_id() if agent_id is None else None
        )
        if source_caller_agent_id:
            blocker = self.operator_fork_start_blocker(source_caller_agent_id)
            if blocker:
                self.notify(blocker, severity="error")
                return
        if not await self.ensure_operator_auth_ready():
            return
        agent_id = agent_id or self.next_operator_agent_id()
        cwd = self.operator_cwd()
        codex_command = self.operator_codex_command()
        session_name = self.operator_tmux_session_name()
        mcp_url = agent_pbx_mcp_url(self.server)
        try:
            await self.configure_operator_codex_mcp(
                codex_command=codex_command,
                mcp_url=mcp_url,
            )
        except Exception as exc:
            self.notify(f"Unable to configure Codex MCP: {exc}", severity="error")
            return
        try:
            root_agent, root_pane_id, root_launched = await self.ensure_operator_root_from_tui(
                agent_id=agent_id,
                cwd=cwd,
                codex_command=codex_command,
                mcp_url=mcp_url,
                session_name=session_name,
                source_caller_agent_id=source_caller_agent_id,
            )
        except Exception as exc:
            self.notify(f"Unable to start operator root: {exc}", severity="error")
            return
        if source_caller_agent_id:
            try:
                fork = await self.ensure_operator_fork_from_tui(
                    logical_operator_id=agent_id,
                    source_caller_agent_id=source_caller_agent_id,
                )
            except Exception as exc:
                self.notify(f"Unable to start operator fork: {exc}", severity="error")
                return
            if fork is None:
                return
            self.save_settings()
            await self.refresh_agents()
            await self.open_latest_for_agent(agent_id)
            if root_launched:
                self.notify(
                    f"Started operator {agent_id} with fork {fork['fork_agent_id']}."
                )
            else:
                self.notify(
                    f"Reused operator {agent_id} and started fork {fork['fork_agent_id']}."
                )
            return
        self.save_settings()
        if root_launched:
            self.notify(f"Started operator {agent_id}.")
        else:
            self.notify(f"Reused operator {agent_id}.")
        await self.refresh_agents()
        await self.open_latest_for_agent(agent_id)
        _ = root_agent, root_pane_id

    def is_operator_agent_id(self, agent_id: str) -> bool:
        agent = self.agents.get(agent_id)
        return agent is not None and self.agent_type(agent) == OPERATOR_AGENT_TYPE

    def operator_fork_record_agent(self, fork: dict[str, Any]) -> dict[str, Any]:
        fork_agent_id = str(fork.get("fork_agent_id") or fork.get("agent_id") or "").strip()
        metadata = fork.get("metadata") if isinstance(fork.get("metadata"), dict) else {}
        hydrated_metadata = dict(metadata)
        clear_resume_identity = (
            hydrated_metadata.get("fork_resume_disabled_reason")
            == "source_session_collision"
        )
        if clear_resume_identity:
            for key in FORK_RESUME_IDENTITY_METADATA_KEYS:
                hydrated_metadata.pop(key, None)
        identity = {
            "agent_type": OPERATOR_AGENT_TYPE,
            "operator_role": OPERATOR_ROLE_FORK,
            "operator_fork_id": str(fork.get("operator_fork_id") or ""),
            "reporting_agent_id": fork_agent_id,
            "logical_operator_id": str(fork.get("logical_operator_agent_id") or ""),
            "source_caller_agent_id": str(fork.get("source_caller_agent_id") or ""),
            "source_codex_session_id": str(fork.get("source_codex_session_id") or ""),
            "fork_track_id": str(
                fork.get("fork_track_id") or DEFAULT_OPERATOR_FORK_TRACK_ID
            ),
            "fork_purpose": str(
                fork.get("fork_purpose") or DEFAULT_OPERATOR_FORK_PURPOSE
            ),
            "access_mode": str(
                fork.get("access_mode") or DEFAULT_OPERATOR_FORK_ACCESS_MODE
            ),
        }
        hydrated_metadata.update({key: value for key, value in identity.items() if value})
        for key in (
            "cwd",
            "source_cwd",
            "work_root",
            "fork_codex_session_id",
            "tmux_pane_id",
        ):
            value = str(fork.get(key) or "").strip()
            if value:
                hydrated_metadata[key] = value
        timestamp = (
            float_value(fork.get("last_used_at"))
            or float_value(fork.get("updated_at"))
            or float_value(fork.get("created_at"))
            or time.time()
        )
        created_at = float_value(fork.get("created_at")) or timestamp
        local_agent = self.agents.get(fork_agent_id)
        if isinstance(local_agent, dict):
            agent = dict(local_agent)
            agent_metadata = (
                agent.get("metadata") if isinstance(agent.get("metadata"), dict) else {}
            )
            agent_metadata = dict(agent_metadata)
            if clear_resume_identity:
                for key in FORK_RESUME_IDENTITY_METADATA_KEYS:
                    agent_metadata.pop(key, None)
            agent["metadata"] = {**agent_metadata, **hydrated_metadata}
            agent["agent_type"] = OPERATOR_AGENT_TYPE
            agent.setdefault("created_at", created_at)
            agent.setdefault("last_seen_at", timestamp)
            source_project = str(
                hydrated_metadata.get("source_caller_project") or ""
            ).strip()
            if source_project:
                agent["project"] = source_project
            return agent
        source_project = str(hydrated_metadata.get("source_caller_project") or "").strip()
        return {
            "agent_id": fork_agent_id,
            "agent_type": OPERATOR_AGENT_TYPE,
            "project": source_project or str(fork.get("cwd") or "agent-pbx-operator"),
            "status": str(fork.get("status") or "unknown"),
            "metadata": hydrated_metadata,
            "created_at": created_at,
            "last_seen_at": timestamp,
            "pbx_active": True,
        }

    def validated_operator_fork_pane(
        self,
        fork_agent_id: str,
        panes: list[tmux_support.TmuxPane],
        *,
        tmux_pane_id: str | None = None,
    ) -> tmux_support.TmuxPane | None:
        fork_agent = self.agents.get(fork_agent_id) or {
            "agent_id": fork_agent_id,
            "agent_type": OPERATOR_AGENT_TYPE,
            "metadata": {"operator_role": OPERATOR_ROLE_FORK},
        }
        candidates = panes
        target = str(tmux_pane_id or "").strip()
        if target:
            candidates = [
                pane
                for pane in panes
                if pane.pane_id == target or pane.target_label == target
            ]
        matches = [
            pane
            for pane in candidates
            if self.tmux_pane_allowed_for_agent(fork_agent, pane)
        ]
        if len(matches) == 1:
            return matches[0]
        return None

    def operator_fork_is_running(self, fork: dict[str, Any]) -> bool:
        metadata = fork.get("metadata") if isinstance(fork.get("metadata"), dict) else {}
        pending = str(metadata.get("operator_fork_pending") or "").strip().lower()
        if pending in {"1", "true", "yes", "on"}:
            return False
        if not bool(fork.get("pbx_active", True)):
            return False
        status = (
            str(fork.get("effective_status") or fork.get("status") or "")
            .strip()
            .lower()
        )
        return status in {
            "active",
            "online",
            "ready",
            "running",
            "starting",
            "working",
            "in_progress",
        }

    def operator_fork_pane_targets(
        self,
        logical_operator_id: str,
        panes: list[tmux_support.TmuxPane],
    ) -> list[tuple[dict[str, Any], tmux_support.TmuxPane]]:
        targets: list[tuple[dict[str, Any], tmux_support.TmuxPane]] = []
        seen: set[tuple[str, str]] = set()
        operator_session_name = self.operator_tmux_session_name()

        def add_target(fork: dict[str, Any], pane: tmux_support.TmuxPane) -> None:
            fork_agent_id = str(fork.get("agent_id") or "").strip()
            if not fork_agent_id:
                return
            key = (fork_agent_id, pane.pane_id)
            if key in seen:
                return
            seen.add(key)
            targets.append((fork, pane))

        for fork in self.operator_forks_for_logical_operator(logical_operator_id):
            fork_agent_id = str(fork.get("agent_id") or "").strip()
            if not fork_agent_id:
                continue
            metadata = fork.get("metadata") if isinstance(fork.get("metadata"), dict) else {}
            explicit_targets = {
                str(self.tmux_agent_targets.get(fork_agent_id) or "").strip(),
                str(metadata.get("tmux_pane_id") or "").strip(),
            }
            explicit_targets.discard("")
            for pane in panes:
                if pane.pane_id in explicit_targets or pane.target_label in explicit_targets:
                    if self.tmux_pane_allowed_for_agent(fork, pane):
                        add_target(fork, pane)
                    elif self.tmux_agent_targets.get(fork_agent_id) in {
                        pane.pane_id,
                        pane.target_label,
                    }:
                        self.clear_saved_tmux_target(fork_agent_id)

            for pane in panes:
                if pane.session_name != operator_session_name:
                    continue
                if not self.tmux_pane_allowed_for_agent(fork, pane):
                    continue
                add_target(fork, pane)

        return targets

    def current_operator_fork_target_key(self, logical_operator_id: str) -> str | None:
        selected_agent_id = self.selected_agent_id
        if selected_agent_id and selected_agent_id in self.agents:
            selected_agent = self.agents[selected_agent_id]
            if (
                self.operator_role(selected_agent) == OPERATOR_ROLE_FORK
                and self.logical_operator_id_for_agent(selected_agent) == logical_operator_id
            ):
                pane_id = (
                    self.tmux_visible_pane_id_for_agent(selected_agent_id)
                    or self.tmux_agent_targets.get(selected_agent_id)
                )
                if pane_id:
                    return f"{selected_agent_id}:{pane_id}"
        return self.selected_operator_fork_target_by_operator.get(logical_operator_id)

    async def view_operator_fork_pane(
        self,
        *,
        logical_operator_id: str,
        fork: dict[str, Any],
        pane: tmux_support.TmuxPane,
        index: int,
        total: int,
    ) -> None:
        fork_agent_id = str(fork.get("agent_id") or "").strip()
        if not fork_agent_id:
            return
        self.tmux_agent_targets[fork_agent_id] = pane.pane_id
        self.tmux_manual_override_agent_ids.add(fork_agent_id)
        self.tmux_detached_agent_ids.discard(fork_agent_id)
        self.tmux_direct_agent_modes[fork_agent_id] = True
        self.selected_operator_fork_target_by_operator[logical_operator_id] = (
            f"{fork_agent_id}:{pane.pane_id}"
        )
        self.active_agent_tab_by_agent[fork_agent_id] = "latest-tab"
        self.save_settings()
        await self.select_agent(fork_agent_id)
        self.move_operator_cursor(fork_agent_id, focus=True)
        source_caller = ""
        track_id = ""
        purpose = ""
        metadata = fork.get("metadata") if isinstance(fork.get("metadata"), dict) else {}
        if metadata:
            source_caller = str(metadata.get("source_caller_agent_id") or "").strip()
            track_id = str(
                metadata.get("fork_track_id") or DEFAULT_OPERATOR_FORK_TRACK_ID
            ).strip()
            purpose = str(
                metadata.get("fork_purpose") or DEFAULT_OPERATOR_FORK_PURPOSE
            ).strip()
        detail = self.query_one_or_none("#detail", TextArea)
        if detail is not None:
            detail.text = (
                f"Viewing fork pane {index + 1}/{total} for {logical_operator_id}.\n"
                f"Fork: {fork_agent_id}\n"
                f"Track: {track_id or '-'}\n"
                f"Purpose: {purpose or '-'}\n"
                f"Pane: {pane.pane_id} ({pane.target_label})\n"
                f"Source caller: {source_caller or '-'}"
            )
        self.notify(
            f"Viewing fork {index + 1}/{total}: {fork_agent_id} "
            f"{track_id or DEFAULT_OPERATOR_FORK_TRACK_ID} {pane.pane_id}."
        )

    async def cycle_selected_operator_fork(self, direction: int) -> None:
        operator_agent_id = self.selected_operator_agent_id()
        if not operator_agent_id:
            return
        operator_agent = self.agents.get(operator_agent_id)
        if operator_agent is None:
            self.notify("Select a known operator first.", severity="warning")
            return
        logical_operator_id = self.logical_operator_id_for_agent(operator_agent)
        try:
            panes = await asyncio.to_thread(tmux_support.list_panes)
        except Exception as exc:
            self.notify(f"Unable to list tmux panes: {exc}", severity="error")
            return
        self.tmux_panes = panes
        targets = self.operator_fork_pane_targets(logical_operator_id, panes)
        if not targets:
            self.notify(
                f"No live fork panes found for {logical_operator_id}.",
                severity="warning",
            )
            return
        current_key = self.current_operator_fork_target_key(logical_operator_id)
        current_index = next(
            (
                index
                for index, (fork, pane) in enumerate(targets)
                if f"{fork.get('agent_id')}:{pane.pane_id}" == current_key
            ),
            -1,
        )
        if current_index < 0:
            next_index = 0 if direction >= 0 else len(targets) - 1
        else:
            next_index = (current_index + direction) % len(targets)
        fork, pane = targets[next_index]
        await self.view_operator_fork_pane(
            logical_operator_id=logical_operator_id,
            fork=fork,
            pane=pane,
            index=next_index,
            total=len(targets),
        )

    def selected_operator_agent_id(self) -> str | None:
        focused_agent_id = self.focused_agent_table_id()
        if focused_agent_id and self.is_operator_agent_id(focused_agent_id):
            return focused_agent_id
        cursor_operator_id = self.operator_id_at_cursor()
        if cursor_operator_id and self.is_operator_agent_id(cursor_operator_id):
            return cursor_operator_id
        if self.selected_agent_id and self.is_operator_agent_id(self.selected_agent_id):
            return self.selected_agent_id
        agent_input = self.query_one_or_none("#agent-id", Input)
        if agent_input is not None:
            value = agent_input.value.strip()
            if value and self.is_operator_agent_id(value):
                return value
        self.notify("Select an operator first.", severity="warning")
        return None

    def palette_operator_lifecycle_target(self, action: str) -> str | None:
        """Return one explicitly aligned Operators-table target for a palette action."""

        cursor_agent_id = self.operator_id_at_cursor()
        selected_agent_id = str(self.selected_agent_id or "").strip()
        if not cursor_agent_id or not self.is_operator_agent_id(cursor_agent_id):
            self.notify(
                f"Select the operator to {action} in the Operators table and press "
                "Enter before using the command palette.",
                severity="warning",
            )
            return None
        if (
            not selected_agent_id
            or not self.is_operator_agent_id(selected_agent_id)
            or selected_agent_id != cursor_agent_id
        ):
            active_label = selected_agent_id or "none"
            self.notify(
                "Operator selection mismatch; no action was taken. "
                f"Operators cursor: {cursor_agent_id}; active selection: "
                f"{active_label}. Press Enter on the intended Operators row, "
                "then reopen the command palette.",
                severity="warning",
            )
            return None
        return cursor_agent_id

    def schedule_operator_broker_requests(self) -> None:
        if (
            self.operator_broker_worker_active
            or self.shutting_down
            or not self.operator_broker_posture.root_operator_enabled
            or self.remote_client_role == "observer"
            or not is_local_server_url(self.server)
        ):
            return
        self.operator_broker_worker_active = True
        self.run_worker(
            self.process_operator_broker_requests(),
            name="operator-broker-requests",
            group="operator-broker-requests",
            exclusive=True,
            exit_on_error=False,
        )

    async def process_operator_broker_requests(self) -> None:
        """Claim and advance one durable local root-supervised request."""

        try:
            response = await self.api_client().get(
                "/v1/operator/broker-checkpoints",
                params={"status_filter": "pending", "limit": 1},
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            payload = response.json()
            raw = payload.get("requests") if isinstance(payload, dict) else []
            request = next(
                (item for item in raw if isinstance(item, dict)),
                None,
            )
            if request is None:
                return
            request_id = str(request.get("request_id") or "").strip()
            if not request_id:
                return
            claimed_response = await self.api_client().post(
                f"/v1/operator/broker-checkpoints/{request_id}/claim",
                json={
                    "executor_id": self.operator_broker_executor_id,
                    "lease_seconds": 60,
                },
                headers=auth_headers(self.token),
            )
            if claimed_response.status_code in {400, 409}:
                return
            claimed_response.raise_for_status()
            claimed = claimed_response.json()
            if not isinstance(claimed, dict):
                raise RuntimeError("broker claim response was not an object")
            self.operator_broker_request_id = request_id
            await self.execute_operator_broker_request(claimed)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            self.notify(
                f"Operator broker request processing failed: {exc}",
                severity="error",
            )
        finally:
            self.operator_broker_request_id = None
            self.operator_broker_worker_active = False

    async def transition_operator_broker_request(
        self,
        request_id: str,
        *,
        status: str,
        expected_statuses: tuple[str, ...],
        action_transaction_id: str | None = None,
        result: Mapping[str, Any] | None = None,
        error_code: str | None = None,
        error: str | None = None,
        lease_seconds: int = 300,
    ) -> dict[str, Any]:
        response = await self.api_client().post(
            f"/v1/operator/broker-checkpoints/{request_id}/transition",
            json={
                "executor_id": self.operator_broker_executor_id,
                "status": status,
                "expected_statuses": list(expected_statuses),
                "action_transaction_id": action_transaction_id,
                "result": dict(result or {}),
                "error_code": error_code,
                "error": error,
                "lease_seconds": lease_seconds,
            },
            headers=auth_headers(self.token),
        )
        response.raise_for_status()
        payload = response.json()
        if not isinstance(payload, dict):
            raise RuntimeError("broker transition response was not an object")
        return payload

    async def operator_broker_action(
        self,
        *,
        target_agent_id: str,
        handoff_id: str,
    ) -> dict[str, Any]:
        actions = await self.fetch_operator_handoff_actions(
            target_agent_id=target_agent_id,
            include_complete=True,
        )
        action = next(
            (
                item
                for item in actions
                if str(item.get("handoff_id") or "") == handoff_id
            ),
            None,
        )
        if action is None:
            raise RuntimeError("broker handoff no longer exposes a managed action")
        return action

    async def operator_broker_execution_preflight(
        self,
        *,
        root_operator_agent_id: str,
        handoff_id: str,
    ) -> dict[str, Any]:
        response = await self.api_client().get(
            f"/v1/operator/handoffs/{quote(handoff_id, safe='')}/execution-preflight",
            params={"operator_agent_id": root_operator_agent_id},
            headers=auth_headers(self.token),
        )
        response.raise_for_status()
        payload = response.json()
        if not isinstance(payload, dict):
            raise RuntimeError("broker execution preflight response was not an object")
        return payload

    @staticmethod
    def operator_broker_receipt_evidence(
        transaction: Mapping[str, Any] | None,
    ) -> dict[str, Any]:
        """Recover durable Git evidence after an executor/UI interruption."""

        if not isinstance(transaction, Mapping):
            return {}
        recovered: dict[str, Any] = {}
        receipts = transaction.get("receipts")
        if not isinstance(receipts, list):
            return recovered
        for receipt in receipts:
            if not isinstance(receipt, Mapping):
                continue
            evidence = receipt.get("evidence")
            if not isinstance(evidence, Mapping):
                continue
            step = str(receipt.get("step") or "")
            if step == "broker_review":
                transaction_id = str(evidence.get("transaction_id") or "").strip()
                if transaction_id:
                    recovered["broker_transaction_id"] = transaction_id
            elif step == "broker_commit":
                for key in (
                    "transaction_id",
                    "old_head",
                    "new_head",
                    "commit_subject",
                    "status",
                ):
                    value = evidence.get(key)
                    if value not in {None, ""}:
                        target_key = {
                            "transaction_id": "broker_transaction_id",
                            "status": "broker_status",
                        }.get(key, key)
                        recovered[target_key] = value
                committed_paths = evidence.get("committed_paths")
                if isinstance(committed_paths, list):
                    recovered["committed_paths"] = [
                        str(path) for path in committed_paths
                    ]
        return recovered

    @staticmethod
    def operator_broker_codex_session_id(agent: Mapping[str, Any]) -> str:
        metadata = agent.get("metadata")
        values = dict(metadata) if isinstance(metadata, Mapping) else {}
        for key in FORK_RESUME_IDENTITY_METADATA_KEYS:
            session_id = str(values.get(key) or "").strip()
            if session_id:
                return session_id
        return ""

    async def execute_operator_broker_request(
        self,
        request: Mapping[str, Any],
    ) -> None:
        """Advance stop, exact commit, and same-fork resume under local custody."""

        request_id = str(request.get("request_id") or "").strip()
        root_id = str(request.get("root_operator_agent_id") or "").strip()
        target_id = str(request.get("target_fork_agent_id") or "").strip()
        handoff_id = str(request.get("handoff_id") or "").strip()
        scope_sha256 = str(request.get("scope_sha256") or "").strip()
        expected_parent = str(request.get("expected_git_parent") or "").strip()
        expected_parents = tuple(
            str(parent or "").strip()
            for parent in (
                request.get("expected_git_parents") or (expected_parent,)
            )
        )
        expected_tree = str(request.get("expected_git_tree") or "").strip() or None
        commit_subject = str(request.get("commit_subject") or "").strip()
        exact_paths = tuple(str(item) for item in request.get("exact_paths") or ())
        if not all(
            (request_id, root_id, target_id, handoff_id, scope_sha256, expected_parent)
        ) or not commit_subject or not exact_paths:
            raise RuntimeError("broker request is incomplete")
        if not expected_parents or expected_parents[0] != expected_parent:
            raise RuntimeError("broker request Git parent order is invalid")
        if len(expected_parents) > 1 and not expected_tree:
            raise RuntimeError("multi-parent broker request lacks an expected Git tree")
        prior_result = request.get("result")
        result_evidence: dict[str, Any] = {
            **(dict(prior_result) if isinstance(prior_result, Mapping) else {}),
            "request_id": request_id,
            "root_operator_agent_id": root_id,
            "target_fork_agent_id": target_id,
            "handoff_id": handoff_id,
            "scope_sha256": scope_sha256,
            "commit_subject": commit_subject,
            "expected_git_parents": list(expected_parents),
            "expected_git_tree": expected_tree,
            "exact_paths": list(exact_paths),
            "started_at": (
                float_value(prior_result.get("started_at"))
                if isinstance(prior_result, Mapping)
                else None
            )
            or time.time(),
        }
        try:
            await self.transition_operator_broker_request(
                request_id,
                status="executing",
                expected_statuses=("claimed",),
                result={**result_evidence, "phase": "preflight"},
            )
            await self.refresh_agents()
            target_agent = self.agents.get(target_id)
            if not isinstance(target_agent, dict):
                raise RuntimeError("target fork is no longer registered")
            expected_session_id = self.operator_broker_codex_session_id(target_agent)
            if not expected_session_id:
                raise RuntimeError("target fork has no resumable Codex session identity")
            result_evidence["codex_session_id"] = expected_session_id
            resume_candidates = await asyncio.to_thread(
                self.operator_session_candidates,
                target_id,
            )
            resume_candidate = next(
                (
                    candidate
                    for candidate in resume_candidates
                    if candidate.session_id == expected_session_id
                ),
                None,
            )
            if resume_candidate is None:
                raise RuntimeError(
                    "the target fork's exact Codex session is not locally resumable"
                )

            action = await self.operator_broker_action(
                target_agent_id=target_id,
                handoff_id=handoff_id,
            )
            if str(action.get("scope_sha256") or "") != scope_sha256:
                raise RuntimeError("broker handoff scope changed after request creation")
            execution = await self.operator_broker_execution_preflight(
                root_operator_agent_id=root_id,
                handoff_id=handoff_id,
            )
            result_evidence.update(
                self.operator_broker_receipt_evidence(execution.get("transaction"))
            )
            state = str(action.get("state") or "")
            if state == "ready_stop":
                await self.transition_operator_broker_request(
                    request_id,
                    status="executing",
                    expected_statuses=("executing",),
                    result={**result_evidence, "phase": "stop"},
                )
                await self.stop_selected_operator(agent_id=target_id)
                action = await self.operator_broker_action(
                    target_agent_id=target_id,
                    handoff_id=handoff_id,
                )
                state = str(action.get("state") or "")
                if state == "ready_stop":
                    await self.refresh_agents()
                    stopped_agent = self.agents.get(target_id) or {}
                    if bool(stopped_agent.get("pbx_active", True)):
                        raise RuntimeError(
                            "guarded stop returned without deactivating the target fork"
                        )
                    await self.record_operator_handoff_action_receipt(
                        handoff_id=handoff_id,
                        operator_agent_id=root_id,
                        step="stop",
                        outcome="succeeded",
                        evidence={
                            "request_id": request_id,
                            "managed_stop_verified": True,
                        },
                    )
                    action = await self.operator_broker_action(
                        target_agent_id=target_id,
                        handoff_id=handoff_id,
                    )
                    state = str(action.get("state") or "")
                if state != "stopped_ready_broker":
                    raise RuntimeError(
                        f"guarded stop did not reach broker-ready state: {state or 'unknown'}"
                    )

            commit_result = None
            if state in {"stopped_ready_broker", "receipt_review"}:
                await self.transition_operator_broker_request(
                    request_id,
                    status="executing",
                    expected_statuses=("executing",),
                    action_transaction_id=str(action.get("transaction_id") or "") or None,
                    result={**result_evidence, "phase": "commit"},
                )
                context = self.linked_git_broker_tui_context(
                    target_id,
                    require_selection=False,
                )
                if context is None:
                    raise RuntimeError(
                        "stopped edit fork failed local broker qualification"
                    )
                receipt = await asyncio.to_thread(
                    prepare_linked_git_commit,
                    agent_id=target_id,
                    work_root=context.work_root,
                    approved_roots=context.approved_roots,
                    approved_stage_paths=exact_paths,
                    codex_home=context.codex_home,
                    authored_at=int(float(request.get("created_at") or time.time())),
                    commit_subject=commit_subject,
                    commit_parents=expected_parents,
                    expected_tree=expected_tree,
                )
                if receipt.head != expected_parent:
                    raise RuntimeError(
                        "broker Git parent changed after root request creation"
                    )
                if tuple(receipt.commit_parents or (receipt.head,)) != expected_parents:
                    raise RuntimeError(
                        "broker ordered Git parents changed after root request creation"
                    )
                if receipt.expected_tree != expected_tree:
                    raise RuntimeError(
                        "broker expected Git tree changed after root request creation"
                    )
                if tuple(receipt.approved_stage_paths) != tuple(sorted(exact_paths)):
                    raise RuntimeError("broker exact path receipt changed")
                if receipt.commit_subject != commit_subject:
                    raise RuntimeError("broker commit subject receipt changed")
                if state == "stopped_ready_broker":
                    await self.record_operator_handoff_action_receipt(
                        handoff_id=handoff_id,
                        operator_agent_id=root_id,
                        step="broker_review",
                        outcome="succeeded",
                        evidence={
                            "request_id": request_id,
                            "transaction_id": receipt.transaction_id,
                            "head": receipt.head,
                            "commit_parents": list(
                                receipt.commit_parents or (receipt.head,)
                            ),
                            "expected_tree": receipt.expected_tree,
                            "commit_subject": receipt.commit_subject,
                            "approved_stage_paths": list(receipt.approved_stage_paths),
                        },
                    )
                commit_result = await asyncio.to_thread(
                    execute_linked_git_commit,
                    receipt,
                    approved_roots=context.approved_roots,
                    journal_root=self.git_broker_state_root,
                    codex_home=context.codex_home,
                )
                await self.record_operator_handoff_action_receipt(
                    handoff_id=handoff_id,
                    operator_agent_id=root_id,
                    step="broker_commit",
                    outcome="succeeded",
                    evidence={
                        "request_id": request_id,
                        "transaction_id": commit_result.transaction_id,
                        "old_head": commit_result.old_head,
                        "new_head": commit_result.new_head,
                        "commit_parents": list(commit_result.commit_parents),
                        "expected_tree": expected_tree,
                        "commit_subject": commit_subject,
                        "committed_paths": list(commit_result.committed_paths),
                        "status": commit_result.status,
                    },
                )
                result_evidence.update(
                    {
                        "broker_transaction_id": commit_result.transaction_id,
                        "old_head": commit_result.old_head,
                        "new_head": commit_result.new_head,
                        "commit_parents": list(commit_result.commit_parents),
                        "expected_tree": expected_tree,
                        "committed_paths": list(commit_result.committed_paths),
                        "broker_status": commit_result.status,
                    }
                )
                action = await self.operator_broker_action(
                    target_agent_id=target_id,
                    handoff_id=handoff_id,
                )
                state = str(action.get("state") or "")

            if state == "committed_ready_resume":
                await self.transition_operator_broker_request(
                    request_id,
                    status="executing",
                    expected_statuses=("executing",),
                    action_transaction_id=str(action.get("transaction_id") or "") or None,
                    result={**result_evidence, "phase": "resume"},
                )
                await self.resume_selected_operator(
                    agent_id=target_id,
                    resume_candidate=resume_candidate,
                )
                action = await self.operator_broker_action(
                    target_agent_id=target_id,
                    handoff_id=handoff_id,
                )
                state = str(action.get("state") or "")
                if state == "committed_ready_resume":
                    await self.refresh_agents()
                    resumed_agent = self.agents.get(target_id) or {}
                    resumed_session_id = self.operator_broker_codex_session_id(
                        resumed_agent
                    )
                    mapping = self.tmux_runtime_mapping_by_agent.get(target_id) or {}
                    pane_id = str(
                        mapping.get("pane_id")
                        or self.tmux_agent_targets.get(target_id)
                        or ""
                    )
                    if (
                        not bool(resumed_agent.get("pbx_active", False))
                        or resumed_session_id != expected_session_id
                        or not pane_id
                    ):
                        raise RuntimeError(
                            "same-fork resume returned without a verified active runtime"
                        )
                    await self.record_operator_handoff_action_receipt(
                        handoff_id=handoff_id,
                        operator_agent_id=root_id,
                        step="resume",
                        outcome="succeeded",
                        evidence={
                            "request_id": request_id,
                            "codex_session_id": resumed_session_id,
                            "tmux_pane_id": pane_id,
                        },
                    )
                    action = await self.operator_broker_action(
                        target_agent_id=target_id,
                        handoff_id=handoff_id,
                    )
                    state = str(action.get("state") or "")
                if state != "resumed_ready_validation":
                    raise RuntimeError(
                        f"same-fork resume did not reach validation-ready state: {state or 'unknown'}"
                    )

            if state not in {"resumed_ready_validation", "complete"}:
                raise RuntimeError(
                    f"broker request stopped at unsupported action state: {state or 'unknown'}"
                )
            await self.refresh_agents()
            resumed_agent = self.agents.get(target_id) or {}
            resumed_session_id = self.operator_broker_codex_session_id(resumed_agent)
            if resumed_session_id != expected_session_id:
                raise RuntimeError("resumed fork Codex session identity changed")
            mapping = self.tmux_runtime_mapping_by_agent.get(target_id) or {}
            pane_id = str(
                mapping.get("pane_id")
                or self.tmux_agent_targets.get(target_id)
                or ""
            )
            if not pane_id:
                raise RuntimeError("resumed fork has no managed tmux pane mapping")
            work_root = str(
                (resumed_agent.get("metadata") or {}).get("work_root")
                or (resumed_agent.get("metadata") or {}).get("cwd")
                or ""
            )
            git_evidence = await asyncio.to_thread(
                self.operator_broker_git_evidence,
                work_root,
            )
            pending = await asyncio.to_thread(
                load_pending_linked_git_commits,
                self.git_broker_state_root,
            )
            transaction_id = str(result_evidence.get("broker_transaction_id") or "")
            journal_done = not any(
                item.receipt.transaction_id == transaction_id for item in pending
            )
            result_evidence.update(
                {
                    **git_evidence,
                    "journal_done": journal_done,
                    "same_fork_resumed": True,
                    "resumed_codex_session_id": resumed_session_id,
                    "resumed_tmux_pane_id": pane_id,
                    "validation_pending": state != "complete",
                    "action_state": state,
                    "duration_seconds": round(
                        time.time() - float(result_evidence["started_at"]),
                        3,
                    ),
                    "completed_at": time.time(),
                }
            )
            if not journal_done:
                raise RuntimeError("broker journal still contains pending transaction state")
            completed = await self.transition_operator_broker_request(
                request_id,
                status="succeeded",
                expected_statuses=("executing",),
                action_transaction_id=str(action.get("transaction_id") or "") or None,
                result=result_evidence,
            )
            self.notify(
                f"Root-supervised broker checkpoint completed for {target_id}; "
                "post-commit validation remains with the root Operator."
            )
            detail = self.query_one_or_none("#detail", TextArea)
            if detail is not None:
                detail.text = self.format_operator_broker_result(completed)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            failed_transaction_id: str | None = None
            try:
                failed_action = await self.operator_broker_action(
                    target_agent_id=target_id,
                    handoff_id=handoff_id,
                )
                failed_state = str(failed_action.get("state") or "")
                failed_step = {
                    "ready_stop": "stop",
                    "stopped_ready_broker": "broker_review",
                    "receipt_review": "broker_commit",
                    "committed_ready_resume": "resume",
                    "resumed_ready_validation": "validate",
                }.get(failed_state)
                if failed_step is not None:
                    failed_receipt = await self.record_operator_handoff_action_receipt(
                        handoff_id=handoff_id,
                        operator_agent_id=root_id,
                        step=failed_step,
                        outcome="failed",
                        evidence={
                            "request_id": request_id,
                            "phase": result_evidence.get("phase"),
                            "reason": str(exc),
                            "git_mutation_confirmed": bool(
                                result_evidence.get("new_head")
                            ),
                        },
                    )
                    transaction = failed_receipt.get("transaction")
                    if isinstance(transaction, Mapping):
                        failed_transaction_id = str(
                            transaction.get("transaction_id") or ""
                        ).strip() or None
            except Exception:
                # Preserve the primary broker failure. The daemon-side request
                # remains terminal even if legacy/inconsistent action state
                # cannot accept the best-effort failure receipt.
                pass
            try:
                await self.transition_operator_broker_request(
                    request_id,
                    status="failed",
                    expected_statuses=("executing",),
                    action_transaction_id=failed_transaction_id,
                    result={
                        **result_evidence,
                        "failed_at": time.time(),
                        "validation_pending": False,
                        "action_state": (
                            "blocked_reapproval_required"
                            if failed_transaction_id
                            else None
                        ),
                    },
                    error_code="OPERATOR_BROKER_EXECUTION_FAILED",
                    error=str(exc),
                )
            except Exception:
                pass
            self.notify(
                f"Root-supervised broker checkpoint failed closed for {target_id}: {exc}",
                severity="error",
            )

    @staticmethod
    def operator_broker_git_evidence(work_root: str) -> dict[str, Any]:
        if not work_root:
            raise RuntimeError("resumed fork has no work root")

        def run(*args: str) -> subprocess.CompletedProcess[str]:
            return subprocess.run(
                ["git", "-C", work_root, *args],
                check=False,
                capture_output=True,
                text=True,
                timeout=15,
            )

        head = run("rev-parse", "HEAD")
        if head.returncode != 0:
            raise RuntimeError("unable to read resumed fork Git HEAD")
        staged = run("diff", "--cached", "--quiet", "--exit-code")
        if staged.returncode not in {0, 1}:
            raise RuntimeError("unable to verify resumed fork Git index")
        return {
            "verified_head": head.stdout.strip(),
            "index_empty": staged.returncode == 0,
        }

    @staticmethod
    def format_operator_broker_result(request: Mapping[str, Any]) -> str:
        result = request.get("result")
        evidence = dict(result) if isinstance(result, Mapping) else {}
        paths = evidence.get("committed_paths") or evidence.get("exact_paths") or []
        return (
            "Root-supervised Operator checkpoint\n\n"
            f"Request: {request.get('request_id') or '-'}\n"
            f"Handoff: {request.get('handoff_id') or '-'}\n"
            f"Root: {request.get('root_operator_agent_id') or '-'}\n"
            f"Fork: {request.get('target_fork_agent_id') or '-'}\n"
            f"Session: {evidence.get('resumed_codex_session_id') or '-'}\n"
            f"Old HEAD: {evidence.get('old_head') or '-'}\n"
            f"New HEAD: {evidence.get('new_head') or evidence.get('verified_head') or '-'}\n"
            f"Subject: {request.get('commit_subject') or '-'}\n"
            f"Index empty: {bool(evidence.get('index_empty'))}\n"
            f"Journal complete: {bool(evidence.get('journal_done'))}\n"
            f"Same fork resumed: {bool(evidence.get('same_fork_resumed'))}\n"
            f"Managed pane: {evidence.get('resumed_tmux_pane_id') or '-'}\n"
            f"Validation pending: {bool(evidence.get('validation_pending'))}\n"
            "Committed paths:\n- "
            + "\n- ".join(str(item) for item in paths)
        )

    def linked_git_broker_tui_context(
        self,
        agent_id: str,
        *,
        expected_authority_sha256: str | None = None,
        require_selection: bool = True,
    ) -> LinkedGitBrokerTuiContext | None:
        """Resolve one stopped edit fork for the local-only commit broker."""

        cursor_agent_id = self.operator_id_at_cursor()
        selected_agent_id = str(self.selected_agent_id or "").strip()
        if require_selection and (
            cursor_agent_id != agent_id or selected_agent_id != agent_id
        ):
            self.notify(
                "Linked Git commit selection drifted; no broker action was taken. "
                "Press Enter on the exact stopped edit-fork row and retry.",
                severity="warning",
            )
            return None
        agent = self.agents.get(agent_id)
        if not isinstance(agent, dict) or self.agent_type(agent) != OPERATOR_AGENT_TYPE:
            self.notify("The broker target is no longer an operator.", severity="warning")
            return None
        metadata = agent.get("metadata") if isinstance(agent.get("metadata"), dict) else {}
        if (
            self.operator_role(agent) != OPERATOR_ROLE_FORK
            or str(metadata.get("fork_purpose") or "").strip() != DEFAULT_OPERATOR_FORK_PURPOSE
            or str(metadata.get("access_mode") or "").strip() != DEFAULT_OPERATOR_FORK_ACCESS_MODE
        ):
            self.notify(
                "The local commit broker is limited to edit-capable operator forks.",
                severity="warning",
            )
            return None
        if str(agent.get("status") or "").strip().casefold() != "canceled":
            self.notify(
                "The local commit broker requires the canonical canceled status "
                "recorded by the guarded TUI stop action.",
                severity="warning",
            )
            return None
        if bool(agent.get("pbx_active", True)):
            self.notify(
                "Stop the exact edit fork before opening the local commit broker.",
                severity="warning",
            )
            return None
        if (
            agent_id in self.tmux_agent_targets
            or agent_id in self.tmux_runtime_mapping_by_agent
            or self.embedded_terminal_agent_id == agent_id
            or self.embedded_terminal_transition_agent_id == agent_id
        ):
            self.notify(
                "The stopped edit fork still has terminal/runtime state. Reconcile "
                "the stopped lifecycle record before opening the broker.",
                severity="warning",
            )
            return None
        liveness = self.tmux_liveness_by_agent.get(agent_id)
        if liveness is not None and (
            not isinstance(liveness, TmuxLiveness) or liveness.state != "stale"
        ):
            self.notify(
                "The edit fork has non-stale tmux liveness evidence; no broker "
                "action was taken.",
                severity="warning",
            )
            return None
        work_root = str(metadata.get("work_root") or metadata.get("cwd") or "").strip()
        if not work_root:
            self.notify("The edit fork has no canonical work root.", severity="error")
            return None
        roots = default_managed_project_roots(cwd=Path(work_root))
        try:
            codex_home = self.codex_home_dir().expanduser().resolve(strict=True)
            plan = qualify_linked_worktree_git_admin(
                work_root,
                approved_roots=roots,
                fork_purpose=DEFAULT_OPERATOR_FORK_PURPOSE,
                access_mode=DEFAULT_OPERATOR_FORK_ACCESS_MODE,
                codex_home=codex_home,
            )
        except (LinkedWorktreeQualificationError, OSError) as exc:
            self.notify(
                f"Linked Git broker qualification failed closed: {exc}",
                severity="error",
            )
            return None
        if plan is None:
            self.notify(
                "This edit fork is not a qualified linked Git worktree.",
                severity="warning",
            )
            return None
        plan_public = plan.public_dict()
        if (
            plan.write_strategy != "tui_root_commit_broker"
            or plan.config_overrides()
            or len(plan.writable_paths) != 4
            or plan_public.get("active_write_grants")
            or plan_public.get("writable_paths")
        ):
            self.notify(
                "This fork does not require the split-profile TUI broker, or its "
                "recomputed plan exposes runtime grants; use its qualified direct "
                "Git path instead.",
                severity="warning",
            )
            return None
        linked = metadata.get("linked_git_admin")
        if linked is not None and not isinstance(linked, dict):
            self.notify(
                "Stored linked-Git metadata is malformed. Refresh/reconcile the "
                "stopped fork metadata before retrying; no restart is required.",
                severity="error",
            )
            return None
        legacy_metadata = False
        if isinstance(linked, dict):
            legacy_keys = {
                "kind",
                "worktree_root",
                "git_dir",
                "common_dir",
                "branch_ref",
                "base_permission_profile",
                "permission_profile",
                "writable_paths",
            }
            legacy_metadata = set(linked) == legacy_keys and all(
                linked.get(key) == plan_public.get(key)
                for key in legacy_keys - {"writable_paths"}
            ) and linked.get("writable_paths") == plan_public.get(
                "qualified_git_admin_paths"
            )
            current_metadata = linked == plan_public
            if not legacy_metadata and not current_metadata:
                self.notify(
                    "Stored linked-Git metadata is partial, malformed, or conflicts "
                    "with the current topology. Only the exact current plan or the "
                    "exact pre-broker four-path legacy record is accepted. Refresh/"
                    "reconcile the stopped fork metadata, then retry without restarting it.",
                    severity="error",
                )
                return None
        authority_payload = {
            "agent_id": agent_id,
            "pbx_active": bool(agent.get("pbx_active", True)),
            "status": str(agent.get("status") or ""),
            "operator_role": self.operator_role(agent),
            "fork_purpose": str(metadata.get("fork_purpose") or ""),
            "access_mode": str(metadata.get("access_mode") or ""),
            "work_root": work_root,
            "recomputed_linked_git_admin": plan_public,
            "legacy_inert_launch_metadata": legacy_metadata,
            "approved_roots": [str(path) for path in roots],
            "codex_home": str(codex_home),
            # Both an absent sample and an explicit stale sample are accepted by
            # the stopped-fork gate above.  Background liveness refreshes may
            # legitimately move between those equivalent safe representations
            # while a root operator reviews the receipt.  Bind the authority to
            # the accepted stopped posture, while every review/execute pass still
            # re-runs the gate and rejects captured, unknown, or other live state.
            "tmux_liveness": "stale_or_absent",
        }
        authority_sha256 = hashlib.sha256(
            json.dumps(
                authority_payload,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
        if (
            expected_authority_sha256 is not None
            and authority_sha256 != expected_authority_sha256
        ):
            self.notify(
                "Linked Git commit approval context drifted; no broker action was taken.",
                severity="warning",
            )
            return None
        return LinkedGitBrokerTuiContext(
            agent_id=agent_id,
            work_root=work_root,
            approved_roots=roots,
            codex_home=codex_home,
            authority_sha256=authority_sha256,
            plan_public=plan_public,
        )

    @staticmethod
    def linked_git_broker_receipt_matches_context(
        receipt: LinkedGitCommitReceipt,
        context: LinkedGitBrokerTuiContext,
    ) -> bool:
        plan = context.plan_public
        return (
            receipt.agent_id == context.agent_id
            and receipt.worktree_root == context.work_root
            and receipt.approved_roots
            == tuple(str(path) for path in context.approved_roots)
            and receipt.codex_home == str(context.codex_home)
            and receipt.git_dir == str(plan.get("git_dir") or "")
            and receipt.common_dir == str(plan.get("common_dir") or "")
            and receipt.object_dir == str(plan.get("object_dir") or "")
            and receipt.branch_ref == str(plan.get("branch_ref") or "")
            and receipt.write_strategy == str(plan.get("write_strategy") or "")
            and receipt.grant_scope == str(plan.get("grant_scope") or "")
            and receipt.base_permission_profile
            == str(plan.get("base_permission_profile") or "")
            and receipt.permission_profile
            == str(plan.get("permission_profile") or "")
            and receipt.qualified_git_admin_paths
            == tuple(plan.get("qualified_git_admin_paths") or ())
        )

    def pending_linked_git_broker_transaction(
        self,
        context: LinkedGitBrokerTuiContext,
        *,
        require_pending: bool,
    ) -> tuple[PendingLinkedGitCommit | None, bool]:
        """Return one exact local pending transaction or fail closed."""

        try:
            pending = load_pending_linked_git_commits(self.git_broker_state_root)
        except (LinkedGitBrokerError, OSError) as exc:
            self.notify(f"Unable to inspect broker recovery state: {exc}", severity="error")
            return None, False
        if not pending:
            if require_pending:
                self.notify(
                    "No pending linked-Git broker transaction exists for recovery.",
                    severity="warning",
                )
            return None, True
        if len(pending) != 1:
            self.notify(
                "Broker recovery is ambiguous: the private journal contains "
                f"{len(pending)} pending transactions. No recovery was attempted.",
                severity="error",
            )
            return None, False
        candidate = pending[0]
        if not self.linked_git_broker_receipt_matches_context(
            candidate.receipt,
            context,
        ):
            self.notify(
                "The pending broker transaction is foreign to the exact selected "
                "stopped fork or its recomputed authority. No recovery was attempted.",
                severity="error",
            )
            return None, False
        return candidate, True

    async def review_linked_git_broker_commit(
        self,
        context: LinkedGitBrokerTuiContext,
        approved_stage_paths: tuple[str, ...],
    ) -> None:
        if not approved_stage_paths:
            self.notify(
                "Explicit stage paths are required; add-all is disabled.",
                severity="warning",
            )
            return
        current = self.linked_git_broker_tui_context(
            context.agent_id,
            expected_authority_sha256=context.authority_sha256,
            require_selection=False,
        )
        if current is None:
            return
        try:
            receipt = await asyncio.to_thread(
                prepare_linked_git_commit,
                agent_id=context.agent_id,
                work_root=context.work_root,
                approved_roots=context.approved_roots,
                approved_stage_paths=approved_stage_paths,
                codex_home=context.codex_home,
            )
        except (LinkedGitBrokerError, OSError) as exc:
            self.notify(f"Linked Git commit review failed: {exc}", severity="error")
            return
        current = self.linked_git_broker_tui_context(
            context.agent_id,
            expected_authority_sha256=context.authority_sha256,
            require_selection=False,
        )
        if current is None:
            return
        if not self.linked_git_broker_receipt_matches_context(receipt, current):
            self.notify(
                "Prepared broker receipt does not match the recomputed stopped-fork "
                "authority; no confirmation was opened.",
                severity="error",
            )
            return
        try:
            review_artifact = validate_linked_git_commit_review(receipt)
        except LinkedGitBrokerError as exc:
            self.notify(
                f"Prepared broker Git review is invalid: {exc}",
                severity="error",
            )
            return
        await self.maybe_record_ready_action_for_target(
            context.agent_id,
            step="broker_review",
            outcome="succeeded",
            evidence={
                "transaction_id": receipt.transaction_id,
                "head": receipt.head,
                "commit_subject": receipt.commit_subject,
                "approved_stage_paths": list(receipt.approved_stage_paths),
                "git_review_sha256": review_artifact.sha256,
            },
        )
        self.push_screen(
            LinkedGitCommitConfirmScreen(context=context, receipt=receipt)
        )

    async def execute_linked_git_broker_commit(
        self,
        context: LinkedGitBrokerTuiContext,
        receipt: LinkedGitCommitReceipt,
        confirmation: str,
    ) -> None:
        expected_confirmation = (
            f"COMMIT {context.agent_id} {receipt.transaction_id[:12]}"
        )
        if confirmation != expected_confirmation:
            self.notify("Exact root confirmation did not match.", severity="warning")
            return
        if not receipt.approved_stage_paths:
            self.notify("The broker receipt has no explicit stage subset.", severity="error")
            return
        current = self.linked_git_broker_tui_context(
            context.agent_id,
            expected_authority_sha256=context.authority_sha256,
            require_selection=False,
        )
        if current is None:
            return
        if not self.linked_git_broker_receipt_matches_context(receipt, current):
            self.notify(
                "Broker receipt no longer matches the recomputed stopped-fork "
                "authority; no commit was attempted.",
                severity="error",
            )
            return
        try:
            result = await asyncio.to_thread(
                execute_linked_git_commit,
                receipt,
                approved_roots=current.approved_roots,
                journal_root=self.git_broker_state_root,
                codex_home=current.codex_home,
            )
        except (LinkedGitBrokerError, OSError) as exc:
            self.notify(f"Linked Git commit failed closed: {exc}", severity="error")
            return
        await self.maybe_record_ready_action_for_target(
            context.agent_id,
            step="broker_commit",
            outcome="succeeded",
            evidence={
                "transaction_id": result.transaction_id,
                "old_head": result.old_head,
                "new_head": result.new_head,
                "committed_paths": list(result.committed_paths),
                "status": result.status,
            },
        )
        self.notify(
            f"Committed {len(result.committed_paths)} approved path(s) for "
            f"{context.agent_id}: {result.new_head[:12]}."
        )
        detail = self.query_one_or_none("#detail", TextArea)
        if detail is not None:
            detail.text = (
                "Linked Git broker commit complete\n\n"
                f"Agent: {context.agent_id}\n"
                f"Transaction: {result.transaction_id}\n"
                f"Old HEAD: {result.old_head}\n"
                f"New HEAD: {result.new_head}\n"
                "Committed paths:\n- "
                + "\n- ".join(result.committed_paths)
                + "\n\nThe edit fork remains stopped."
            )

    async def recover_linked_git_broker_commit(
        self,
        context: LinkedGitBrokerTuiContext,
        pending: PendingLinkedGitCommit,
        confirmation: str,
    ) -> None:
        receipt = pending.receipt
        expected_confirmation = (
            f"RECOVER {context.agent_id} {receipt.transaction_id[:12]}"
        )
        if confirmation != expected_confirmation:
            self.notify("Exact recovery confirmation did not match.", severity="warning")
            return
        current = self.linked_git_broker_tui_context(
            context.agent_id,
            expected_authority_sha256=context.authority_sha256,
            require_selection=False,
        )
        if current is None:
            return
        current_pending, safe = self.pending_linked_git_broker_transaction(
            current,
            require_pending=True,
        )
        if (
            not safe
            or current_pending is None
            or current_pending.receipt != receipt
            or current_pending.phase != pending.phase
        ):
            self.notify(
                "Broker recovery receipt or phase drifted; no recovery was attempted.",
                severity="error",
            )
            return
        try:
            result = await asyncio.to_thread(
                recover_linked_git_commit,
                receipt,
                approved_roots=current.approved_roots,
                journal_root=self.git_broker_state_root,
                codex_home=current.codex_home,
            )
        except LinkedGitBrokerRestored as exc:
            try:
                remaining = load_pending_linked_git_commits(
                    self.git_broker_state_root
                )
            except (LinkedGitBrokerError, OSError) as state_exc:
                self.notify(
                    "Broker restored the original state, but journal verification "
                    f"failed closed: {state_exc}",
                    severity="error",
                )
                return
            if remaining:
                self.notify(
                    "Broker reported an original-state restore, but pending journal "
                    "state remains; manual review is required.",
                    severity="error",
                )
                return
            self.notify(
                f"Restored the exact original linked-Git state for {context.agent_id}."
            )
            await self.maybe_record_ready_action_for_target(
                context.agent_id,
                step="broker_commit",
                outcome="restored",
                evidence={"transaction_id": receipt.transaction_id},
            )
            detail = self.query_one_or_none("#detail", TextArea)
            if detail is not None:
                detail.text = (
                    "Linked Git broker recovery restored the original state\n\n"
                    f"Agent: {context.agent_id}\n"
                    f"Transaction: {receipt.transaction_id}\n"
                    f"Original HEAD: {receipt.head}\n"
                    f"Approved paths were not committed: "
                    f"{', '.join(receipt.approved_stage_paths)}\n\n"
                    f"Recovery result: {exc}\n"
                    "No pending transaction remains. The edit fork remains stopped."
                )
            return
        except (LinkedGitBrokerError, OSError) as exc:
            self.notify(f"Linked Git recovery failed closed: {exc}", severity="error")
            return
        if result is None:
            self.notify(
                "The selected broker transaction no longer has recoverable state.",
                severity="warning",
            )
            return
        self.notify(
            f"Recovered broker transaction for {context.agent_id}: "
            f"{result.old_head[:12]} -> {result.new_head[:12]}."
        )
        detail = self.query_one_or_none("#detail", TextArea)
        if detail is not None:
            detail.text = (
                "Linked Git broker recovery complete\n\n"
                f"Agent: {context.agent_id}\n"
                f"Transaction: {result.transaction_id}\n"
                f"Old HEAD: {result.old_head}\n"
                f"New HEAD: {result.new_head}\n"
                "Committed paths:\n- "
                + "\n- ".join(result.committed_paths)
                + "\n\nThe edit fork remains stopped."
            )

    def tui_owned_operator_pane_id(self, agent_id: str) -> str | None:
        if not self.is_operator_agent_id(agent_id):
            return None
        agent = self.agents.get(agent_id, {})
        metadata = agent.get("metadata") if isinstance(agent.get("metadata"), dict) else {}
        if metadata.get("launched_by") != "agent-pbx-tui":
            return None
        return self.tmux_agent_targets.get(agent_id)

    def clear_operator_tmux_state(self, agent_id: str) -> None:
        self.tmux_agent_targets.pop(agent_id, None)
        self.clear_cached_tmux_runtime_mapping(agent_id)
        self.tmux_direct_agent_modes.pop(agent_id, None)
        self.tmux_manual_override_agent_ids.discard(agent_id)
        self.tmux_detached_agent_ids.discard(agent_id)
        self.tmux_liveness_by_agent.pop(agent_id, None)
        self.tmux_plan_selector_agent_ids.discard(agent_id)
        self.tmux_plan_selector_pane_by_agent.pop(agent_id, None)
        self.tmux_plan_selector_indices_by_agent.pop(agent_id, None)

    async def kill_tui_owned_operator_pane(
        self,
        agent_id: str,
        *,
        lifecycle_target: ManagedTmuxLifecycleTarget | None = None,
    ) -> bool:
        pane_id = (
            lifecycle_target.pane_id
            if lifecycle_target is not None
            else self.tui_owned_operator_pane_id(agent_id)
        )
        if not pane_id:
            return True
        lifecycle_target = lifecycle_target or await self.managed_tmux_lifecycle_target(
            agent_id,
            expected_pane_id=pane_id,
            action="stop",
        )
        if lifecycle_target is None:
            return False
        try:
            await asyncio.to_thread(
                tmux_support.kill_pane,
                lifecycle_target.pane_id,
                **lifecycle_target.runtime_kwargs,
            )
        except Exception as exc:
            self.notify(
                f"Unable to kill qualified operator pane {lifecycle_target.pane_id}: "
                f"{exc}",
                severity="error",
            )
            return False
        self.clear_operator_tmux_state(agent_id)
        self.save_settings()
        return True

    async def prepare_managed_operator_stop(
        self,
        agent_id: str,
        mapping: Mapping[str, Any],
    ) -> dict[str, Any] | None:
        payload = {
            "client_id": self.tmux_terminal_client_id,
            "expected_server_id": str(mapping.get("server_id") or ""),
            "expected_socket_path": str(mapping.get("socket_path") or ""),
            "expected_session_name": str(mapping.get("session_name") or ""),
            "expected_window_id": str(mapping.get("window_id") or ""),
            "expected_pane_id": str(mapping.get("pane_id") or ""),
            "expected_pane_pid": mapping.get("pane_pid"),
            "expected_process_start_ticks": mapping.get("process_start_ticks"),
            "expected_codex_session_id": mapping.get("codex_session_id"),
            "metadata": {"source": "agent-pbx-tui"},
        }
        try:
            response = await self.api_client().post(
                f"/v2/lifecycle/{quote(agent_id, safe='')}/managed-stop/prepare",
                json=payload,
                headers=auth_headers(self.token),
            )
            response.raise_for_status()
            prepared = response.json()
        except Exception as exc:
            self.notify(
                f"Unable to prepare an exact managed stop for {agent_id}: {exc}",
                severity="error",
            )
            return None
        return prepared if isinstance(prepared, dict) else None

    async def finalize_managed_operator_stop(
        self,
        agent_id: str,
        transaction_id: str,
    ) -> dict[str, Any] | None:
        last_error: Exception | None = None
        for attempt in range(8):
            try:
                response = await self.api_client().post(
                    f"/v2/lifecycle/{quote(agent_id, safe='')}/managed-stop/finalize",
                    json={
                        "transaction_id": transaction_id,
                        "metadata": {"source": "agent-pbx-tui"},
                    },
                    headers=auth_headers(self.token),
                )
                response.raise_for_status()
                finalized = response.json()
                return finalized if isinstance(finalized, dict) else None
            except Exception as exc:
                last_error = exc
                if attempt < 7:
                    await asyncio.sleep(0.25)
        self.notify(
            f"The pane stop for {agent_id} could not be finalized: {last_error}. "
            f"Retry the stop transaction {transaction_id}; do not restart the fork.",
            severity="error",
        )
        return None

    async def release_embedded_terminal_for_managed_stop(
        self,
        agent_id: str,
        mapping: Mapping[str, Any],
    ) -> dict[str, Any] | None:
        owner = str(mapping.get("writer_client_id") or "").strip()
        lease_active = bool(mapping.get("writer_lease_active"))
        mapped_target = f"{mapping.get('server_id')}:{mapping.get('pane_id')}"
        if lease_active and owner != self.tmux_terminal_client_id:
            self.notify(
                f"Refused to stop {agent_id}: runtime writer lease belongs to "
                f"{owner or 'an unknown client'}.",
                severity="error",
            )
            return None

        if self.embedded_terminal_agent_id == agent_id:
            surface = self.query_one_or_none(
                "#pbx-terminal-surface", PbxTerminalSurface
            )
            if (
                surface is None
                or not surface.attached
                or self.embedded_terminal_target != mapped_target
                or surface.target != mapped_target
            ):
                self.notify(
                    f"Refused to stop {agent_id}: its embedded writer target no "
                    "longer matches the authoritative runtime mapping.",
                    severity="error",
                )
                return None
            await self.detach_embedded_tmux_terminal(release_lease=True)
        elif lease_active:
            self.notify(
                f"Refused to stop {agent_id}: this TUI owns a writer lease but "
                "has no matching attached terminal to release.",
                severity="error",
            )
            return None

        refreshed = await self.fetch_tmux_runtime_mapping_for_stop(agent_id)
        if refreshed is None:
            self.notify(
                f"Refused to stop {agent_id}: its authoritative runtime mapping "
                "disappeared while releasing the writer.",
                severity="error",
            )
            return None
        if refreshed.get("writer_lease_active"):
            self.notify(
                f"Refused to stop {agent_id}: its runtime writer lease is still active.",
                severity="error",
            )
            return None
        return refreshed

    async def restart_selected_operator(
        self,
        *,
        agent_id: str | None = None,
    ) -> None:
        agent_id = agent_id or self.selected_operator_agent_id()
        if not agent_id:
            return
        await self.restart_tmux_codex_session(agent_id)

    async def resume_selected_operator(
        self,
        *,
        agent_id: str | None = None,
        resume_candidate: OperatorSessionCandidate | None = None,
    ) -> None:
        agent_id = agent_id or self.selected_operator_agent_id()
        if not agent_id:
            return
        if not self.is_operator_agent_id(agent_id):
            self.notify(f"{agent_id} is not an operator.", severity="warning")
            return
        if not self.tmux_features_available:
            self.notify(
                "Tmux is required to resume an operator from the TUI.",
                severity="warning",
            )
            return
        candidates = (
            [resume_candidate]
            if resume_candidate is not None
            else await asyncio.to_thread(self.operator_session_candidates, agent_id)
        )
        target = resume_candidate or self.operator_resume_target(agent_id, candidates)
        if target is None:
            self.notify(f"No resumable Codex session found for {agent_id}.", severity="warning")
            await self.show_selected_operator_history(agent_id=agent_id)
            return
        if not self.operator_session_can_resume(agent_id, target.session_id):
            self.notify(
                f"Refused to resume {agent_id} from its source Codex session. "
                "Restart this fork to create or continue a distinct Codex fork instead.",
                severity="warning",
            )
            return
        pane_id = self.tmux_agent_targets.get(agent_id)
        if pane_id and self.tui_owned_operator_pane_id(agent_id) != pane_id:
            self.notify(
                f"{agent_id} has a non-TUI-owned tmux pane; detach it before resume.",
                severity="warning",
            )
            return
        lifecycle_target: ManagedTmuxLifecycleTarget | None = None
        if pane_id:
            lifecycle_target = await self.managed_tmux_lifecycle_target(
                agent_id,
                expected_pane_id=pane_id,
                action="resume",
            )
            if lifecycle_target is None:
                return
        agent = self.agents.get(agent_id) or {}
        if pane_id and self.operator_role(agent) == OPERATOR_ROLE_ROOT:
            if lifecycle_target is not None:
                restarted = await self.relaunch_operator_root_codex(
                    agent_id,
                    lifecycle_target.pane,
                    resume_candidate=target,
                    lifecycle_target=lifecycle_target,
                )
                if restarted:
                    await self.refresh_agents()
                    await self.open_latest_for_agent(agent_id)
                return
        session_name = self.operator_tmux_session_name()
        if lifecycle_target is not None:
            session_name = lifecycle_target.session_name
            runtime_kwargs = lifecycle_target.runtime_kwargs
        else:
            session_name, runtime_kwargs = await self.configured_runtime_launch_target(
                agent_id,
                fallback_session_name=session_name,
            )
            if not runtime_kwargs.get("socket_path"):
                self.notify(
                    f"Refused to resume {agent_id}: no fully qualified managed tmux "
                    "launch target is available. No pane was created.",
                    severity="error",
                )
                return
        if not await self.ensure_codex_resume_session_available(
            agent_id,
            target.session_id,
            replacing_pane_id=pane_id,
            **runtime_kwargs,
        ):
            return
        if not await self.ensure_operator_auth_ready():
            return
        metadata = self.operator_metadata_for(agent_id)
        launch_preset = codex_model_preset_from_metadata(metadata)
        cwd = str(metadata.get("cwd") or self.operator_cwd()).strip() or os.getcwd()
        try:
            fork_identity = self.operator_fork_resume_identity(agent_id, cwd=cwd)
        except ValueError as exc:
            self.notify(str(exc), severity="error")
            return
        if fork_identity is not None:
            cwd = fork_identity["work_root"]
        fork_purpose = (
            fork_identity["fork_purpose"]
            if fork_identity is not None
            else ""
        )
        access_mode = (
            fork_identity["access_mode"]
            if fork_identity is not None
            else ""
        )
        if launch_preset is None:
            launch_preset = self.codex_model_policy.profile_for_role(
                "operator"
                if fork_identity is None
                else (
                    "review_fork"
                    if fork_purpose == REVIEW_OPERATOR_FORK_PURPOSE
                    else "edit_fork"
                )
            )
        git_admin_plan = None
        if fork_identity is not None:
            try:
                git_admin_plan = await self.linked_edit_fork_git_admin_plan(
                    cwd,
                    fork_purpose=fork_purpose,
                    access_mode=access_mode,
                )
            except LinkedWorktreeQualificationError as exc:
                self.notify(
                    f"Refused to resume {agent_id}: linked-worktree Git "
                    f"administration did not qualify. {exc}",
                    severity="error",
                )
                return
        codex_command = self.operator_codex_command()
        mcp_url = agent_pbx_mcp_url(self.server)
        try:
            await self.configure_operator_codex_mcp(
                codex_command=codex_command,
                mcp_url=mcp_url,
            )
        except Exception as exc:
            self.notify(f"Unable to configure Codex MCP: {exc}", severity="error")
            return
        history = self.operator_session_history_metadata(
            agent_id,
            include=[*candidates[:3], target],
        )
        try:
            workerbee_gateway_binding = await self.prepare_workerbee_gateway_launch(
                agent_id=agent_id,
                project=str(agent.get("project") or "agent-pbx-operator"),
                codex_session_id=target.session_id,
                profile=self.workerbee_profile_for_agent(agent),
                source_root=cwd,
            )
        except RuntimeError as exc:
            self.notify(str(exc), severity="error")
            return
        if not await self.kill_tui_owned_operator_pane(
            agent_id,
            lifecycle_target=lifecycle_target,
        ):
            return
        if fork_identity is not None and fork_purpose == REVIEW_OPERATOR_FORK_PURPOSE:
            raw_review_servers = metadata.get("review_mcp_approval_servers", [])
            review_servers = (
                tuple(str(item) for item in raw_review_servers if str(item).strip())
                if isinstance(raw_review_servers, (list, tuple))
                else ()
            )
            if not review_servers:
                review_servers = review_operator_mcp_approval_server_names()
            launch_config_overrides = review_operator_config_overrides(
                review_servers,
                mcp_url=mcp_url,
                codex_home=self.codex_home_dir(),
                work_root=cwd,
                terminal_mode=self.codex_terminal_mode,
                workerbee_gateway_binding=workerbee_gateway_binding,
            )
            sandbox = "workspace-write"
        else:
            launch_config_overrides = operator_agent_config_overrides(
                mcp_url=mcp_url,
                codex_home=self.codex_home_dir(),
                work_root=cwd,
                include_campaign_lifecycle=True,
                terminal_mode=self.codex_terminal_mode,
                workerbee_gateway_binding=workerbee_gateway_binding,
                authority_metadata=metadata,
                linked_git_admin_plan=git_admin_plan,
            )
            sandbox = operator_authority_sandbox(metadata)
        launch_config_overrides.extend(
            codex_model_preset_config_overrides(launch_preset)
        )
        launch_config_overrides.extend(
            self.linked_edit_fork_config_overrides(git_admin_plan, metadata)
        )
        command = self.operator_resume_command(
            codex_command,
            target.session_id,
            cd=cwd,
            sandbox=sandbox,
            config_overrides=launch_config_overrides,
        )
        env_kwargs: dict[str, Any] = {}
        if fork_identity is not None:
            env_kwargs = {
                "operator_role": OPERATOR_ROLE_FORK,
                **fork_identity,
            }
        env = self.operator_launch_env(
            agent_id=agent_id,
            cwd=cwd,
            mcp_url=mcp_url,
            model_preset=launch_preset,
            workerbee_gateway_binding=workerbee_gateway_binding,
            **env_kwargs,
        )
        env["AGENT_PBX_RESUME_CODEX_SESSION_ID"] = target.session_id
        try:
            resumed_pane_id = await asyncio.to_thread(
                tmux_support.launch_pane,
                session_name=session_name,
                window_name=agent_id,
                command=command,
                cwd=cwd,
                env=env,
                width=self.detached_tmux_width,
                height=self.detached_tmux_height,
                **runtime_kwargs,
            )
        except Exception as exc:
            self.notify(f"Unable to launch resumed operator pane: {exc}", severity="error")
            return
        if CODEX_RESTART_STABILIZE_SECONDS > 0:
            await asyncio.sleep(CODEX_RESTART_STABILIZE_SECONDS)
        try:
            pane_alive = await asyncio.to_thread(
                tmux_support.pane_is_live,
                resumed_pane_id,
                **runtime_kwargs,
            )
        except Exception as exc:
            self.notify(
                f"Unable to verify resumed operator pane {resumed_pane_id}: {exc}",
                severity="error",
            )
            return
        if not pane_alive:
            self.notify(
                f"Resumed operator pane {resumed_pane_id} exited before Codex stabilized.",
                severity="error",
            )
            return
        self.tmux_agent_targets[agent_id] = resumed_pane_id
        self.tmux_manual_override_agent_ids.add(agent_id)
        self.tmux_detached_agent_ids.discard(agent_id)
        self.tmux_direct_agent_modes[agent_id] = True
        if await self.tmux_pane_has_codex_session_lease_conflict(
            resumed_pane_id,
            **runtime_kwargs,
        ):
            self.notify(
                f"Codex opened a conversation-lease dialog for {agent_id}. The pane "
                "was left unregistered and without a bootstrap paste; close or wait "
                "for the existing owner and use r, or use Codex's explicit f fork "
                "option to branch intentionally.",
                severity="warning",
            )
            self.save_settings()
            return
        try:
            if fork_identity is None:
                await self.register_operator_root(
                    agent_id,
                    cwd=cwd,
                    codex_command=codex_command,
                    mcp_url=mcp_url,
                    session_name=session_name,
                    tmux_pane_id=resumed_pane_id,
                    resumed_codex_session_id=target.session_id,
                    operator_session_history=history,
                    model_preset=launch_preset,
                    workerbee_gateway_binding=workerbee_gateway_binding,
                )
            else:
                fork_metadata = {
                    **metadata,
                    **fork_identity,
                    "agent_type": OPERATOR_AGENT_TYPE,
                    "operator_role": OPERATOR_ROLE_FORK,
                    "reporting_agent_id": agent_id,
                    "cwd": cwd,
                    "tmux_session": session_name,
                    "tmux_pane_id": resumed_pane_id,
                    "fork_codex_session_id": target.session_id,
                    "last_resume_codex_session_id": target.session_id,
                    "operator_session_history": history,
                    **launch_preset.metadata(),
                    **self.workerbee_gateway_metadata(workerbee_gateway_binding),
                }
                if git_admin_plan is not None:
                    fork_metadata["linked_git_admin"] = git_admin_plan.public_dict()
                else:
                    fork_metadata.pop("linked_git_admin", None)
                fork = await self.record_operator_fork(
                    logical_operator_id=fork_identity["logical_operator_id"],
                    source_caller_agent_id=fork_identity["source_caller_agent_id"],
                    fork_agent_id=agent_id,
                    tmux_pane_id=resumed_pane_id,
                    metadata=fork_metadata,
                    fork_track_id=fork_identity["fork_track_id"],
                    fork_purpose=fork_purpose,
                    access_mode=access_mode,
                    source_cwd=fork_identity["source_cwd"],
                    work_root=cwd,
                    fork_codex_session_id=target.session_id,
                )
                if isinstance(fork, dict):
                    self.agents[agent_id] = self.operator_fork_record_agent(fork)
        except Exception as exc:
            registration_kind = "fork" if fork_identity is not None else "root"
            self.notify(
                f"Resumed pane launched, but PBX {registration_kind} registration "
                f"failed: {exc}",
                severity="warning",
            )
        try:
            await self.register_launched_tmux_runtime(
                agent_id,
                resumed_pane_id,
                runtime_kwargs=runtime_kwargs,
                mapping_source="operator_resume",
                codex_session_id=target.session_id,
            )
        except Exception as exc:
            self.notify(
                f"Resumed {agent_id}, but exact runtime registration failed: {exc}",
                severity="warning",
            )
        await self.mark_operator_authority_activated(agent_id)
        await asyncio.sleep(1.0)
        bootstrap_kwargs: dict[str, Any] = fork_identity or {}
        try:
            await asyncio.to_thread(
                tmux_support.send_text,
                resumed_pane_id,
                self.operator_bootstrap_prompt(
                    agent_id,
                    cwd,
                    **bootstrap_kwargs,
                ),
                **runtime_kwargs,
            )
            sent = True
        except Exception:
            sent = False
        if not sent:
            self.notify(
                f"Resumed {agent_id}, but bootstrap paste failed.",
                severity="warning",
            )
        else:
            self.notify(f"Resumed {agent_id} from {target.session_id}.")
        self.save_settings()
        await self.refresh_agents()
        await self.maybe_record_ready_action_for_target(
            agent_id,
            step="resume",
            outcome="succeeded",
            evidence={
                "codex_session_id": target.session_id,
                "tmux_pane_id": resumed_pane_id,
            },
        )
        await self.open_latest_for_agent(agent_id)

    async def stop_selected_operator(
        self,
        *,
        agent_id: str | None = None,
    ) -> None:
        agent_id = agent_id or self.selected_operator_agent_id()
        if not agent_id:
            return
        agent = self.agents.get(agent_id) or {}
        metadata = agent.get("metadata") if isinstance(agent.get("metadata"), dict) else {}
        if metadata.get("launched_by") != "agent-pbx-tui":
            self.notify(
                f"Refused to stop {agent_id}: it is not a TUI-managed Operator runtime.",
                severity="error",
            )
            return
        if agent_id in self.tmux_stop_in_progress_agent_ids:
            self.notify(f"A managed stop is already in progress for {agent_id}.")
            return
        self.tmux_stop_in_progress_agent_ids.add(agent_id)
        transaction_id = ""
        try:
            mapping = await self.fetch_tmux_runtime_mapping_for_stop(agent_id)
            if mapping is None:
                self.notify(
                    f"Refused to stop {agent_id}: no authoritative managed runtime "
                    "mapping is available.",
                    severity="error",
                )
                return
            mapping = await self.release_embedded_terminal_for_managed_stop(
                agent_id,
                mapping,
            )
            if mapping is None:
                return
            prepared = await self.prepare_managed_operator_stop(agent_id, mapping)
            if prepared is None:
                return
            transaction_id = str(prepared.get("transaction_id") or "").strip()
            prepared_mapping = (
                prepared.get("mapping")
                if isinstance(prepared.get("mapping"), dict)
                else None
            )
            if not transaction_id or prepared_mapping is None:
                self.notify(
                    f"Refused to stop {agent_id}: managed stop preparation was incomplete.",
                    severity="error",
                )
                return
            if bool(prepared.get("requires_pane_stop")):
                pane_id = str(prepared_mapping.get("pane_id") or "").strip()
                lifecycle_target = await self.managed_tmux_lifecycle_target(
                    agent_id,
                    expected_pane_id=pane_id,
                    action="stop",
                )
                if lifecycle_target is None:
                    self.notify(
                        f"Managed stop {transaction_id} remains prepared; retry after "
                        "the runtime identity can be verified.",
                        severity="warning",
                    )
                    return
                if not await self.kill_tui_owned_operator_pane(
                    agent_id,
                    lifecycle_target=lifecycle_target,
                ):
                    self.notify(
                        f"Managed stop {transaction_id} remains prepared; no durable "
                        "Agent or fork record was changed.",
                        severity="warning",
                    )
                    return
            finalized = await self.finalize_managed_operator_stop(
                agent_id,
                transaction_id,
            )
            if finalized is None:
                return
            self.clear_operator_tmux_state(agent_id)
            self.save_settings()
            finalized_agent = finalized.get("agent")
            if isinstance(finalized_agent, dict):
                self.agents[agent_id] = finalized_agent
            self.notify(f"Stopped and finalized managed Operator {agent_id}.")
            await self.refresh_agents()
            await self.maybe_record_ready_action_for_target(
                agent_id,
                step="stop",
                outcome="succeeded",
                evidence={"managed_stop_transaction_id": transaction_id},
            )
            await self.refresh_events()
            await self.load_thread(agent_id)
        finally:
            self.tmux_stop_in_progress_agent_ids.discard(agent_id)

