    async def queue_command(
        self, agent_id: str, command_type: str, payload: dict[str, Any]
    ) -> dict[str, Any]:
        response = await self.api_client().post(
            "/v1/commands",
            json={
                "agent_id": agent_id,
                "type": command_type,
                "payload": payload,
            },
            headers=auth_headers(self.token),
        )
        response.raise_for_status()
        return response.json()

    async def delete_agent(
        self, agent_id: str, *, delete_thread: bool = False
    ) -> dict[str, Any]:
        response = await self.api_client().delete(
            f"/v1/agents/{agent_id}",
            params={"delete_thread": delete_thread},
            headers=auth_headers(self.token),
        )
        response.raise_for_status()
        return response.json()

    async def unhide_agent(self, agent_id: str) -> dict[str, Any]:
        response = await self.api_client().put(
            f"/v1/agents/{agent_id}/unhide",
            headers=auth_headers(self.token),
        )
        response.raise_for_status()
        return response.json()

    async def set_agent_pbx_active(
        self,
        agent_id: str,
        *,
        active: bool,
    ) -> dict[str, Any]:
        response = await self.api_client().put(
            f"/v1/agents/{agent_id}/pbx-active",
            json={"active": active},
            headers=auth_headers(self.token),
        )
        response.raise_for_status()
        return response.json()

    async def create_agent_report(
        self, agent_id: str, payload: dict[str, Any]
    ) -> dict[str, Any]:
        response = await self.api_client().post(
            f"/v1/agents/{agent_id}/reports",
            json=payload,
            headers=auth_headers(self.token),
        )
        response.raise_for_status()
        return response.json()

    async def delete_queued_command(self, command_id: str) -> dict[str, Any]:
        response = await self.api_client().delete(
            f"/v1/commands/{command_id}",
            headers=auth_headers(self.token),
        )
        response.raise_for_status()
        return response.json()

    async def fetch_agent_file_listing(
        self,
        agent_id: str,
        path: str | None = None,
    ) -> dict[str, Any]:
        response = await self.api_client().get(
            f"/v1/agents/{agent_id}/files",
            params={"path": path or "."},
            headers=auth_headers(self.token),
            timeout=15,
        )
        response.raise_for_status()
        payload = response.json()
        if not isinstance(payload, dict):
            raise ValueError("Files response was not an object")
        return payload

    async def fetch_agent_file_document(
        self,
        agent_id: str,
        path: str,
    ) -> dict[str, Any]:
        response = await self.api_client().get(
            f"/v1/agents/{agent_id}/files/document",
            params={"path": path},
            headers=auth_headers(self.token),
            timeout=20,
        )
        response.raise_for_status()
        payload = response.json()
        if not isinstance(payload, dict):
            raise ValueError("File document response was not an object")
        return payload

    async def put_agent_file_document(
        self,
        agent_id: str,
        *,
        path: str,
        text: str,
        previous_sha256: str | None = None,
        previous_mtime: float | None = None,
        create: bool = False,
    ) -> dict[str, Any]:
        response = await self.api_client().put(
            f"/v1/agents/{agent_id}/files/document",
            json={
                "path": path,
                "text": text,
                "previous_sha256": previous_sha256,
                "previous_mtime": previous_mtime,
                "create": create,
            },
            headers=auth_headers(self.token),
            timeout=20,
        )
        response.raise_for_status()
        payload = response.json()
        if not isinstance(payload, dict):
            raise ValueError("File document save response was not an object")
        return payload

    async def fetch_agent_file_search(
        self,
        agent_id: str,
        *,
        query: str,
        path: str | None = None,
    ) -> dict[str, Any]:
        response = await self.api_client().get(
            f"/v1/agents/{agent_id}/files/search",
            params={
                "query": query,
                "path": path or self.file_path_by_agent.get(agent_id, "."),
            },
            headers=auth_headers(self.token),
            timeout=20,
        )
        response.raise_for_status()
        payload = response.json()
        if not isinstance(payload, dict):
            raise ValueError("Files search response was not an object")
        return payload

    async def fetch_agent_file_diagnostics(
        self,
        agent_id: str,
        *,
        path: str,
        tool: str = "auto",
    ) -> dict[str, Any]:
        response = await self.api_client().post(
            f"/v1/agents/{agent_id}/files/diagnostics",
            json={"path": path, "tool": tool},
            headers=auth_headers(self.token),
            timeout=30,
        )
        response.raise_for_status()
        payload = response.json()
        if not isinstance(payload, dict):
            raise ValueError("File diagnostics response was not an object")
        return payload

    async def load_agent_files(self, agent_id: str, path: str | None = None) -> None:
        current_path = path if path is not None else self.file_path_by_agent.get(agent_id, ".")
        path_label = self.query_one("#file-path", Static)
        path_label.update(f"Path: {current_path or '.'}")
        self.set_file_preview_text(f"Loading files for {agent_id}...")
        try:
            payload = await self.fetch_agent_file_listing(agent_id, current_path or ".")
        except Exception as exc:
            self.render_file_error(agent_id, f"Unable to load files for {agent_id}: {exc}")
            return
        self.render_file_list(payload)

    async def load_parent_agent_files(self, agent_id: str) -> None:
        current = self.file_path_by_agent.get(agent_id, ".")
        parent = "."
        entries = self.file_entries_by_agent.get(agent_id, {})
        current_entry = entries.get(current)
        if isinstance(current_entry, dict):
            parent = str(current_entry.get("parent") or ".")
        else:
            parts = [part for part in current.split("/") if part and part != "."]
            parent = "/".join(parts[:-1]) if len(parts) > 1 else "."
        await self.load_agent_files(agent_id, parent)

    async def search_agent_files(self, agent_id: str, query: str | None = None) -> None:
        search_input = self.query_one_or_none("#files-search-query", Input)
        resolved_query = query if query is not None else (
            search_input.value if search_input is not None else ""
        )
        resolved_query = resolved_query.strip()
        self.file_search_query_by_agent[agent_id] = resolved_query
        if search_input is not None and search_input.value != resolved_query:
            search_input.value = resolved_query
        status = self.query_one_or_none("#file-search-status", Static)
        if not resolved_query:
            self.clear_file_search(agent_id)
            return
        if status is not None:
            status.update(f"Search: searching for {resolved_query!r}...")
        try:
            payload = await self.fetch_agent_file_search(
                agent_id,
                query=resolved_query,
                path=self.file_path_by_agent.get(agent_id, "."),
            )
        except Exception as exc:
            if status is not None:
                status.update(f"Search: failed ({exc})")
            return
        self.render_file_search_results(payload)

    def clear_file_search(self, agent_id: str | None = None) -> None:
        resolved_agent_id = agent_id or self.selected_agent_id
        if resolved_agent_id:
            self.file_search_results_by_agent[resolved_agent_id] = {}
            self.file_search_query_by_agent[resolved_agent_id] = ""
        search_input = self.query_one_or_none("#files-search-query", Input)
        if search_input is not None:
            search_input.value = ""
        table = self.query_one_or_none("#file-search-results", DataTable)
        if table is not None:
            table.clear()
        status = self.query_one_or_none("#file-search-status", Static)
        if status is not None:
            status.update("Search: -")

    def focus_file_search(self) -> None:
        search_input = self.query_one_or_none("#files-search-query", Input)
        if search_input is not None:
            search_input.focus()

    def render_file_search_results(self, payload: dict[str, Any]) -> None:
        agent_id = str(payload.get("agent_id") or self.selected_agent_id or "")
        results = payload.get("results") if isinstance(payload.get("results"), list) else []
        table = self.query_one("#file-search-results", DataTable)
        position = self.data_table_position(table)
        table.clear()
        result_map: dict[str, dict[str, Any]] = {}
        for index, result in enumerate(results):
            if not isinstance(result, dict):
                continue
            path = str(result.get("path") or "")
            if not path:
                continue
            key = f"{index}:{path}:{result.get('line') or 0}:{result.get('column') or 0}"
            result_map[key] = result
            table.add_row(
                path,
                str(result.get("line") or ""),
                str(result.get("column") or ""),
                str(result.get("snippet") or ""),
                key=key,
            )
        if agent_id:
            self.file_search_results_by_agent[agent_id] = result_map
            self.file_search_query_by_agent[agent_id] = str(payload.get("query") or "")
        status = self.query_one_or_none("#file-search-status", Static)
        if status is not None:
            error = payload.get("error") if isinstance(payload.get("error"), dict) else None
            if error:
                status.update(f"Search: {error.get('code') or 'SEARCH_ERROR'}")
            else:
                suffix = " truncated" if payload.get("truncated") else ""
                status.update(
                    f"Search: {len(result_map)} match(es) via {payload.get('backend') or 'none'}{suffix}"
                )
        self.restore_data_table_position(table, position)

    async def select_file_search_result(self, row_key: str) -> None:
        agent_id = self.selected_agent_id
        if not agent_id:
            return
        result = self.file_search_results_by_agent.get(agent_id, {}).get(row_key)
        if not result:
            return
        path = str(result.get("path") or "")
        if not path:
            return
        self.selected_file_path_by_agent[agent_id] = path
        try:
            line = int(result.get("line") or 0)
        except (TypeError, ValueError):
            line = 0
        if line > 0:
            self.selected_file_line_by_agent[agent_id] = line
        else:
            self.selected_file_line_by_agent.pop(agent_id, None)
        await self.load_file_preview(agent_id, path)

    async def select_file_entry(self, row_key: str) -> None:
        agent_id = self.selected_agent_id
        if not agent_id:
            return
        entry = self.file_entries_by_agent.get(agent_id, {}).get(row_key)
        if not entry:
            return
        selected_path = str(entry.get("path") or row_key)
        if selected_path:
            self.selected_file_path_by_agent[agent_id] = selected_path
            self.selected_file_line_by_agent.pop(agent_id, None)
        if entry.get("kind") == "directory":
            await self.load_agent_files(agent_id, str(entry.get("path") or "."))
            return
        await self.load_file_preview(agent_id, str(entry.get("path") or row_key))

    async def load_file_preview(self, agent_id: str, path: str) -> None:
        self.set_file_preview_text(f"Loading {path}...")
        try:
            response = await self.api_client().get(
                f"/v1/agents/{agent_id}/files/preview",
                params={"path": path},
                headers=auth_headers(self.token),
                timeout=15,
            )
            response.raise_for_status()
            payload = response.json()
        except Exception as exc:
            self.set_file_preview_text(f"Unable to preview {path}: {exc}")
            return
        self.set_file_preview_payload(payload)

    def selected_file_path(self, agent_id: str | None = None) -> str | None:
        resolved_agent_id = agent_id or self.selected_agent_id
        if not resolved_agent_id:
            return None
        path = self.selected_file_path_by_agent.get(resolved_agent_id)
        return path.strip() if isinstance(path, str) and path.strip() else None

    async def copy_selected_file_path(self, agent_id: str | None = None) -> None:
        resolved_agent_id = agent_id or self.selected_agent_id
        path = self.selected_file_path(resolved_agent_id)
        if not resolved_agent_id or not path:
            self.notify("Select a file or search result first.")
            return
        try:
            source = await asyncio.to_thread(write_clipboard_text, path)
        except Exception as exc:
            self.notify(f"Unable to copy path: {exc}")
            return
        self.notify(f"Copied {path} via {source}.")

    async def copy_selected_file_text(self, agent_id: str | None = None) -> None:
        resolved_agent_id = agent_id or self.selected_agent_id
        path = self.selected_file_path(resolved_agent_id)
        if not resolved_agent_id or not path:
            self.notify("Select a file or search result first.")
            return
        try:
            payload = await self.fetch_agent_file_document(resolved_agent_id, path)
        except Exception as exc:
            self.notify(f"Unable to load file text: {exc}")
            return
        error = payload.get("error") if isinstance(payload.get("error"), dict) else None
        if error:
            self.notify(
                f"Unable to copy text: {error.get('code') or 'FILE_ERROR'}"
            )
            self.set_file_preview_text(self.format_file_error(error))
            return
        text = payload.get("text")
        if not isinstance(text, str):
            self.notify("Selected file has no readable text.")
            return
        try:
            source = await asyncio.to_thread(write_clipboard_text, text)
        except Exception as exc:
            self.notify(f"Unable to copy text: {exc}")
            return
        self.notify(f"Copied text from {path} via {source}.")

    def open_file_path_action(self, action: str) -> None:
        agent_id = self.selected_agent_id
        if not agent_id:
            self.notify("Select an agent first.", severity="warning")
            return
        current = self.file_path_by_agent.get(agent_id, ".")
        selected = self.selected_file_path(agent_id)
        source: str | None = None
        if action == "move":
            if not selected:
                self.notify("Select a file or directory to move.", severity="warning")
                return
            source = selected
            initial_path = selected
        else:
            suffix = "new-file.txt" if action == "create_file" else "new-directory"
            initial_path = suffix if current in {"", "."} else f"{current.rstrip('/')}/{suffix}"
        self.push_screen(
            FilePathActionScreen(
                agent_id=agent_id,
                action=action,
                initial_path=initial_path,
                source=source,
            )
        )

    async def apply_file_path_action(
        self,
        agent_id: str,
        action: str,
        path: str,
        *,
        source: str | None = None,
    ) -> None:
        endpoint = f"/v1/agents/{agent_id}/files/create"
        payload: dict[str, Any]
        if action == "move":
            if not source:
                self.notify("Move source is missing.", severity="error")
                return
            endpoint = f"/v1/agents/{agent_id}/files/move"
            payload = {"source": source, "destination": path}
        else:
            payload = {
                "path": path,
                "kind": "directory" if action == "create_directory" else "file",
                "text": "",
            }
        try:
            response = await self.api_client().post(
                endpoint,
                json=payload,
                headers=auth_headers(self.token),
                timeout=20,
            )
            response.raise_for_status()
            result = response.json()
        except Exception as exc:
            self.notify(f"File action failed: {exc}", severity="error")
            return
        if self.notify_file_mutation_error(result):
            return
        if action == "move" and source:
            self.reconcile_editor_path_move(agent_id, source=source, destination=path)
            self.selected_file_path_by_agent[agent_id] = path
            verb = "Moved"
        else:
            self.selected_file_path_by_agent[agent_id] = path
            verb = "Created directory" if action == "create_directory" else "Created file"
        parent = path.rsplit("/", 1)[0] if "/" in path else "."
        await self.load_agent_files(agent_id, parent or ".")
        if action != "create_directory":
            await self.load_file_preview(agent_id, path)
        self.notify(f"{verb}: {path}")

    async def request_file_delete(self, agent_id: str | None = None) -> None:
        resolved_agent_id = agent_id or self.selected_agent_id
        path = self.selected_file_path(resolved_agent_id)
        if not resolved_agent_id or not path:
            self.notify("Select a file or directory to delete.", severity="warning")
            return
        self.capture_editor_buffer(resolved_agent_id)
        if self.editor_path_within(resolved_agent_id, path) and (
            resolved_agent_id in self.editor_dirty_agent_ids
        ):
            self.notify(
                "Save or discard the open editor changes before deleting this path.",
                severity="warning",
            )
            return
        try:
            response = await self.api_client().get(
                f"/v1/agents/{resolved_agent_id}/files/delete-preview",
                params={"path": path},
                headers=auth_headers(self.token),
                timeout=20,
            )
            response.raise_for_status()
            preview = response.json()
        except Exception as exc:
            self.notify(f"Delete preview failed: {exc}", severity="error")
            return
        if self.notify_file_mutation_error(preview):
            return
        self.push_screen(FileDeleteConfirmScreen(agent_id=resolved_agent_id, preview=preview))

    async def apply_file_delete(
        self,
        agent_id: str,
        preview: dict[str, Any],
    ) -> None:
        path = str(preview.get("path") or "")
        payload = {
            "path": path,
            "preview_token": str(preview.get("preview_token") or ""),
            "actor": "tui-operator",
            "confirm_tracked": preview.get("delete_mode") == "git_delete",
        }
        try:
            response = await self.api_client().post(
                f"/v1/agents/{agent_id}/files/delete",
                json=payload,
                headers=auth_headers(self.token),
                timeout=30,
            )
            response.raise_for_status()
            result = response.json()
        except Exception as exc:
            self.notify(f"Delete failed: {exc}", severity="error")
            return
        if self.notify_file_mutation_error(result):
            return
        if self.editor_path_within(agent_id, path):
            self.close_editor_document(agent_id)
        self.selected_file_path_by_agent.pop(agent_id, None)
        self.selected_file_line_by_agent.pop(agent_id, None)
        parent = path.rsplit("/", 1)[0] if "/" in path else "."
        await self.load_agent_files(agent_id, parent or ".")
        if result.get("trashed"):
            self.notify(f"Moved {path} to recoverable project trash.")
        else:
            self.notify(f"Deleted tracked path {path}; Git can restore it.")

    async def open_file_trash(self, agent_id: str | None = None) -> None:
        resolved_agent_id = agent_id or self.selected_agent_id
        if not resolved_agent_id:
            self.notify("Select an agent first.", severity="warning")
            return
        try:
            response = await self.api_client().get(
                f"/v1/agents/{resolved_agent_id}/files/trash",
                headers=auth_headers(self.token),
                timeout=20,
            )
            response.raise_for_status()
            payload = response.json()
        except Exception as exc:
            self.notify(f"Unable to list project trash: {exc}", severity="error")
            return
        if self.notify_file_mutation_error(payload):
            return
        entries = payload.get("entries") if isinstance(payload, dict) else []
        self.push_screen(
            FileTrashScreen(
                agent_id=resolved_agent_id,
                entries=[item for item in entries if isinstance(item, dict)]
                if isinstance(entries, list)
                else [],
            )
        )

    async def restore_file_trash(self, agent_id: str, trash_id: str) -> None:
        try:
            response = await self.api_client().post(
                f"/v1/agents/{agent_id}/files/trash/restore",
                json={"trash_id": trash_id},
                headers=auth_headers(self.token),
                timeout=30,
            )
            response.raise_for_status()
            result = response.json()
        except Exception as exc:
            self.notify(f"Trash restore failed: {exc}", severity="error")
            return
        if self.notify_file_mutation_error(result):
            return
        path = str(result.get("path") or "")
        parent = path.rsplit("/", 1)[0] if "/" in path else "."
        self.selected_file_path_by_agent[agent_id] = path
        await self.load_agent_files(agent_id, parent or ".")
        if path:
            await self.load_file_preview(agent_id, path)
        self.notify(f"Restored {path} from project trash.")

    async def prune_file_trash(self, agent_id: str) -> None:
        try:
            preview_response = await self.api_client().get(
                f"/v1/agents/{agent_id}/files/trash/prune-preview",
                headers=auth_headers(self.token),
                timeout=20,
            )
            preview_response.raise_for_status()
            preview = preview_response.json()
        except Exception as exc:
            self.notify(f"Trash prune preview failed: {exc}", severity="error")
            return
        if self.notify_file_mutation_error(preview):
            return
        if int(preview.get("count") or 0) == 0:
            self.notify("No expired project trash entries are eligible for pruning.")
            return
        try:
            response = await self.api_client().post(
                f"/v1/agents/{agent_id}/files/trash/prune",
                json={
                    "preview_token": str(preview.get("preview_token") or ""),
                    "cutoff": float(preview.get("cutoff") or time.time()),
                },
                headers=auth_headers(self.token),
                timeout=30,
            )
            response.raise_for_status()
            result = response.json()
        except Exception as exc:
            self.notify(f"Trash prune failed: {exc}", severity="error")
            return
        if self.notify_file_mutation_error(result):
            return
        batch_id = str(result.get("batch_id") or "")
        if batch_id:
            self.latest_file_trash_prune_batch_by_agent[agent_id] = batch_id
        self.notify(
            f"Quarantined {int(result.get('count') or 0)} expired trash entry(s); "
            "Undo Prune remains available."
        )

    async def undo_file_trash_prune(self, agent_id: str) -> None:
        batch_id = self.latest_file_trash_prune_batch_by_agent.get(agent_id, "")
        if not batch_id:
            self.notify("No project trash prune batch is available to undo.", severity="warning")
            return
        try:
            response = await self.api_client().post(
                f"/v1/agents/{agent_id}/files/trash/prune-undo",
                json={"batch_id": batch_id},
                headers=auth_headers(self.token),
                timeout=30,
            )
            response.raise_for_status()
            result = response.json()
        except Exception as exc:
            self.notify(f"Trash prune undo failed: {exc}", severity="error")
            return
        if self.notify_file_mutation_error(result):
            return
        self.latest_file_trash_prune_batch_by_agent.pop(agent_id, None)
        self.notify(f"Restored {len(result.get('trash_ids') or [])} pruned trash entry(s).")

    def notify_file_mutation_error(self, payload: Any) -> bool:
        error = payload.get("error") if isinstance(payload, dict) else None
        if not isinstance(error, dict):
            return False
        code = str(error.get("code") or "FILE_ACTION_FAILED")
        message = str(error.get("message") or "File action failed")
        remediation = str(error.get("remediation") or "")
        detail = f"{code}: {message}"
        if remediation:
            detail = f"{detail} ({remediation})"
        self.notify(detail, severity="warning")
        return True

    def editor_path_within(self, agent_id: str, path: str) -> bool:
        document = self.editor_documents_by_agent.get(agent_id)
        editor_path = str(document.get("path") or "") if isinstance(document, dict) else ""
        normalized = path.rstrip("/")
        return bool(
            editor_path
            and normalized
            and (editor_path == normalized or editor_path.startswith(f"{normalized}/"))
        )

    def reconcile_editor_path_move(
        self,
        agent_id: str,
        *,
        source: str,
        destination: str,
    ) -> None:
        document = self.editor_documents_by_agent.get(agent_id)
        if not isinstance(document, dict):
            return
        editor_path = str(document.get("path") or "")
        normalized_source = source.rstrip("/")
        if editor_path == normalized_source:
            next_path = destination
        elif editor_path.startswith(f"{normalized_source}/"):
            next_path = f"{destination.rstrip('/')}{editor_path[len(normalized_source):]}"
        else:
            return
        document["path"] = next_path
        self.selected_file_path_by_agent[agent_id] = next_path
        if self.editor_rendered_agent_id == agent_id:
            self.set_editor_status(self.format_editor_status(agent_id, document))

    def capture_editor_buffer(self, agent_id: str | None = None) -> None:
        if self.editor_rendering:
            return
        resolved_agent_id = agent_id or self.selected_agent_id
        if not resolved_agent_id:
            return
        if self.editor_rendered_agent_id != resolved_agent_id:
            return
        document = self.editor_documents_by_agent.get(resolved_agent_id)
        if not isinstance(document, dict):
            return
        editor = self.query_one_or_none("#editor", TextArea)
        if editor is None:
            return
        document["current_text"] = editor.text
        if editor.text != str(document.get("text") or ""):
            self.editor_dirty_agent_ids.add(resolved_agent_id)
        else:
            self.editor_dirty_agent_ids.discard(resolved_agent_id)

    def editor_document_for_agent(
        self,
        agent_id: str | None = None,
    ) -> dict[str, Any] | None:
        resolved_agent_id = agent_id or self.selected_agent_id
        if not resolved_agent_id:
            return None
        document = self.editor_documents_by_agent.get(resolved_agent_id)
        return document if isinstance(document, dict) else None

    def format_editor_status(
        self,
        agent_id: str,
        document: dict[str, Any] | None,
    ) -> str:
        if not document:
            return "Editor: no file"
        path = str(document.get("path") or "-")
        dirty = "*" if agent_id in self.editor_dirty_agent_ids else ""
        language = str(document.get("language") or "text")
        line_count = document.get("line_count")
        line_text = f" | {line_count} lines" if line_count else ""
        return f"Editor: {dirty}{path} | {language}{line_text}"

    def set_editor_status(self, text: str) -> None:
        status = self.query_one_or_none("#editor-status", Static)
        if status is not None:
            status.update(text)

    def set_editor_diagnostics(self, text: str) -> None:
        diagnostics = self.query_one_or_none("#editor-diagnostics", TextArea)
        if diagnostics is not None:
            diagnostics.text = text

    def update_editor_dirty_state(self, agent_id: str | None = None) -> None:
        if self.editor_rendering:
            return
        resolved_agent_id = agent_id or self.selected_agent_id
        if not resolved_agent_id:
            return
        self.capture_editor_buffer(resolved_agent_id)
        self.set_editor_status(
            self.format_editor_status(
                resolved_agent_id,
                self.editor_document_for_agent(resolved_agent_id),
            )
        )

    def render_editor_for_agent(self, agent_id: str) -> None:
        editor = self.query_one_or_none("#editor", TextArea)
        if editor is None:
            return
        document = self.editor_document_for_agent(agent_id)
        self.editor_rendering = True
        try:
            self.editor_rendered_agent_id = agent_id
            if not document:
                editor.load_text("")
                self.set_editor_status("Editor: no file")
                self.set_editor_diagnostics("Diagnostics: not run")
                return
            current_text = (
                document.get("current_text")
                if "current_text" in document
                else document.get("text")
            )
            editor.load_text(str(current_text) if current_text is not None else "")
            self.set_editor_language(editor, document.get("language"))
            line = self.selected_file_line_by_agent.get(agent_id)
            if line is not None:
                try:
                    editor.move_cursor((max(0, line - 1), 0), center=True)
                except Exception:
                    pass
            self.set_editor_status(self.format_editor_status(agent_id, document))
        finally:
            self.editor_rendering = False

    def set_editor_language(self, editor: TextArea, language: Any) -> None:
        language_name = str(language or "").strip() or None
        try:
            editor.language = language_name
        except Exception:
            try:
                editor.language = None
            except Exception:
                pass

    def editor_surface_for_agent(self, agent_id: str | None = None) -> str:
        resolved_agent_id = agent_id or self.selected_agent_id
        if not resolved_agent_id:
            return self.editor_default_surface
        return normalize_editor_surface(
            self.editor_surface_by_agent.get(
                resolved_agent_id,
                self.editor_default_surface,
            )
        )

    async def show_text_editor(self, agent_id: str | None = None) -> None:
        resolved_agent_id = agent_id or self.selected_agent_id
        if not resolved_agent_id:
            self.notify("Select an Agent or Operator first.", severity="warning")
            return
        self.editor_surface_by_agent[resolved_agent_id] = EDITOR_SURFACE_TEXTUAL
        self.terminal_editor_pending_agent_id = None
        if self.terminal_editor_agent_id == resolved_agent_id:
            await self.detach_terminal_editor_surface()
        self.activate_agent_tab("editor-tab")
        self.render_editor_for_agent(resolved_agent_id)
        self.apply_terminal_editor_class()
        self.focus_right_pane_content()

    async def open_selected_file_in_editor(self, agent_id: str | None = None) -> None:
        if self.editor_default_surface == EDITOR_SURFACE_TERMINAL:
            await self.open_selected_file_in_terminal_editor(agent_id)
            return
        await self.open_selected_file_in_text_editor(agent_id)

    async def open_selected_file_in_text_editor(
        self,
        agent_id: str | None = None,
    ) -> None:
        resolved_agent_id = agent_id or self.selected_agent_id
        path = self.selected_file_path(resolved_agent_id)
        if not resolved_agent_id or not path:
            self.notify("Select a file or search result first.", severity="warning")
            return
        line = self.selected_file_line_by_agent.get(resolved_agent_id)
        await self.open_editor_for_agent(resolved_agent_id, path=path, line=line)

    async def open_selected_file_in_terminal_editor(
        self,
        agent_id: str | None = None,
    ) -> None:
        resolved_agent_id = agent_id or self.selected_agent_id
        path = self.selected_file_path(resolved_agent_id)
        if not resolved_agent_id or not path:
            self.notify("Select a file or search result first.", severity="warning")
            return
        await self.start_terminal_editor(
            resolved_agent_id,
            path=path,
            line=self.selected_file_line_by_agent.get(resolved_agent_id),
        )

    async def open_editor_for_agent(
        self,
        agent_id: str,
        *,
        path: str,
        line: int | None = None,
    ) -> None:
        existing = self.editor_document_for_agent(agent_id)
        if existing is not None:
            self.capture_editor_buffer(agent_id)
        if agent_id in self.editor_dirty_agent_ids:
            existing_path = str((existing or {}).get("path") or "")
            if existing_path == path:
                await self.show_text_editor(agent_id)
                self.notify(
                    "Showing the existing unsaved Textual buffer.",
                    severity="warning",
                )
            else:
                self.notify(
                    "Save or revert Textual editor changes before opening another file.",
                    severity="warning",
                )
            return
        self.set_editor_status(f"Editor: loading {path}...")
        try:
            payload = await self.fetch_agent_file_document(agent_id, path)
        except Exception as exc:
            self.set_editor_status(f"Editor: load failed ({exc})")
            self.notify(f"Unable to open editor: {exc}", severity="error")
            return
        error = payload.get("error") if isinstance(payload.get("error"), dict) else None
        if error:
            self.set_editor_status(f"Editor: {error.get('code') or 'FILE_ERROR'}")
            self.set_editor_diagnostics(self.format_file_error(error))
            self.notify(
                f"Unable to open editor: {error.get('code') or 'FILE_ERROR'}",
                severity="warning",
            )
            return
        text = payload.get("text")
        if not isinstance(text, str):
            self.set_editor_status("Editor: selected file has no readable text")
            self.notify("Selected file has no readable text.", severity="warning")
            return
        self.editor_surface_by_agent[agent_id] = EDITOR_SURFACE_TEXTUAL
        self.terminal_editor_pending_agent_id = None
        if self.terminal_editor_agent_id == agent_id:
            await self.detach_terminal_editor_surface()
        payload["current_text"] = text
        self.editor_documents_by_agent[agent_id] = payload
        self.editor_dirty_agent_ids.discard(agent_id)
        self.selected_file_path_by_agent[agent_id] = str(payload.get("path") or path)
        if line and line > 0:
            self.selected_file_line_by_agent[agent_id] = line
        else:
            self.selected_file_line_by_agent.pop(agent_id, None)
        self.activate_agent_tab("editor-tab")
        self.render_editor_for_agent(agent_id)
        self.set_editor_diagnostics("Diagnostics: not run")
        self.focus_right_pane_content()

    def apply_terminal_editor_class(self) -> None:
        surface = self.query_one_or_none(
            "#pbx-editor-terminal", PbxTerminalSurface
        )
        active = bool(
            self.active_agent_tab == "editor-tab"
            and self.selected_agent_id
            and self.editor_surface_for_agent(self.selected_agent_id)
            == EDITOR_SURFACE_TERMINAL
            and (
                self.terminal_editor_pending_agent_id == self.selected_agent_id
                or (
                    self.terminal_editor_agent_id == self.selected_agent_id
                    and surface is not None
                    and surface.attached
                )
            )
        )
        try:
            screens = list(self.screen_stack)
        except ScreenStackError:
            return
        for screen in screens:
            screen.set_class(active, "terminal-editor")

    async def attach_terminal_editor(
        self,
        agent_id: str,
        runtime: dict[str, Any],
    ) -> bool:
        if (
            agent_id != self.selected_agent_id
            or self.active_agent_tab != "editor-tab"
            or not runtime.get("running")
        ):
            return False
        surface = self.query_one_or_none(
            "#pbx-editor-terminal", PbxTerminalSurface
        )
        if surface is None:
            return False
        target = f"editor:{agent_id}:{runtime.get('pane_id')}"
        if (
            self.terminal_editor_agent_id == agent_id
            and surface.attached
            and surface.target == target
        ):
            surface.sync_geometry()
            self.apply_terminal_editor_class()
            return True
        await self.detach_terminal_editor_surface()
        if agent_id != self.selected_agent_id or self.active_agent_tab != "editor-tab":
            return False
        self.terminal_editor_agent_id = agent_id
        self.terminal_editor_pending_agent_id = agent_id
        self.terminal_editor_runtime_by_agent[agent_id] = dict(runtime)
        try:
            # Reveal the terminal before starting its PTY so the nested tmux
            # client receives the real Editor-tab rectangle rather than 80x24.
            for screen in list(self.screen_stack):
                screen.set_class(True, "terminal-editor")
            if not await self.wait_for_embedded_terminal_layout(surface):
                raise RuntimeError(
                    "managed terminal editor did not receive a visible layout rectangle"
                )
            if agent_id != self.selected_agent_id or self.active_agent_tab != "editor-tab":
                raise RuntimeError("editor target changed while attaching")
            surface.attach(
                tmux_client_attach_command(runtime),
                target=target,
                cwd=str(runtime.get("root") or Path.home()),
            )
            surface.set_scroll_mode(EMBEDDED_SCROLL_MODE_CHILD)
        except Exception as exc:
            surface.detach()
            self.terminal_editor_agent_id = None
            self.terminal_editor_pending_agent_id = None
            self.apply_terminal_editor_class()
            self.notify(f"Unable to attach terminal editor: {exc}", severity="error")
            return False
        self.terminal_editor_pending_agent_id = None
        self.apply_terminal_editor_class()
        path = str(runtime.get("path") or "")
        location = path or "project workspace"
        self.set_editor_status(
            f"Editor: {runtime.get('profile_id') or 'native'} · {location}"
        )
        surface.focus()
        return True

    async def detach_terminal_editor_surface(self) -> None:
        surface = self.query_one_or_none(
            "#pbx-editor-terminal", PbxTerminalSurface
        )
        if surface is not None:
            surface.detach()
        self.terminal_editor_agent_id = None
        self.terminal_editor_pending_agent_id = None
        self.apply_terminal_editor_class()

    async def load_terminal_editor_status(
        self,
        agent_id: str,
        *,
        start_if_missing: bool = False,
    ) -> None:
        try:
            response = await self.api_client().get(
                f"/v1/agents/{agent_id}/terminal-editor",
                headers=auth_headers(self.token),
                timeout=10,
            )
            response.raise_for_status()
            runtime = response.json()
        except Exception as exc:
            if self.terminal_editor_pending_agent_id == agent_id:
                self.terminal_editor_pending_agent_id = None
                self.apply_terminal_editor_class()
            self.notify(f"Unable to load terminal editor: {exc}", severity="warning")
            return
        if not runtime.get("running"):
            self.terminal_editor_runtime_by_agent.pop(agent_id, None)
            if self.terminal_editor_agent_id == agent_id:
                await self.detach_terminal_editor_surface()
            if (
                start_if_missing
                and self.editor_surface_for_agent(agent_id) == EDITOR_SURFACE_TERMINAL
                and agent_id == self.selected_agent_id
                and self.active_agent_tab == "editor-tab"
            ):
                await self.start_terminal_editor(agent_id)
                return
            if self.terminal_editor_pending_agent_id == agent_id:
                self.terminal_editor_pending_agent_id = None
                self.apply_terminal_editor_class()
            return
        self.terminal_editor_runtime_by_agent[agent_id] = dict(runtime)
        if (
            agent_id == self.selected_agent_id
            and self.active_agent_tab == "editor-tab"
            and self.editor_surface_for_agent(agent_id) == EDITOR_SURFACE_TERMINAL
        ):
            await self.attach_terminal_editor(agent_id, runtime)
        elif self.terminal_editor_pending_agent_id == agent_id:
            self.terminal_editor_pending_agent_id = None
            self.apply_terminal_editor_class()

    async def start_terminal_editor(
        self,
        agent_id: str | None = None,
        *,
        profile_id: str | None = None,
        path: str | None = None,
        line: int | None = None,
    ) -> bool:
        resolved_agent_id = agent_id or self.selected_agent_id
        if not resolved_agent_id:
            self.notify("Select an Agent or Operator first.", severity="warning")
            return False
        self.capture_editor_buffer(resolved_agent_id)
        if resolved_agent_id in self.editor_dirty_agent_ids:
            self.notify(
                "Save or revert Textual editor changes before opening a terminal editor.",
                severity="warning",
            )
            return False
        payload: dict[str, Any] = {}
        if path:
            payload["path"] = path
            payload["line"] = line
        if profile_id:
            payload["profile_id"] = profile_id
        self.editor_surface_by_agent[resolved_agent_id] = EDITOR_SURFACE_TERMINAL
        self.terminal_editor_pending_agent_id = resolved_agent_id
        self.activate_agent_tab("editor-tab")
        self.set_editor_status("Editor: opening native project workspace...")
        self.apply_terminal_editor_class()
        try:
            response = await self.api_client().post(
                f"/v1/agents/{resolved_agent_id}/terminal-editor",
                json=payload,
                headers=auth_headers(self.token),
                timeout=20,
            )
            response.raise_for_status()
            runtime = response.json()
        except Exception as exc:
            self.terminal_editor_pending_agent_id = None
            self.apply_terminal_editor_class()
            self.notify(f"Unable to start terminal editor: {exc}", severity="error")
            return False
        error = runtime.get("error") if isinstance(runtime.get("error"), dict) else None
        if runtime.get("ready") is False or error:
            self.terminal_editor_pending_agent_id = None
            self.apply_terminal_editor_class()
            code = str((error or {}).get("code") or "TERMINAL_EDITOR_UNAVAILABLE")
            message = str((error or {}).get("message") or "native editor unavailable")
            self.notify(f"{code}: {message}", severity="warning")
            return False
        self.terminal_editor_runtime_by_agent[resolved_agent_id] = dict(runtime)
        attached = await self.attach_terminal_editor(resolved_agent_id, runtime)
        if attached:
            self.notify(
                f"Managed {runtime.get('profile_id') or 'terminal'} editor opened."
            )
        return attached

    async def stop_terminal_editor(self, agent_id: str | None = None) -> bool:
        resolved_agent_id = agent_id or self.selected_agent_id
        if not resolved_agent_id:
            self.notify("Select an Agent or Operator first.", severity="warning")
            return False
        runtime = self.terminal_editor_runtime_by_agent.get(resolved_agent_id, {})
        path = str(runtime.get("path") or "")
        try:
            response = await self.api_client().delete(
                f"/v1/agents/{resolved_agent_id}/terminal-editor",
                headers=auth_headers(self.token),
                timeout=15,
            )
            response.raise_for_status()
            result = response.json()
        except Exception as exc:
            self.notify(f"Unable to stop terminal editor: {exc}", severity="error")
            return False
        self.editor_surface_by_agent[resolved_agent_id] = EDITOR_SURFACE_TEXTUAL
        self.terminal_editor_pending_agent_id = None
        if self.terminal_editor_agent_id == resolved_agent_id:
            await self.detach_terminal_editor_surface()
        self.terminal_editor_runtime_by_agent.pop(resolved_agent_id, None)
        if path and self.editor_document_for_agent(resolved_agent_id) is not None:
            await self.open_editor_for_agent(resolved_agent_id, path=path)
        self.notify(
            "Managed terminal editor stopped."
            if result.get("stopped")
            else "No managed terminal editor was running."
        )
        return True

    async def forget_terminal_editor(self, agent_id: str | None = None) -> bool:
        """Remove only a server-verified stale or exited editor mapping."""

        resolved_agent_id = agent_id or self.selected_agent_id
        if not resolved_agent_id:
            self.notify("Select an Agent or Operator first.", severity="warning")
            return False
        try:
            response = await self.api_client().post(
                f"/v1/agents/{resolved_agent_id}/terminal-editor/forget",
                headers=auth_headers(self.token),
                timeout=15,
            )
            response.raise_for_status()
            result = response.json()
        except Exception as exc:
            self.notify(
                f"Unable to forget terminal editor mapping: {exc}",
                severity="error",
            )
            return False
        if self.terminal_editor_agent_id == resolved_agent_id:
            await self.detach_terminal_editor_surface()
        self.terminal_editor_runtime_by_agent.pop(resolved_agent_id, None)
        self.notify(
            "Stale managed terminal editor mapping forgotten."
            if result.get("forgotten")
            else "No managed terminal editor mapping was present."
        )
        return True

    async def save_editor_document(self, agent_id: str | None = None) -> bool:
        resolved_agent_id = agent_id or self.selected_agent_id
        document = self.editor_document_for_agent(resolved_agent_id)
        if not resolved_agent_id or document is None:
            self.notify("Open a file in the editor first.", severity="warning")
            return False
        self.capture_editor_buffer(resolved_agent_id)
        path = str(document.get("path") or "")
        text = str(document.get("current_text") or "")
        if not path:
            self.notify("Editor file path is missing.", severity="warning")
            return False
        self.set_editor_status(f"Editor: saving {path}...")
        try:
            payload = await self.put_agent_file_document(
                resolved_agent_id,
                path=path,
                text=text,
                previous_sha256=(
                    str(document.get("sha256"))
                    if document.get("sha256") is not None
                    else None
                ),
                previous_mtime=(
                    float(document.get("mtime"))
                    if document.get("mtime") is not None
                    else None
                ),
            )
        except Exception as exc:
            self.set_editor_status(f"Editor: save failed ({exc})")
            self.notify(f"Unable to save editor file: {exc}", severity="error")
            return False
        error = payload.get("error") if isinstance(payload.get("error"), dict) else None
        if error:
            self.set_editor_status(f"Editor: {error.get('code') or 'SAVE_FAILED'}")
            self.set_editor_diagnostics(self.format_file_error(error))
            self.notify(
                f"Unable to save: {error.get('code') or 'SAVE_FAILED'}",
                severity="warning",
            )
            return False
        payload["current_text"] = str(payload.get("text") or text)
        self.editor_documents_by_agent[resolved_agent_id] = payload
        self.editor_dirty_agent_ids.discard(resolved_agent_id)
        self.render_editor_for_agent(resolved_agent_id)
        await self.load_agent_files(
            resolved_agent_id,
            self.file_path_by_agent.get(resolved_agent_id, "."),
        )
        self.notify(f"Saved {payload.get('path') or path}.")
        return True

    async def revert_editor_document(self, agent_id: str | None = None) -> None:
        resolved_agent_id = agent_id or self.selected_agent_id
        document = self.editor_document_for_agent(resolved_agent_id)
        if not resolved_agent_id or document is None:
            self.notify("Open a file in the editor first.", severity="warning")
            return
        path = str(document.get("path") or "")
        if not path:
            self.notify("Editor file path is missing.", severity="warning")
            return
        await self.open_editor_for_agent(resolved_agent_id, path=path)

    async def copy_editor_path(self, agent_id: str | None = None) -> None:
        resolved_agent_id = agent_id or self.selected_agent_id
        document = self.editor_document_for_agent(resolved_agent_id)
        if document is None:
            self.notify("Open a file in the editor first.", severity="warning")
            return
        path = str(document.get("path") or "")
        if not path:
            self.notify("Editor file path is missing.", severity="warning")
            return
        try:
            source = await asyncio.to_thread(write_clipboard_text, path)
        except Exception as exc:
            self.notify(f"Unable to copy editor path: {exc}", severity="error")
            return
        self.notify(f"Copied {path} via {source}.")

    async def copy_editor_text(self) -> None:
        editor = self.query_one_or_none("#editor", TextArea)
        if editor is None:
            return
        try:
            source = await asyncio.to_thread(write_clipboard_text, editor.text)
        except Exception as exc:
            self.notify(f"Unable to copy editor text: {exc}", severity="error")
            return
        self.notify(f"Copied editor text via {source}.")

    async def check_editor_document(self, agent_id: str | None = None) -> None:
        resolved_agent_id = agent_id or self.selected_agent_id
        document = self.editor_document_for_agent(resolved_agent_id)
        if not resolved_agent_id or document is None:
            self.notify("Open a file in the editor first.", severity="warning")
            return
        path = str(document.get("path") or "")
        if not path:
            self.notify("Editor file path is missing.", severity="warning")
            return
        self.set_editor_diagnostics(f"Diagnostics: checking {path}...")
        try:
            payload = await self.fetch_agent_file_diagnostics(
                resolved_agent_id,
                path=path,
            )
        except Exception as exc:
            self.set_editor_diagnostics(f"Diagnostics failed:\n{exc}")
            self.notify(f"Diagnostics failed: {exc}", severity="error")
            return
        self.set_editor_diagnostics(self.format_file_diagnostics(payload))
        error = payload.get("error") if isinstance(payload.get("error"), dict) else None
        if error:
            self.notify(
                f"Diagnostics unavailable: {error.get('code') or 'DIAGNOSTIC_ERROR'}",
                severity="warning",
            )
        else:
            diagnostics = payload.get("diagnostics")
            count = len(diagnostics) if isinstance(diagnostics, list) else 0
            self.notify(f"Diagnostics complete: {count} issue(s).")

    async def request_close_editor_document(self, agent_id: str | None = None) -> None:
        resolved_agent_id = agent_id or self.selected_agent_id
        document = self.editor_document_for_agent(resolved_agent_id)
        if not resolved_agent_id or document is None:
            self.notify("No editor file is open.", severity="warning")
            return
        self.capture_editor_buffer(resolved_agent_id)
        if resolved_agent_id in self.editor_dirty_agent_ids:
            self.push_screen(
                EditorCloseConfirmScreen(
                    agent_id=resolved_agent_id,
                    path=str(document.get("path") or "file"),
                )
            )
            return
        self.close_editor_document(resolved_agent_id, notify=True)

    async def save_and_close_editor_document(
        self,
        agent_id: str | None = None,
    ) -> None:
        resolved_agent_id = agent_id or self.selected_agent_id
        if not resolved_agent_id:
            self.notify("No editor file is open.", severity="warning")
            return
        if await self.save_editor_document(resolved_agent_id):
            self.close_editor_document(resolved_agent_id, notify=True)

    def close_editor_document(
        self,
        agent_id: str | None = None,
        *,
        notify: bool = False,
        discarded: bool = False,
    ) -> bool:
        resolved_agent_id = agent_id or self.selected_agent_id
        document = self.editor_document_for_agent(resolved_agent_id)
        if not resolved_agent_id or document is None:
            if notify:
                self.notify("No editor file is open.", severity="warning")
            return False
        path = str(document.get("path") or "file")
        self.editor_documents_by_agent.pop(resolved_agent_id, None)
        self.editor_dirty_agent_ids.discard(resolved_agent_id)
        if self.editor_rendered_agent_id == resolved_agent_id:
            self.editor_rendered_agent_id = None
            editor = self.query_one_or_none("#editor", TextArea)
            if editor is not None:
                self.editor_rendering = True
                try:
                    editor.load_text("")
                finally:
                    self.editor_rendering = False
            self.set_editor_status("Editor: no file")
            self.set_editor_diagnostics("Diagnostics: not run")
        if self.active_agent_tab == "editor-tab":
            self.activate_agent_tab("files-tab")
        self.focus_right_pane_content()
        if notify:
            message = f"Discarded changes and closed {path}." if discarded else f"Closed {path}."
            self.notify(message)
        return True

    async def reveal_editor_document_in_files(
        self,
        agent_id: str | None = None,
    ) -> None:
        resolved_agent_id = agent_id or self.selected_agent_id
        document = self.editor_document_for_agent(resolved_agent_id)
        if not resolved_agent_id or document is None:
            self.notify("Open a file in the editor first.", severity="warning")
            return
        path = str(document.get("path") or "")
        if not path:
            self.notify("Editor file path is missing.", severity="warning")
            return
        directory = path.rsplit("/", 1)[0] if "/" in path else "."
        self.activate_agent_tab("files-tab")
        await self.load_agent_files(resolved_agent_id, directory or ".")
        self.selected_file_path_by_agent[resolved_agent_id] = path
        await self.load_file_preview(resolved_agent_id, path)
        self.focus_right_pane_content()

    def format_file_diagnostics(self, payload: dict[str, Any]) -> str:
        error = payload.get("error") if isinstance(payload.get("error"), dict) else None
        available = payload.get("available_tools")
        if not isinstance(available, list):
            available = []
        diagnostics = payload.get("diagnostics")
        if not isinstance(diagnostics, list):
            diagnostics = []
        lines = [
            f"Diagnostics: {payload.get('backend') or payload.get('tool') or 'none'}",
            f"Path: {payload.get('path') or '-'}",
            f"Available: {', '.join(str(item) for item in available) or '-'}",
            f"Issues: {len(diagnostics)}",
        ]
        if error:
            lines.extend(
                [
                    "",
                    f"Code: {error.get('code') or 'DIAGNOSTIC_ERROR'}",
                    f"Message: {error.get('message') or ''}",
                ]
            )
            if error.get("remediation"):
                lines.append(f"Remediation: {error.get('remediation')}")
            return "\n".join(lines)
        if not diagnostics:
            lines.append("")
            lines.append("No diagnostics reported.")
            return "\n".join(lines)
        lines.append("")
        for item in diagnostics[:100]:
            if not isinstance(item, dict):
                continue
            location = (
                f"{item.get('path') or '-'}:"
                f"{item.get('line') or 1}:"
                f"{item.get('column') or 1}"
            )
            code = f" [{item.get('code')}]" if item.get("code") else ""
            lines.append(
                f"{location} {item.get('severity') or 'error'} "
                f"{item.get('source') or '-'}{code}: {item.get('message') or ''}"
            )
        if len(diagnostics) > 100:
            lines.append(f"... {len(diagnostics) - 100} more")
        return "\n".join(lines)

    def toggle_right_pane_fullscreen(self) -> None:
        """Toggle the complete active right-side tab workspace full width."""

        self.right_pane_fullscreen = not self.right_pane_fullscreen
        self.apply_layout_class()
        self.focus_right_pane_content()
        state = "enabled" if self.right_pane_fullscreen else "disabled"
        self.notify(f"Right pane fullscreen {state}.")

    def toggle_editor_fullscreen(self) -> None:
        """Compatibility alias for the former editor-only fullscreen action."""

        self.toggle_right_pane_fullscreen()

    def render_file_error(self, agent_id: str, message: str) -> None:
        table = self.query_one("#files", DataTable)
        position = self.data_table_position(table)
        table.clear()
        self.file_entries_by_agent[agent_id] = {}
        self.restore_data_table_position(table, position)
        self.set_file_preview_text(message)

    def cache_file_listing(self, payload: dict[str, Any]) -> dict[str, dict[str, Any]]:
        agent_id = str(payload.get("agent_id") or self.selected_agent_id or "")
        path = str(payload.get("path") or ".")
        entries = payload.get("entries") if isinstance(payload.get("entries"), list) else []
        parent = payload.get("parent")
        entry_map: dict[str, dict[str, Any]] = {}
        if parent:
            entry_map[".."] = {
                "name": "..",
                "path": str(parent),
                "kind": "directory",
                "parent": parent,
            }
        for entry in entries:
            if not isinstance(entry, dict):
                continue
            entry_path = str(entry.get("path") or entry.get("name") or "")
            if entry_path:
                entry_map[entry_path] = entry
        if agent_id:
            self.file_path_by_agent[agent_id] = path
            self.file_entries_by_agent[agent_id] = entry_map
            self.file_directory_entries_by_agent.setdefault(agent_id, {})[path] = entry_map
        return entry_map

    def render_file_list(self, payload: dict[str, Any]) -> None:
        agent_id = str(payload.get("agent_id") or self.selected_agent_id or "")
        path = str(payload.get("path") or ".")
        entries = payload.get("entries") if isinstance(payload.get("entries"), list) else []
        entry_map = self.cache_file_listing(payload)
        table = self.query_one("#files", DataTable)
        position = self.data_table_position(table)
        table.clear()
        self.query_one("#file-path", Static).update(f"Path: {path}")
        if ".." in entry_map:
            table.add_row("DIR", "..", "", "", key="..")
        for entry in entries:
            if not isinstance(entry, dict):
                continue
            entry_path = str(entry.get("path") or entry.get("name") or "")
            if not entry_path:
                continue
            entry_map[entry_path] = entry
            table.add_row(
                self.file_entry_type(entry),
                str(entry.get("name") or entry_path),
                self.format_file_size(entry.get("size")),
                self.format_file_mtime(entry.get("mtime")),
                key=entry_path,
            )
        error = payload.get("error") if isinstance(payload.get("error"), dict) else None
        if error:
            self.set_file_preview_text(self.format_file_error(error))
        else:
            self.set_file_preview_text(
                f"Agent: {agent_id}\n"
                f"Cwd: {payload.get('cwd') or '-'}\n"
                f"Path: {path}\n"
                f"Entries: {len(entries)}\n\n"
                "Select a directory to browse it or a file to preview it."
            )
        self.restore_data_table_position(table, position)

    def set_file_preview_text(self, text: str) -> None:
        preview = self.query_one("#file-preview", RichLog)
        preview.clear()
        preview.write(text)
        preview.scroll_home(animate=False, immediate=True)

    def set_file_preview_payload(self, payload: dict[str, Any]) -> None:
        preview = self.query_one("#file-preview", RichLog)
        preview.clear()
        for renderable in self.format_file_preview_renderables(payload):
            preview.write(renderable)
        preview.scroll_home(animate=False, immediate=True)

    def file_entry_type(self, entry: dict[str, Any]) -> str:
        if entry.get("kind") == "directory":
            return "DIR"
        if entry.get("is_gif"):
            return "GIF"
        if entry.get("is_image"):
            return "IMG"
        if entry.get("is_text"):
            return "TXT"
        return "BIN" if entry.get("kind") == "file" else "OTHER"

    def format_file_preview_renderables(
        self,
        payload: dict[str, Any],
    ) -> list[str | Text]:
        ansi_preview = str(payload.get("image_preview_ansi") or "").rstrip()
        if not payload.get("is_image") or not ansi_preview:
            return [self.format_file_preview(payload)]
        lines = self.format_file_preview_header(payload)
        lines.extend(
            [
                f"Image: {'GIF' if payload.get('is_gif') else 'yes'}",
                f"Dimensions: {self.format_image_dimensions(payload)}",
                "",
                self.image_preview_label(payload, color=True),
            ]
        )
        text = Text("\n".join(lines) + "\n")
        text.append(Text.from_ansi(ansi_preview))
        if payload.get("truncated"):
            text.append("\n\n[Preview truncated]")
        return [text]

    def format_file_preview(self, payload: dict[str, Any]) -> str:
        error = payload.get("error") if isinstance(payload.get("error"), dict) else None
        if error:
            return self.format_file_error(error)
        lines = self.format_file_preview_header(payload)
        if payload.get("is_image"):
            dimensions = self.format_image_dimensions(payload)
            lines.extend(
                [
                    f"Image: {'GIF' if payload.get('is_gif') else 'yes'}",
                    f"Dimensions: {dimensions}",
                ]
            )
            preview = str(payload.get("image_preview") or "").rstrip()
            if preview:
                lines.extend(["", self.image_preview_label(payload), preview])
                if payload.get("truncated"):
                    lines.extend(["", "[Preview truncated]"])
                return "\n".join(lines)
            lines.extend(["", "Image preview is metadata-only."])
            return "\n".join(lines)
        text = payload.get("text")
        if text is not None:
            lines.extend(["", str(text)])
            if payload.get("truncated"):
                lines.extend(["", "[Preview truncated]"])
            return "\n".join(lines)
        lines.extend(["", "Binary preview is not available."])
        return "\n".join(lines)

    def format_file_preview_header(self, payload: dict[str, Any]) -> list[str]:
        return [
            f"Path: {payload.get('path') or '-'}",
            f"Type: {self.file_entry_type(payload)}",
            f"Size: {self.format_file_size(payload.get('size'))}",
            f"Modified: {self.format_file_mtime(payload.get('mtime'))}",
            f"MIME: {payload.get('mime_type') or '-'}",
        ]

    def image_preview_label(self, payload: dict[str, Any], *, color: bool = False) -> str:
        base = "GIF Preview (first frame)" if payload.get("is_gif") else "Image Preview"
        return f"{base} (color)" if color else base

    def format_file_error(self, error: dict[str, Any]) -> str:
        lines = [
            "Files unavailable",
            f"Code: {error.get('code', 'FILE_ERROR')}",
            f"Message: {error.get('message', '')}",
        ]
        remediation = error.get("remediation")
        if remediation:
            lines.append(f"Remediation: {remediation}")
        return "\n".join(lines)

    def format_image_dimensions(self, payload: dict[str, Any]) -> str:
        width = payload.get("image_width")
        height = payload.get("image_height")
        if width and height:
            return f"{width}x{height}"
        return "-"

    def format_file_size(self, value: Any) -> str:
        if value is None:
            return ""
        try:
            size = int(value)
        except (TypeError, ValueError):
            return ""
        units = ["B", "KiB", "MiB", "GiB"]
        amount = float(size)
        for unit in units:
            if amount < 1024 or unit == units[-1]:
                return f"{amount:.1f} {unit}" if unit != "B" else f"{size} B"
            amount /= 1024
        return f"{size} B"

    def format_file_mtime(self, value: Any) -> str:
        if value is None:
            return ""
        try:
            timestamp = float(value)
        except (TypeError, ValueError):
            return ""
        return datetime.fromtimestamp(timestamp, timezone.utc).strftime("%Y-%m-%d %H:%M")

